// Data grammar-n1 — dihasilkan otomatis (lihat scripts/fetch-data.mjs).
export default [{"pattern":"A うが B うが","meaning":"Expresses the idea of 'no matter how... or', 'even if... or'.","formation":"Verb-volitional form + うが + Verb-volitional form + うが, or Adjective (-かろう) + が + Adjective (-かろう) + が","examples":[{"jp":"朝早かろうが夜遅かろうが、いつもバスが遅れる。","en":"No matter whether it's early morning or late at night, the bus is always late.","romaji":"Asa hayakarou ga yoru osokarou ga, itsumo basu ga okureru."},{"jp":"彼に話そうが話すまいが、結果は変わらない。","en":"Even if I talk to him or don't, the outcome won't change.","romaji":"Kare ni hanasou ga hanasu maiga, kekka wa kawaranai."},{"jp":"この仕事をしようがしまいが、給料は同じだ。","en":"Whether I do this job or not, the salary is the same.","romaji":"Kono shigoto o shiyou ga shimai ga, kyuuryou wa onaji da."},{"jp":"あの人に話そうが話すまいが、理解してくれるとは思えない。","en":"I don't think that person would understand whether I talk to them or not.","romaji":"Ano hito ni hanasou ga hanasu maiga, rikai shite kureru to wa omoenai."}],"example":"朝早かろうが夜遅かろうが、いつもバスが遅れる。","exampleMeaning":"No matter whether it's early morning or late at night, the bus is always late."},{"pattern":"A うと B うと","meaning":"Shows that the speaker is indifferent to both conditions; 'whether A or B'.","formation":"い-adjective (-かろう) + と, な-adjective / Noun + であろうと","examples":[{"jp":"雨が降ろうと晴れようと、私は毎日ジョギングをします。","en":"Whether it's raining or sunny, I jog every day.","romaji":"Ame ga furou to hareyou to, watashi wa mainichi jogingu o shimasu."},{"jp":"試験が難しかろうと易しかろうと、一生懸命勉強します。","en":"Whether the exam is difficult or easy, I will study hard.","romaji":"Shiken ga muzukashikarou to yasashikarou to, isshoukenmei benkyou shimasu."},{"jp":"彼が学生であろうと社会人であろうと、私は彼を尊敬しています。","en":"Whether he's a student or a working adult, I respect him.","romaji":"Kare ga gakusei de arou to shakaijin de arou to, watashi wa kare o sonkei shiteimasu."},{"jp":"その映画が新しいであろうと古いであろうと、面白ければ観ます。","en":"Whether the movie is new or old, if it's interesting, I'll watch it.","romaji":"Sono eiga ga atarashii de arou to furui de arou to, omoshirokereba mimasu."}],"example":"雨が降ろうと晴れようと、私は毎日ジョギングをします。","exampleMeaning":"Whether it's raining or sunny, I jog every day."},{"pattern":"A かたわら B","meaning":"Expresses 'while also', 'at the same time as'.","formation":"Verb-dictionary form + かたわら, Noun + のかたわら","examples":[{"jp":"彼は仕事をするかたわら、大学に通っている。","en":"While working, he also attends university.","romaji":"Kare wa shigoto o suru katawara, daigaku ni kayotte iru."},{"jp":"私は学生のかたわら、レストランでアルバイトをしている。","en":"While being a student, I work part-time at a restaurant.","romaji":"Watashi wa gakusei no katawara, resutoran de arubaito o shite iru."},{"jp":"彼女は医者のかたわら、趣味で絵を描いている。","en":"While being a doctor, she paints as a hobby.","romaji":"Kanojo wa isha no katawara, shumi de e o kaite iru."},{"jp":"彼は仕事をするかたわら、ボランティア活動にも積極的に参加している。","en":"While doing his job, he also actively participates in volunteer work.","romaji":"Kare wa shigoto o suru katawara, borantia katsudou ni mo sekkyokuteki ni sanka shite iru."}],"example":"彼は仕事をするかたわら、大学に通っている。","exampleMeaning":"While working, he also attends university."},{"pattern":"A かれ B かれ","meaning":"Expresses 'whether A or B'; both situations are included.","formation":"Commonly i-adjective stems + かれ + i-adjective stems + かれ (e.g. 早かれ遅かれ). Also sometimes Noun + かれ + Noun + かれ in older usage.","examples":[{"jp":"冬かれ夏かれ、毎日ジョギングする。","en":"Whether it's winter or summer, I jog every day.","romaji":"Fuyu kare natsu kare, mainichi jogingu suru."},{"jp":"彼が来るかれ来ないかれ、パーティーは始める。","en":"Whether he comes or not, the party will start.","romaji":"Kare ga kuru kare konai kare, paatii wa hajimeru."},{"jp":"勝つかれ負けるかれ、試合に出ることが大事だ。","en":"Whether we win or lose, it's important to take part in the match.","romaji":"Katsu kare makeru kare, shiai ni deru koto ga daiji da."},{"jp":"雨かれ雪かれ、犬の散歩は欠かさない。","en":"Whether it's raining or snowing, I never skip walking the dog.","romaji":"Ame kare yuki kare, inu no sanpo wa kakasanai."}],"example":"冬かれ夏かれ、毎日ジョギングする。","exampleMeaning":"Whether it's winter or summer, I jog every day."},{"pattern":"A だの B だの","meaning":"Used to list examples (often with a critical or complaining tone); 'things like A, B, etc.'.","formation":"Noun/Verb casual + だの + Noun/Verb casual + だの","examples":[{"jp":"彼はいつも遅刻だの、仕事を忘れるだので困る。","en":"I'm troubled because he's always late, forgets work, and so on.","romaji":"Kare wa itsumo chikoku dano, shigoto o wasureru dano de komaru."},{"jp":"彼女は新しい服だの、化粧品だのによくお金を使います。","en":"She often spends money on new clothes, cosmetics, and so on.","romaji":"Kanojo wa atarashii fuku dano, keshouhin dano ni yoku okane o tsukaimasu."},{"jp":"彼が言うには、音楽だの映画だの本だのが好きらしい。","en":"He says he likes music, movies, books, and so on.","romaji":"Kare ga iu ni wa, ongaku dano, eiga dano, hon dano ga suki rashii."},{"jp":"子供にはお菓子だの、おもちゃだの、好きなものを限りなく与えてあげたい。","en":"I want to give children all the things they like, such as sweets and toys, without limit.","romaji":"Kodomo ni wa okashi dano, omocha dano, suki na mono o kagirinaku ataete agetai."}],"example":"彼はいつも遅刻だの、仕事を忘れるだので困る。","exampleMeaning":"I'm troubled because he's always late, forgets work, and so on."},{"pattern":"A であれ B であれ","meaning":"Indicates the same statement applies to both A and B; 'whether A or B'.","formation":"Noun A + であれ + Noun B + であれ","examples":[{"jp":"雨であれ雪であれ、試合は中止にならない。","en":"Whether it's rain or snow, the match will not be canceled.","romaji":"Ame deare yuki deare, shiai wa chuushi ni naranai."},{"jp":"男であれ女であれ、平等に扱われるべきだ。","en":"Whether man or woman, everyone should be treated equally.","romaji":"Otoko deare onna deare, byoudou ni atsukawareru beki da."},{"jp":"豊かであれ貧乏であれ、真の幸福は金では買えない。","en":"Whether rich or poor, true happiness can't be bought with money.","romaji":"Yutaka deare binbou deare, shin no shiawase wa kane de wa kaenai."},{"jp":"経験者であれ初心者であれ、このゲームは楽しめる。","en":"Whether you're a veteran or a beginner, you can enjoy this game.","romaji":"Keikensha deare shoshinsha deare, kono geemu wa tanoshimeru."}],"example":"雨であれ雪であれ、試合は中止にならない。","exampleMeaning":"Whether it's rain or snow, the match will not be canceled."},{"pattern":"A というか B というか","meaning":"Means 'rather than say A, it's more like B', or 'whether to call it A or B'.","formation":"Phrase A + というか + Phrase B + というか","examples":[{"jp":"彼は無礼というか、直接的というか、とにかくはっきりしている。","en":"He's rather rude, or maybe just direct; in any case, he is very blunt.","romaji":"Kare wa burei to iu ka, chokusetsuteki to iu ka, tonikaku hakkiri shite iru."},{"jp":"この映画は面白いというか、変というか、とにかく不思議な雰囲気がある。","en":"This movie is interesting or maybe strange; anyway, it has a mysterious vibe.","romaji":"Kono eiga wa omoshiroi to iu ka, hen to iu ka, tonikaku fushigi na fun'iki ga aru."},{"jp":"彼の絵は素晴らしいというか、驚くべきというか、本当に見る価値がある。","en":"His paintings are wonderful, or perhaps astonishing; they're definitely worth seeing.","romaji":"Kare no e wa subarashii to iu ka, odoroku beki to iu ka, hontou ni miru kachi ga aru."},{"jp":"彼女の服はかわいいというか、派手というか、とにかく人目を引く。","en":"Her outfit is cute or maybe flashy; in any case, it grabs people's attention.","romaji":"Kanojo no fuku wa kawaii to iu ka, hade to iu ka, tonikaku hitome o hiku."}],"example":"彼は無礼というか、直接的というか、とにかくはっきりしている。","exampleMeaning":"He's rather rude, or maybe just direct; in any case, he is very blunt."},{"pattern":"A とも B とも","meaning":"Expresses two possibilities; 'either A or B', 'whether A or B'.","formation":"Noun + とも + Noun + とも (or sometimes Verb forms for each A, B)","examples":[{"jp":"決断とも誤りとも、結果は時間が教えてくれるでしょう。","en":"Whether it's a wise decision or a mistake, time will show the result.","romaji":"Ketsudan tomo ayamari tomo, kekka wa jikan ga oshiete kureru deshou."},{"jp":"彼は父とも兄とも、もう何年も話していない。","en":"He hasn't spoken to either his father or his brother in years.","romaji":"Kare wa chichi tomo ani tomo, mou nannen mo hanashite inai."},{"jp":"彼女とも友達とも映画を見に行くつもりです。","en":"I plan to go watch a movie either with my girlfriend or a friend.","romaji":"Kanojo tomo tomodachi tomo eiga o mi ni iku tsumori desu."},{"jp":"このゲームには時間とも努力とも言えないほどの根気が必要です。","en":"This game requires a kind of persistence beyond just time or effort.","romaji":"Kono geemu ni wa jikan tomo doryoku tomo ienai hodo no konki ga hitsuyou desu."}],"example":"決断とも誤りとも、結果は時間が教えてくれるでしょう。","exampleMeaning":"Whether it's a wise decision or a mistake, time will show the result."},{"pattern":"A にしろ B にしろ","meaning":"Means 'whether it is A or B'; 'regardless of A or B'.","formation":"Noun A + にしろ + Noun B + にしろ, or Verb-casual A + にしろ + Verb-casual B + にしろ","examples":[{"jp":"暑いにしろ寒いにしろ、毎日運動するべきです。","en":"Whether it's hot or cold, you should exercise every day.","romaji":"Atsui ni shiro samui ni shiro, mainichi undou suru beki desu."},{"jp":"合格するにしろ不合格になるにしろ、最善を尽くしました。","en":"Whether I pass or fail, I did my best.","romaji":"Goukaku suru ni shiro fukougaku ni naru ni shiro, saizen o tsukushimashita."},{"jp":"忙しいにしろ暇にしろ、時間を大切にすべきです。","en":"Whether you're busy or free, you should value your time.","romaji":"Isogashii ni shiro hima ni shiro, jikan o taisetsu ni subeki desu."},{"jp":"大きいにしろ小さいにしろ、その箱は全部ここに運んでください。","en":"Whether they're large or small, please move all those boxes here.","romaji":"Ookii ni shiro chiisai ni shiro, sono hako wa zenbu koko ni hakonde kudasai."}],"example":"暑いにしろ寒いにしろ、毎日運動するべきです。","exampleMeaning":"Whether it's hot or cold, you should exercise every day."},{"pattern":"A にせよ B にせよ","meaning":"Either A or B; Regardless of whether it's A or B.","formation":"Noun + にせよ + Noun + にせよ (also works with verbs in dictionary form + にせよ)","examples":[{"jp":"雨にせよ雪にせよ、試合は中止しない。","en":"Whether it's rain or snow, the match won't be cancelled.","romaji":"Ame ni seyo yuki ni seyo, shiai wa chuushi shinai."},{"jp":"彼にせよ彼女にせよ、誰か一人が行くべきだ。","en":"Whether it's him or her, someone should go.","romaji":"Kare ni seyo kanojo ni seyo, dareka hitori ga iku beki da."},{"jp":"成果にせよ努力にせよ、どちらも重要だ。","en":"Whether it's results or effort, both are important.","romaji":"Seika ni seyo doryoku ni seyo, dochira mo juuyou da."},{"jp":"春にせよ秋にせよ、私は花が好きだ。","en":"Whether it's spring or fall, I like flowers.","romaji":"Haru ni seyo aki ni seyo, watashi wa hana ga suki da."}],"example":"雨にせよ雪にせよ、試合は中止しない。","exampleMeaning":"Whether it's rain or snow, the match won't be cancelled."},{"pattern":"A につけ B につけ","meaning":"Expresses 'whether... or...', 'both... and...', 'in either case'.","formation":"Phrase A (dictionary/adjective form) + につけ、Phrase B (dictionary/adjective form) + につけ","examples":[{"jp":"彼には笑うにつけ泣くにつけ、とても魅力的だ。","en":"He is very charming whether he’s laughing or crying.","romaji":"Kare ni wa warau ni tsuke naku ni tsuke, totemo miryokuteki da."},{"jp":"嬉しいにつけ悲しいにつけ、彼はいつも音楽を聴いている。","en":"Whether he's happy or sad, he's always listening to music.","romaji":"Ureshii ni tsuke kanashii ni tsuke, kare wa itsumo ongaku o kiite iru."},{"jp":"日中につけ夜間につけ、この景色は美しい。","en":"This view is beautiful whether it's daytime or nighttime.","romaji":"Nitchuu ni tsuke yakan ni tsuke, kono keishiki wa utsukushii."},{"jp":"喜びにつけ悲しみにつけ、彼女はいつも私を支えてくれる。","en":"Whether I’m joyful or sorrowful, she always supports me.","romaji":"Yorokobi ni tsuke kanashimi ni tsuke, kanojo wa itsumo watashi o sasaete kureru."}],"example":"彼には笑うにつけ泣くにつけ、とても魅力的だ。","exampleMeaning":"He is very charming whether he’s laughing or crying."},{"pattern":"A のやら B のやら","meaning":"Used when the speaker is unsure or confused between multiple possibilities.","formation":"Noun1 + のやら + Noun2 + のやら (also works with adjectives and verbs + のやら)","examples":[{"jp":"彼が怒っているのやら、悲しいのやら、私には分からない。","en":"I don't know whether he's angry or sad.","romaji":"Kare ga okotte iru no yara, kanashii no yara, watashi ni wa wakaranai."},{"jp":"試験の結果が良いのやら悪いのやら、気になって仕方がない。","en":"I can’t help worrying whether my exam results are good or bad.","romaji":"Shiken no kekka ga yoi no yara warui no yara, ki ni natte shikata ga nai."},{"jp":"彼女が私を好きなのやら嫌いなのやら、わからない。","en":"I don’t know whether she likes me or hates me.","romaji":"Kanojo ga watashi o suki na no yara kirai na no yara, wakaranai."},{"jp":"彼が本当に行くのやら行かないのやら、はっきりしない。","en":"It’s unclear whether he will really go or not.","romaji":"Kare ga hontou ni iku no yara ikanai no yara, hakkiri shinai."}],"example":"彼が怒っているのやら、悲しいのやら、私には分からない。","exampleMeaning":"I don't know whether he's angry or sad."},{"pattern":"Noun1 が Noun1 なら、 Noun2 も Noun2 だ (A ga A nara, B mo B da)","meaning":"Indicates a parallel or matching situation; 'if Noun1 is (truly) Noun1, then Noun2 is also Noun2'.","formation":"Noun1 + が + (repeat Noun1) + なら、Noun2 + も + (repeat Noun2) + だ","examples":[{"jp":"鬼が鬼なら、人間も人間だ。","en":"If demons are indeed demons, humans are likewise humans.","romaji":"Oni ga oni nara, ningen mo ningen da."},{"jp":"彼が社長なら、私も社長だ。","en":"If he is the president, then I'm the president too.","romaji":"Kare ga shachou nara, watashi mo shachou da."},{"jp":"貴様が戦士なら、俺も戦士だ。","en":"If you're a warrior, then I'm a warrior as well.","romaji":"Kisama ga senshi nara, ore mo senshi da."},{"jp":"ハムスターがペットなら、猫もペットだ。","en":"If a hamster counts as a pet, then a cat is also a pet.","romaji":"Hamusutā ga petto nara, neko mo petto da."}],"example":"鬼が鬼なら、人間も人間だ。","exampleMeaning":"If demons are indeed demons, humans are likewise humans."},{"pattern":"Noun1 も Noun1 なら、Noun2 も Noun2 だ (A mo A nara, B mo B da)","meaning":"Highlights two parallel facts or characteristics; 'if it’s said that ~, then it can also be said that ~'.","formation":"Noun1 + も + (repeat Noun1) + なら、Noun2 + も + (repeat Noun2) + だ","examples":[{"jp":"君も君なら、私も私だ。","en":"If you are you, then I am also me.","romaji":"Kimi mo kimi nara, watashi mo watashi da."},{"jp":"夏も夏なら、冬も冬だ。","en":"If it’s said that summer is summer, then winter is also winter.","romaji":"Natsu mo natsu nara, fuyu mo fuyu da."},{"jp":"東京も東京なら、大阪も大阪だ。","en":"If Tokyo is Tokyo, then Osaka is also Osaka (they each have their distinctive qualities).","romaji":"Toukyou mo toukyou nara, Oosaka mo Oosaka da."},{"jp":"犬も犬なら、猫も猫だ。","en":"If dogs are dogs, then cats are also cats.","romaji":"Inu mo inu nara, neko mo neko da."}],"example":"君も君なら、私も私だ。","exampleMeaning":"If you are you, then I am also me."},{"pattern":"Noun + あっての + Noun","meaning":"Expresses 'B cannot exist without A'; 'B only exists because of A'.","formation":"Noun1 + あっての + Noun2","examples":[{"jp":"家族あっての私です。","en":"I am who I am thanks to my family.","romaji":"Kazoku atte no watashi desu."},{"jp":"お客様あってのビジネスです。","en":"A business is nothing without its customers.","romaji":"Okyakusama atte no bijinesu desu."},{"jp":"練習あっての成功です。","en":"Success is nothing without practice.","romaji":"Renshuu atte no seikou desu."},{"jp":"健康あっての仕事です。","en":"Work is nothing without your health.","romaji":"Kenkou atte no shigoto desu."}],"example":"家族あっての私です。","exampleMeaning":"I am who I am thanks to my family."},{"pattern":"Noun かたがた","meaning":"Do one thing while also doing another; 'while', 'and at the same time'.","formation":"Noun + かたがた","examples":[{"jp":"東京へ出張のかたがた、友人に会いに行った。","en":"While on a business trip to Tokyo, I also went to see a friend.","romaji":"Toukyou e shucchou no kata gata, yuujin ni ai ni itta."},{"jp":"観光のかたがた、お土産を買いました。","en":"While sightseeing, I bought some souvenirs.","romaji":"Kankou no kata gata, omiyage o kaimashita."},{"jp":"散歩のかたがた、ゴミを拾った。","en":"While taking a walk, I also picked up trash.","romaji":"Sanpo no kata gata, gomi o hirotta."},{"jp":"学習のかたがた、音楽を聞いた。","en":"While studying, I also listened to music.","romaji":"Gakushuu no kata gata, ongaku o kiita."}],"example":"東京へ出張のかたがた、友人に会いに行った。","exampleMeaning":"While on a business trip to Tokyo, I also went to see a friend."},{"pattern":"Noun がてら","meaning":"Means 'while...at the same time', 'on the occasion of', or 'along with'.","formation":"Noun + がてら","examples":[{"jp":"散歩がてらに、近くの公園で花を摘みました。","en":"While taking a walk, I picked some flowers in the nearby park.","romaji":"Sanpo gatera ni, chikaku no kouen de hana o tsumimashita."},{"jp":"買い物がてら、友達に会いに行きました。","en":"While I was out shopping, I went to see a friend.","romaji":"Kaimono gatera, tomodachi ni ai ni ikimashita."},{"jp":"彼女は旅行がてら、新しい言語を勉強しました。","en":"She studied a new language while traveling.","romaji":"Kanojo wa ryokou gatera, atarashii gengo o benkyou shimashita."},{"jp":"ドライブがてら、新しいアルバムを聞きました。","en":"I listened to a new album while going for a drive.","romaji":"Doraibu gatera, atarashii arubamu o kikimashita."}],"example":"散歩がてらに、近くの公園で花を摘みました。","exampleMeaning":"While taking a walk, I picked some flowers in the nearby park."},{"pattern":"Noun からある (〜kara aru)","meaning":"Used with large numbers or measurements to emphasize 'at least that many' or 'no less than.'","formation":"Number + Counter + からある","examples":[{"jp":"彼のコレクションは500個からある。","en":"He has at least 500 items in his collection.","romaji":"Kare no korekushon wa gohyaku ko kara aru."},{"jp":"このビルは40階からある。","en":"This building has at least 40 floors.","romaji":"Kono biru wa yonjuu kai kara aru."},{"jp":"彼の財産は10億円からある。","en":"He has assets worth at least one billion yen.","romaji":"Kare no zaisan wa juu oku en kara aru."},{"jp":"このマラソンは10kmからある。","en":"This marathon is at least 10 kilometers long.","romaji":"Kono marason wa juu kiro kara aru."}],"example":"彼のコレクションは500個からある。","exampleMeaning":"He has at least 500 items in his collection."},{"pattern":"Noun からする","meaning":"Used to indicate that something is judged, estimated, or considered from a certain point or aspect.","formation":"Noun + からする","examples":[{"jp":"彼の態度からすると、彼はその計画に反対しているようだ。","en":"Judging from his attitude, he seems to be against the plan.","romaji":"Kare no taido kara suru to, kare wa sono keikaku ni hantai shiteiru you da."},{"jp":"このレストランの雰囲気からすると、料理もすばらしいはずだ。","en":"Judging from the atmosphere of this restaurant, the food must be wonderful.","romaji":"Kono resutoran no fun'iki kara suru to, ryouri mo subarashii hazu da."},{"jp":"彼女の成績からすると、彼女は非常に勉強熱心な人でしょう。","en":"Judging from her grades, she must be a very diligent student.","romaji":"Kanojo no seiseki kara suru to, kanojo wa hijou ni benkyou nesshin na hito deshou."},{"jp":"その会社の成長率からすると、将来的には大きな利益を得られるでしょう。","en":"From the company's growth rate, it seems likely to gain substantial profits in the future.","romaji":"Sono kaisha no seicho-ritsu kara suru to, shouraiteki ni wa ooki na rieki o erareru deshou."}],"example":"彼の態度からすると、彼はその計画に反対しているようだ。","exampleMeaning":"Judging from his attitude, he seems to be against the plan."},{"pattern":"Noun からの","meaning":"Defines the starting point or the origin; 'from'.","formation":"Noun + からの","examples":[{"jp":"日本からの手紙を受け取りました。","en":"I received a letter from Japan.","romaji":"Nihon kara no tegami wo uketorimashita."},{"jp":"彼は東京からの旅行者です。","en":"He is a traveler from Tokyo.","romaji":"Kare wa Tokyo kara no ryokousha desu."},{"jp":"昨日、母からの電話がありました。","en":"Yesterday, I got a call from my mother.","romaji":"Kinou, haha kara no denwa ga arimashita."},{"jp":"彼女は大学からの友人です。","en":"She is a friend from college.","romaji":"Kanojo wa daigaku kara no yuujin desu."}],"example":"日本からの手紙を受け取りました。","exampleMeaning":"I received a letter from Japan."},{"pattern":"Noun から言わせれば","meaning":"Express the perspective of the noun; 'from ~'s point of view.'","formation":"Noun + から言わせれば","examples":[{"jp":"先生から言わせれば、毎日勉強するべきだ。","en":"From the teacher's point of view, you should study every day.","romaji":"Sensei kara iwasereba, mainichi benkyou suru beki da."},{"jp":"子供たちから言わせれば、もっと遊ぶ時間がほしい。","en":"From the children's perspective, they want more time to play.","romaji":"Kodomo-tachi kara iwasereba, motto asobu jikan ga hoshii."},{"jp":"僕から言わせれば、そのプランは実行可能だ。","en":"From my point of view, that plan is feasible.","romaji":"Boku kara iwasereba, sono puran wa jikkou kanou da."},{"jp":"犬から言わせれば、もっと散歩したいはずだ。","en":"If the dog could talk, it would probably want more walks.","romaji":"Inu kara iwasereba, motto sanpo shitai hazu da."}],"example":"先生から言わせれば、毎日勉強するべきだ。","exampleMeaning":"From the teacher's point of view, you should study every day."},{"pattern":"Noun + ぐるみ (〜gurumi)","meaning":"Describes 'entirely', 'all together', or 'as a whole group'.","formation":"Noun + ぐるみ","examples":[{"jp":"家族ぐるみで旅行に行きました。","en":"We went on a trip with the whole family.","romaji":"Kazoku gurumi de ryokou ni ikimashita."},{"jp":"クラスぐるみで遠足に行きました。","en":"The entire class went on an excursion.","romaji":"Kurasu gurumi de ensoku ni ikimashita."},{"jp":"この国は国民ぐるみでその法案を支持しています。","en":"The entire population of the country supports that bill.","romaji":"Kono kuni wa kokumin gurumi de sono houan wo shiji shiteimasu."},{"jp":"彼は友人ぐるみでそのクラブに参加した。","en":"He joined the club along with all of his friends.","romaji":"Kare wa yuujin gurumi de sono kurabu ni sanka shita."}],"example":"家族ぐるみで旅行に行きました。","exampleMeaning":"We went on a trip with the whole family."},{"pattern":"Noun こそあれ","meaning":"Expresses 'though there is ... (some negative or burdensome aspect), still ...'.","formation":"Noun + こそあれ + (result/continuation)","examples":[{"jp":"問題こそあれ、プロジェクトは順調に進んでいます。","en":"Though there are problems, the project is progressing smoothly.","romaji":"Mondai koso are, purojekuto wa junchou ni susunde imasu."},{"jp":"多少のリスクこそあれ、挑戦する価値はある。","en":"Though there is some risk, it's worth taking on the challenge.","romaji":"Tashou no risuku koso are, chousen suru kachi wa aru."},{"jp":"欠点こそあれ、彼の提案は興味深い。","en":"Though it has flaws, his proposal is intriguing.","romaji":"Ketten koso are, kare no teian wa kyoumibukai."},{"jp":"不安こそあれ、今が行動するときだ。","en":"Though there is anxiety, now is the time to act.","romaji":"Fuan koso are, ima ga koudou suru toki da."}],"example":"問題こそあれ、プロジェクトは順調に進んでいます。","exampleMeaning":"Though there are problems, the project is progressing smoothly."},{"pattern":"Noun こそ～が","meaning":"Emphasizes that 'it is precisely Noun that ...', then adds a contrasting or additional point.","formation":"Noun + こそ + (statement) + が + (contrasting/additional statement)","examples":[{"jp":"お金こそ必要だが、それだけが人生のすべてではない。","en":"Money is indeed necessary, but it isn't everything in life.","romaji":"Okane koso hitsuyou da ga, sore dake ga jinsei no subete de wa nai."},{"jp":"努力こそ大事だが、結果も見逃せない。","en":"Effort is certainly crucial, but results also matter.","romaji":"Doryoku koso daiji da ga, kekka mo minogasenai."},{"jp":"健康こそ宝だが、ときには仕事を優先せざるを得ない。","en":"Health is indeed a treasure, but sometimes you have to prioritize work.","romaji":"Kenkou koso takara da ga, toki ni wa shigoto o yuusen sezaru wo enai."},{"jp":"愛こそ力だが、表現するのは難しい。","en":"Love is certainly a powerful force, but it's difficult to express.","romaji":"Ai koso chikara da ga, hyougen suru no wa muzukashii."}],"example":"お金こそ必要だが、それだけが人生のすべてではない。","exampleMeaning":"Money is indeed necessary, but it isn't everything in life."},{"pattern":"Noun こそすれ","meaning":"An emphatic pattern meaning 'it may be X, but definitely not Y.' Often pairs with a negative statement.","formation":"Noun + こそすれ + (negative or contrasting statement)","examples":[{"jp":"感謝こそすれ、非難などできません。","en":"I might feel grateful, but I could never criticize.","romaji":"Kansha koso sure, hinan nado dekimasen."},{"jp":"忙しさこそすれ、退屈することはありません。","en":"I may be busy, but I'm never bored.","romaji":"Isogashisa koso sure, taikutsu suru koto wa arimasen."},{"jp":"後悔こそすれ、忘れることはできない。","en":"I might regret it, but I can't forget it.","romaji":"Koukai koso sure, wasureru koto wa dekinai."},{"jp":"疑問こそすれ、賛成はできない。","en":"I may have doubts, but I cannot agree.","romaji":"Gimon koso sure, sansei wa dekinai."}],"example":"感謝こそすれ、非難などできません。","exampleMeaning":"I might feel grateful, but I could never criticize."},{"pattern":"Noun ごとき / Noun ごとく (〜gotoki/〜gotoku)","meaning":"Means 'like a...', 'as if...', expressing a simile or metaphor.","formation":"Noun + ごとき, Noun + ごとく, Verb-casual + ごとく, い-Adjective + ごとく","examples":[{"jp":"彼は天使のごとく純粋だ。","en":"He is as pure as an angel.","romaji":"Kare wa tenshi no gotoku junsui da."},{"jp":"悪魔のごとき行為をするな。","en":"Don't engage in acts like those of a devil.","romaji":"Akuma no gotoki koui o suru na."},{"jp":"彼女は雪のごとく白い肌をしている。","en":"She has skin as white as snow.","romaji":"Kanojo wa yuki no gotoku shiroi hada o shiteiru."},{"jp":"彼は風のごとく去った。","en":"He left like the wind.","romaji":"Kare wa kaze no gotoku satta."}],"example":"彼は天使のごとく純粋だ。","exampleMeaning":"He is as pure as an angel."},{"pattern":"Noun じゃあるまいし","meaning":"Expressing that something 'is not'; 'it's not like...'. Colloquial/masculine form of ではあるまいし.","formation":"Noun or Na-Adjective + じゃあるまいし","examples":[{"jp":"彼は子供じゃあるまいし、その問題をしっかりと解決するべきだ。","en":"He’s not a child, so he should solve that problem properly.","romaji":"Kare wa kodomo ja aru mai shi, sono mondai o shikkari to kaiketsu suru beki da."},{"jp":"急ぐ必要はない、時間じゃあるまいし。","en":"We don’t need to hurry; it’s not like we’re short of time.","romaji":"Isogu hitsuyou wa nai, jikan ja aru mai shi."},{"jp":"監督じゃあるまいし、試合の結果について心配するな。","en":"You’re not the coach, so don’t worry about the game results.","romaji":"Kantoku ja aru mai shi, shiai no kekka ni tsuite shinpai suru na."},{"jp":"飴じゃあるまいし、そのまま飲み込んでも大丈夫だよ。","en":"It’s not candy, so it’s okay to just swallow it.","romaji":"Ame ja aru mai shi, sono mama nomikonde mo daijoubu da yo."}],"example":"彼は子供じゃあるまいし、その問題をしっかりと解決するべきだ。","exampleMeaning":"He’s not a child, so he should solve that problem properly."},{"pattern":"Noun ずくめ","meaning":"Denotes 'entirely' or 'nothing but' the preceding noun.","formation":"Noun + ずくめ","examples":[{"jp":"彼は最近、失敗ずくめだ。","en":"He has had nothing but failures recently.","romaji":"Kare wa saikin, shippai zukume da."},{"jp":"この冬は雪ずくめで大変だ。","en":"This winter has been nothing but snow, which is tough.","romaji":"Kono fuyu wa yuki zukume de taihen da."},{"jp":"彼の話は嘘ずくめだった。","en":"His story was full of nothing but lies.","romaji":"Kare no hanashi wa uso zukume datta."},{"jp":"今日の仕事は忙しさずくめだった。","en":"Today's work was nothing but constant busyness.","romaji":"Kyou no shigoto wa isogashisa zukume datta."}],"example":"彼は最近、失敗ずくめだ。","exampleMeaning":"He has had nothing but failures recently."},{"pattern":"Noun だけではすまない","meaning":"Expresses 'it can't be settled with just...', 'cannot be resolved merely by...'.","formation":"Noun + だけではすまない","examples":[{"jp":"この問題は謝罪だけではすまない。","en":"This problem cannot be settled with just an apology.","romaji":"Kono mondai wa shazai dake dewa sumanai."},{"jp":"彼女が怒っているから、お菓子をあげただけではすまないよ。","en":"She’s angry, so just giving her sweets won't fix it.","romaji":"Kanojo ga okotte iru kara, okashi o ageta dake dewa sumanai yo."},{"jp":"このプロジェクトの成功は努力だけではすまない。","en":"Success on this project cannot be achieved with mere effort.","romaji":"Kono purojekuto no seikou wa doryoku dake dewa sumanai."},{"jp":"資金調達だけではすまない、実際のビジネスプランも必要だ。","en":"We can’t just finish with fundraising; we also need a real business plan.","romaji":"Shikin choutatsu dake dewa sumanai, jissai no bijinesu puran mo hitsuyou da."}],"example":"この問題は謝罪だけではすまない。","exampleMeaning":"This problem cannot be settled with just an apology."},{"pattern":"Noun たりとも～ない","meaning":"Used to show a strong negative: 'not even ~', 'not a single ~'.","formation":"Noun + たりとも + Negative Verb","examples":[{"jp":"一分たりとも無駄にするな。","en":"Don’t waste even a single minute.","romaji":"Ippun tari tomo muda ni suru na."},{"jp":"彼は一言たりとも話さない。","en":"He doesn't speak even a single word.","romaji":"Kare wa hitokoto tari tomo hanasanai."},{"jp":"彼女は一度たりともその映画を見たことがない。","en":"She has never seen that movie, not even once.","romaji":"Kanojo wa ichido tari tomo sono eiga o mita koto ga nai."},{"jp":"私は一枚たりともその写真を持っていない。","en":"I don't have even a single picture of it.","romaji":"Watashi wa ichimai tari tomo sono shashin o motte inai."}],"example":"一分たりとも無駄にするな。","exampleMeaning":"Don’t waste even a single minute."},{"pattern":"Noun たる Noun","meaning":"Indicates 'being in the position/state of', used for roles or statuses.","formation":"Noun1 + たる + Noun2","examples":[{"jp":"リーダーたる者は、常に先を見て行動すべきだ。","en":"A person who is a leader should always look ahead and act accordingly.","romaji":"Riidaa taru mono wa, tsune ni saki o mite koudou subeki da."},{"jp":"教師たる者、学生に模範を示すべきである。","en":"Someone who is a teacher should set a good example for the students.","romaji":"Kyoushi taru mono, gakusei ni mohan o shimesu beki de aru."},{"jp":"母たる者、家族を愛するのは当然だ。","en":"If you are a mother, it’s natural to love your family.","romaji":"Haha taru mono, kazoku o aisuru no wa touzen da."},{"jp":"医者たる者、患者の安全を最優先に考えるべきだ。","en":"A person who is a doctor should make patient safety their top priority.","romaji":"Isha taru mono, kanja no anzen o saiyuusen ni kangaeru beki da."}],"example":"リーダーたる者は、常に先を見て行動すべきだ。","exampleMeaning":"A person who is a leader should always look ahead and act accordingly."},{"pattern":"Noun ですら","meaning":"Means 'even', 'as much as', used for emphasis in formal contexts.","formation":"Noun + ですら","examples":[{"jp":"明日試験があるのに、彼はテキストですら読まない。","en":"He doesn’t even read the textbook, despite having a test tomorrow.","romaji":"Ashita shiken ga aru noni, kare wa tekisuto desura yomanai."},{"jp":"この問題は専門家ですら解けない。","en":"Even an expert can’t solve this problem.","romaji":"Kono mondai wa senmonka desura tokenai."},{"jp":"彼女は最後のスピーチですら泣いてしまった。","en":"She ended up crying, even during the final speech.","romaji":"Kanojo wa saigo no supiichi desura naite shimatta."},{"jp":"彼は毎日勉強しているが、基本の漢字ですら覚えられない。","en":"He studies every day, but can’t even remember basic kanji.","romaji":"Kare wa mainichi benkyou shite iru ga, kihon no kanji desura oboerarenai."}],"example":"明日試験があるのに、彼はテキストですら読まない。","exampleMeaning":"He doesn’t even read the textbook, despite having a test tomorrow."},{"pattern":"Noun でなくてなんだろう (〜de nakute nandarou)","meaning":"A strong rhetorical question: 'If not X, then what is it?'","formation":"Noun + でなくてなんだろう","examples":[{"jp":"これが真実でなくてなんだろう。","en":"If this isn’t the truth, then what is?","romaji":"Kore ga shinjitsu de nakute nandarou."},{"jp":"彼がリーダーでなくてなんだろう。","en":"If he isn’t the leader, then who is?","romaji":"Kare ga riidaa de nakute nandarou."},{"jp":"これが愛でなくてなんだろう。","en":"If this isn’t love, then what is?","romaji":"Kore ga ai de nakute nandarou."},{"jp":"これが最高のレストランでなくてなんだろう。","en":"If this isn’t the best restaurant, then what is?","romaji":"Kore ga saikou no resutoran de nakute nandarou."}],"example":"これが真実でなくてなんだろう。","exampleMeaning":"If this isn’t the truth, then what is?"},{"pattern":"Noun ではあるまいし","meaning":"Means 'it’s not as if...', 'it’s not that...', more formal than じゃあるまいし.","formation":"Noun + ではあるまいし","examples":[{"jp":"彼女はプロの歌手ではあるまいし、完璧を求めるのは酷だ。","en":"She’s not a professional singer, so it’s rather harsh to demand perfection.","romaji":"Kanojo wa puro no kashu de wa aru mai shi, kanpeki o motomeru no wa koku da."},{"jp":"彼は子供ではあるまいし、そんなにチョコレートばかり食べるのはどうかと思う。","en":"He’s not a child, so I’m not sure about him eating that much chocolate.","romaji":"Kare wa kodomo de wa aru mai shi, sonnani chokoreeto bakari taberu no wa douka to omou."},{"jp":"彼は医者ではあるまいし、あなたの健康状態を詮索する必要はない。","en":"He’s not a doctor, so he has no need to pry into your health.","romaji":"Kare wa isha de wa aru mai shi, anata no kenkou joutai o sensaku suru hitsuyou wa nai."},{"jp":"この指輪は高価なものではあるまいし、落としても大したことはない。","en":"It’s not an expensive ring, so dropping it isn’t a big deal.","romaji":"Kono yubiwa wa kouka na mono de wa aru mai shi, otoshite mo taishita koto wa nai."}],"example":"彼女はプロの歌手ではあるまいし、完璧を求めるのは酷だ。","exampleMeaning":"She’s not a professional singer, so it’s rather harsh to demand perfection."},{"pattern":"Noun と Noun を兼ねて","meaning":"Used to indicate doing two things at once or fulfilling two roles/purposes.","formation":"Noun + と + Noun + を兼ねて","examples":[{"jp":"お父さんは社長と経理部長を兼ねています。","en":"My father serves as both the company president and the head of accounting.","romaji":"Otousan wa shachou to keiri buchou o kanete imasu."},{"jp":"彼女は音楽教師とピアニストを兼ねています。","en":"She works as both a music teacher and a pianist.","romaji":"Kanojo wa ongaku kyoushi to pianisuto o kanete imasu."},{"jp":"この部屋は寝室と書斎を兼ねています。","en":"This room serves as both a bedroom and a study.","romaji":"Kono heya wa shinshitsu to shosai o kanete imasu."},{"jp":"彼は父と母を兼ねて子どもの世話をしている。","en":"He looks after his child, taking on both mother and father roles.","romaji":"Kare wa chichi to haha o kanete kodomo no sewa o shite iru."}],"example":"お父さんは社長と経理部長を兼ねています。","exampleMeaning":"My father serves as both the company president and the head of accounting."},{"pattern":"Noun といい Noun といい (〜to ii〜to ii)","meaning":"Used to express 'both A and B'; 'whether it's A or B'; 'not to mention A and also B'.","formation":"Noun1 + といい + Noun2 + といい + Comment","examples":[{"jp":"日本の食べ物といい観光地といい、すべてが素晴らしいです。","en":"Both Japanese food and tourist spots are all wonderful.","romaji":"Nihon no tabemono to ii kankouchi to ii, subete ga subarashii desu."},{"jp":"彼の優しさといい、体力といい、彼は理想的なパートナーだ。","en":"Whether it's his kindness or stamina, he is an ideal partner.","romaji":"Kare no yasashisa to ii, tairyoku to ii, kare wa risouteki na paatonaa da."},{"jp":"この町の映画館といい、公園といい、老若男女が楽しめる。","en":"Not to mention the movie theaters and parks in this town, they are enjoyable for all ages.","romaji":"Kono machi no eigakan to ii, kouen to ii, rounyakunan'nyo ga tanoshimeru."},{"jp":"彼の歌唱力といい、ダンスのスキルといい、完璧だ。","en":"Both his singing ability and his dance skills are perfect.","romaji":"Kare no kashou ryoku to ii, dansu no sukiru to ii, kanpeki da."}],"example":"日本の食べ物といい観光地といい、すべてが素晴らしいです。","exampleMeaning":"Both Japanese food and tourist spots are all wonderful."},{"pattern":"Noun という Noun","meaning":"Used to specify or define one noun with another; 'the noun called', 'the noun that is', or 'a certain'.","formation":"Noun1 という Noun2","examples":[{"jp":"宮崎駿という人は有名なアニメーション監督です。","en":"The person called Hayao Miyazaki is a famous animation director.","romaji":"Miyazaki Hayao to iu hito wa yuumei na animation kantoku desu."},{"jp":"その恋人という女性は彼にとても厳しいです。","en":"The woman called his girlfriend is very strict with him.","romaji":"Sono koibito to iu josei wa kare ni totemo kibishii desu."},{"jp":"東京という都市は夜も賑やかです。","en":"The city called Tokyo is bustling even at night.","romaji":"Tokyo to iu toshi wa yoru mo nigiyaka desu."},{"jp":"私は「ハリーポッター」という本が好きです。","en":"I like the book called 'Harry Potter'.","romaji":"Watashi wa 'Harry Potter' to iu hon ga suki desu."}],"example":"宮崎駿という人は有名なアニメーション監督です。","exampleMeaning":"The person called Hayao Miyazaki is a famous animation director."},{"pattern":"Noun というところだ","meaning":"Means 'it's approximately...' or 'it's about...'. Used to show approximation or a general assessment.","formation":"Noun + というところだ","examples":[{"jp":"今回の試験の合格者は半数というところだろう。","en":"The passers in this exam would be approximately half.","romaji":"Konkai no shiken no goukakusha wa hansuu to iu tokoro darou."},{"jp":"彼の力は80％というところだ。","en":"His strength is about 80%.","romaji":"Kare no chikara wa hachijuu paasento to iu tokoro da."},{"jp":"このプランに賛成の人は7割というところだ。","en":"About 70% of people agree with this plan.","romaji":"Kono puran ni sansei no hito wa nanawari to iu tokoro da."},{"jp":"課長の意見には、私としては90％というところでしょう。","en":"As for the section manager's opinion, I'd say I'm about 90% in agreement.","romaji":"Kachou no iken ni wa, watashi toshite wa kyuujuu paasento to iu tokoro deshou."}],"example":"今回の試験の合格者は半数というところだろう。","exampleMeaning":"The passers in this exam would be approximately half."},{"pattern":"Noun + というもの","meaning":"Used to express a generic concept: 'all ~', 'any ~ of that kind'.","formation":"Noun + というもの","examples":[{"jp":"子供というものは、毎日たくさん遊びます。","en":"Children, as a group, play a lot every day.","romaji":"Kodomo to iu mono wa, mainichi takusan asobimasu."},{"jp":"大学生というものは研究に時間をたくさんかけます。","en":"University students spend a lot of time on research.","romaji":"Daigakusei to iu mono wa kenkyuu ni jikan o takusan kakemasu."},{"jp":"日本文化というものは伝統的なものと新しいものが混ざっています。","en":"Japanese culture is a mixture of traditional and new.","romaji":"Nihon bunka to iu mono wa dentouteki na mono to atarashii mono ga mazatte imasu."},{"jp":"別れというものはいつも悲しいものです。","en":"Goodbyes are always sad.","romaji":"Wakare to iu mono wa itsumo kanashii mono desu."}],"example":"子供というものは、毎日たくさん遊びます。","exampleMeaning":"Children, as a group, play a lot every day."},{"pattern":"Noun といったところだ","meaning":"Expresses 'at most', 'as much as', or 'limited to'.","formation":"Noun + といったところだ","examples":[{"jp":"彼の英語レベルは初級といったところだ。","en":"His English level is at most beginner level.","romaji":"Kare no eigo reberu wa shokyuu to itta tokoro da."},{"jp":"私の日本語の語彙は1000語といったところだ。","en":"My Japanese vocabulary is limited to about 1000 words.","romaji":"Watashi no nihongo no goi wa sen go to itta tokoro da."},{"jp":"彼が毎日ランニングできるのは5キロといったところだ。","en":"He can run as much as 5 kilometers a day at most.","romaji":"Kare ga mainichi ranningu dekiru no wa go kiro to itta tokoro da."},{"jp":"その会社の従業員は20人といったところだ。","en":"The employees at that company are limited to about 20 people.","romaji":"Sono kaisha no juugyouin wa nijuu nin to itta tokoro da."}],"example":"彼の英語レベルは初級といったところだ。","exampleMeaning":"His English level is at most beginner level."},{"pattern":"Noun といわず Noun といわず","meaning":"Expresses 'both A and B' or 'be it A or B'; applies to both without distinction.","formation":"Noun1 + といわず + Noun2 + といわず + (rest of the sentence)","examples":[{"jp":"冬といわず夏といわず、彼はいつもアイスクリームを食べます。","en":"Be it winter or summer, he always eats ice cream.","romaji":"Fuyu to iwazu natsu to iwazu, kare wa itsumo aisukuriimu o tabemasu."},{"jp":"老いといわず若きといわず、全ての人がそのイベントを楽しめます。","en":"Whether old or young, everyone can enjoy that event.","romaji":"Oi to iwazu wakaki to iwazu, subete no hito ga sono ibento o tanoshimemasu."},{"jp":"男といわず女といわず、誰もがこの映画を楽しむでしょう。","en":"Be it men or women, everyone will enjoy this movie.","romaji":"Otoko to iwazu onna to iwazu, daremo ga kono eiga o tanoshimu deshou."},{"jp":"月といわず火といわず、あの店は毎日混んでいます。","en":"Be it Monday or Tuesday, that shop is busy every day.","romaji":"Getsu to iwazu ka to iwazu, ano mise wa mainichi konde imasu."}],"example":"冬といわず夏といわず、彼はいつもアイスクリームを食べます。","exampleMeaning":"Be it winter or summer, he always eats ice cream."},{"pattern":"Noun + ときたら (〜tokitara)","meaning":"Expresses strong feelings about a topic; 'speaking of', 'when it comes to'.","formation":"Noun + ときたら","examples":[{"jp":"寿司ときたら、彼は何も食べられない。","en":"When it comes to sushi, he can't eat anything.","romaji":"Sushi tokitara, kare wa nanimo taberarenai."},{"jp":"数学の問題ときたら、彼女はいつも困っている。","en":"When it comes to math problems, she's always struggling.","romaji":"Suugaku no mondai tokitara, kanojo wa itsumo komatte iru."},{"jp":"あの店のハンバーガーときたら、本当に美味しい。","en":"Speaking of that shop's hamburgers, they're really delicious.","romaji":"Ano mise no hanbaagaa tokitara, hontou ni oishii."},{"jp":"彼のいつもの態度ときたら、本当に困ったものだ。","en":"Speaking of his usual attitude, it's truly problematic.","romaji":"Kare no itsumo no taido tokitara, hontou ni komatta mono da."}],"example":"寿司ときたら、彼は何も食べられない。","exampleMeaning":"When it comes to sushi, he can't eat anything."},{"pattern":"Noun とは比べものにならない","meaning":"Indicates something is not comparable; 'beyond comparison'.","formation":"Noun + とは比べものにならない","examples":[{"jp":"新しい車の速さは古い車とは比べものにならない。","en":"The speed of the new car is not comparable to the old one.","romaji":"Atarashii kuruma no hayasa wa furui kuruma to wa kurabemono ni naranai."},{"jp":"彼の英語のうまさは私とは比べものにならない。","en":"His English skills are beyond comparison with mine.","romaji":"Kare no eigo no umasa wa watashi to wa kurabemono ni naranai."},{"jp":"日本の技術は他の国とは比べものにならない。","en":"Japan's technology is not comparable to that of other countries.","romaji":"Nihon no gijutsu wa hoka no kuni to wa kurabemono ni naranai."},{"jp":"今回の地震の被害は前回とは比べものにならない。","en":"The damage from this earthquake is incomparable to the previous one.","romaji":"Konkai no jishin no higai wa zenkai to wa kurabemono ni naranai."}],"example":"新しい車の速さは古い車とは比べものにならない。","exampleMeaning":"The speed of the new car is not comparable to the old one."},{"pattern":"Noun + ともあろう + Noun","meaning":"Used to criticize or question unbecoming behavior by someone of a certain status.","formation":"Noun + ともあろう + Noun","examples":[{"jp":"先生ともあろう者が、そんな間違いをするなんて。","en":"For a teacher, it's shocking to make such a mistake.","romaji":"Sensei tomoarou mono ga, sonna machigai o suru nante."},{"jp":"大人ともあろう者が子供みたいにふるまってはいけない。","en":"It's not right for an adult to behave like a child.","romaji":"Otona tomoarou mono ga kodomo mitai ni furumatte wa ikenai."},{"jp":"社長ともあろう人がそんな失礼なことを言うなんて。","en":"It's shocking that someone who is the company president would say such a rude thing.","romaji":"Shachou tomoarou hito ga sonna shitsurei na koto o iu nante."},{"jp":"プロの選手ともあろう者が、試合に遅刻するなんて。","en":"For a professional athlete, being late to a match is unthinkable.","romaji":"Puro no senshu tomoarou mono ga, shiai ni chikoku suru nante."}],"example":"先生ともあろう者が、そんな間違いをするなんて。","exampleMeaning":"For a teacher, it's shocking to make such a mistake."},{"pattern":"Noun ともなると (〜to mo naru to)","meaning":"'When it comes to...', emphasizes a change of situation or status.","formation":"Noun + ともなると","examples":[{"jp":"クリスマスともなると、街中がきらきらと輝いて見えます。","en":"When it comes to Christmas time, the whole city sparkles.","romaji":"Kurisumasu to mo naru to, machijuu ga kirakira to kagayaite miemasu."},{"jp":"子供が自分の過ちを認めるともなると、話は別ですね。","en":"When a child admits their mistake, that’s a different story.","romaji":"Kodomo ga jibun no ayamachi o mitomeru to mo naru to, hanashi wa betsu desu ne."},{"jp":"夏休みともなると、海辺は観光客で溢れかえります。","en":"When summer vacation comes, the seaside is filled with tourists.","romaji":"Natsu yasumi to mo naru to, umibe wa kankoukyaku de afurekaerimasu."},{"jp":"試験週間ともなると、図書館はいつもより混雑します。","en":"When exam week arrives, the library gets more crowded than usual.","romaji":"Shiken shuukan to mo naru to, toshokan wa itsumo yori konzatsu shimasu."}],"example":"クリスマスともなると、街中がきらきらと輝いて見えます。","exampleMeaning":"When it comes to Christmas time, the whole city sparkles."},{"pattern":"Noun ともなれば (〜to mo nareba)","meaning":"Expresses 'if it comes to', 'when', or 'once'.","formation":"Noun + ともなれば","examples":[{"jp":"試験ともなれば、大抵の人が緊張するものです。","en":"When it comes to exams, most people get nervous.","romaji":"Shiken to mo nareba, taitei no hito ga kinchou suru mono desu."},{"jp":"彼がリーダーともなれば、チームの性能はさらに向上するでしょう。","en":"If he becomes the leader, the team's performance will improve even more.","romaji":"Kare ga riidaa to mo nareba, chiimu no seinou wa sara ni koujou suru deshou."},{"jp":"夏休みともなれば、観光地はいつも人であふれている。","en":"When it comes to summer vacation, tourist spots are always packed with people.","romaji":"Natsuyasumi to mo nareba, kankouchi wa itsumo hito de afurete iru."},{"jp":"結婚ともなれば、ただ二人が愛し合っているだけではすまされない事情も多い。","en":"When it comes to marriage, there are often issues that can’t be solved by love alone.","romaji":"Kekkon to mo nareba, tada futari ga aishiatte iru dake de wa sumasarenai jijou mo oi."}],"example":"試験ともなれば、大抵の人が緊張するものです。","exampleMeaning":"When it comes to exams, most people get nervous."},{"pattern":"Noun と相まって","meaning":"Used to express 'in combination with', 'together with', 'along with'.","formation":"Noun + と相まって","examples":[{"jp":"天気の良さと相まって、ピクニックは大成功でした。","en":"In combination with the good weather, the picnic was a great success.","romaji":"Tenki no yosa to aimatte, pikunikku wa daiseikou deshita."},{"jp":"努力と運と相まって、彼は試験に合格しました。","en":"Thanks to both effort and luck, he passed the exam.","romaji":"Doryoku to un to aimatte, kare wa shiken ni goukaku shimashita."},{"jp":"ひまわり油とガーリックと相まって、この料理は美味しいです。","en":"Combined with sunflower oil and garlic, this dish is delicious.","romaji":"Himawari abura to gaarikku to aimatte, kono ryouri wa oishii desu."},{"jp":"新しい技術と経験と相まって、私たちはこの問題を克服できました。","en":"Together with new technology and experience, we were able to overcome this problem.","romaji":"Atarashii gijutsu to keiken to aimatte, watashitachi wa kono mondai o kokufuku dekimashita."}],"example":"天気の良さと相まって、ピクニックは大成功でした。","exampleMeaning":"In combination with the good weather, the picnic was a great success."},{"pattern":"Noun なくして～はない","meaning":"Expresses 'without ~, there can't be ~'; 'can't do ~ without first doing ~'.","formation":"Noun + なくして + Sentence ～はない","examples":[{"jp":"努力なくして成功はない。","en":"There is no success without effort.","romaji":"Doryoku nakushite seikou wa nai."},{"jp":"時間なくして完璧な作品は作れない。","en":"You cannot create a perfect work without time.","romaji":"Jikan nakushite kanpeki na sakuhin wa tsukurenai."},{"jp":"経験なくして成長はない。","en":"There is no growth without experience.","romaji":"Keiken nakushite seichou wa nai."},{"jp":"リーダーシップなくしてグループの成功はない。","en":"Without leadership, there can be no success for the group.","romaji":"Riidaashippu nakushite guruupu no seikou wa nai."}],"example":"努力なくして成功はない。","exampleMeaning":"There is no success without effort."},{"pattern":"Noun なしでは～ない","meaning":"Expresses the necessity of something; 'cannot do without', 'not possible without'.","formation":"Noun + なしでは～ない","examples":[{"jp":"水なしでは生きられない。","en":"We cannot live without water.","romaji":"Mizu nashi de wa ikirarenai."},{"jp":"彼の助けなしでは、この問題を解決することはできない。","en":"Without his help, I cannot solve this problem.","romaji":"Kare no tasuke nashi de wa, kono mondai o kaiketsu suru koto wa dekinai."},{"jp":"コンピュータなしでは、現代のビジネスは成り立たない。","en":"Modern business cannot function without computers.","romaji":"Konpyuuta nashi de wa, gendai no bijinesu wa naritatanai."},{"jp":"友情なしでは、人生は退屈だろう。","en":"Life would be boring without friendship.","romaji":"Yuujou nashi de wa, jinsei wa taikutsu darou."}],"example":"水なしでは生きられない。","exampleMeaning":"We cannot live without water."},{"pattern":"Noun なしには～ない","meaning":"Means 'without', 'cannot do without', 'not possible without'.","formation":"Noun + なしには + Verb-negative","examples":[{"jp":"お金なしには生活ができない。","en":"I cannot get by without money.","romaji":"Okane nashi ni wa seikatsu ga dekinai."},{"jp":"愛情なしには子育てができない。","en":"You cannot raise a child without love.","romaji":"Aijou nashi ni wa kosodate ga dekinai."},{"jp":"彼なしにはこのプロジェクトを進められない。","en":"Without him, I cannot move this project forward.","romaji":"Kare nashi ni wa kono purojekuto o susumerarenai."},{"jp":"水なしには生きていけない。","en":"I cannot live without water.","romaji":"Mizu nashi ni wa ikite ikenai."}],"example":"お金なしには生活ができない。","exampleMeaning":"I cannot get by without money."},{"pattern":"Noun ならいざ知らず","meaning":"Expresses 'maybe X is possible, but Y is definitely not'. Often 'let alone...'.","formation":"Noun1 + ならいざ知らず + Noun2 (comment)","examples":[{"jp":"数学ならいざ知らず、物理なんて全然わからない。","en":"Math might be manageable, but as for physics, I'm completely clueless.","romaji":"Suugaku nara iza shirazu, butsuri nante zenzen wakaranai."},{"jp":"5キロならいざ知らず、10キロなんて走れません。","en":"Maybe I could run 5 kilometers, but 10 kilometers is out of the question.","romaji":"Go kiro nara iza shirazu, juu kiro nante hashiremasen."},{"jp":"日本語ならいざ知らず、中国語なんて話せない。","en":"I might be able to speak Japanese, but Chinese is impossible for me.","romaji":"Nihongo nara iza shirazu, chuugokugo nante hanasenai."},{"jp":"冷たい水ならいざ知らず、熱い水で泳ぐなんて考えたこともない。","en":"Maybe cold water, but swimming in hot water never even crossed my mind.","romaji":"Tsumetai mizu nara iza shirazu, atsui mizu de oyogu nante kangaeta koto mo nai."}],"example":"数学ならいざ知らず、物理なんて全然わからない。","exampleMeaning":"Math might be manageable, but as for physics, I'm completely clueless."},{"pattern":"Noun + ならでは","meaning":"Expresses something unique or characteristic only of that noun; 'only found in', 'only possible with'.","formation":"Noun + ならでは","examples":[{"jp":"これは日本ならではの風景ですね。","en":"This is a landscape you can only find in Japan.","romaji":"Kore wa Nihon nara dewa no fuukei desu ne."},{"jp":"新鮮な魚はこの町ならではの特産品です。","en":"Fresh fish is a specialty unique to this town.","romaji":"Shinsen na sakana wa kono machi nara dewa no tokusanhin desu."},{"jp":"彼の技術は彼ならではのものだ。","en":"His skills are unique to him.","romaji":"Kare no gijutsu wa kare nara dewa no mono da."},{"jp":"この手作りの一品は、彼女ならではのものです。","en":"This handmade item is something only she could produce.","romaji":"Kono tezukuri no ippin wa, kanojo nara dewa no mono desu."}],"example":"これは日本ならではの風景ですね。","exampleMeaning":"This is a landscape you can only find in Japan."},{"pattern":"Noun なり Noun なり","meaning":"Lists alternatives of the same kind; 'either A or B', 'A or B, for example'.","formation":"Noun + なり + Noun + なり","examples":[{"jp":"映画なり、音楽なり、何か趣味はありますか。","en":"Do you have any hobbies, such as movies or music?","romaji":"Eiga nari, ongaku nari, nanika shumi wa arimasu ka?"},{"jp":"紅茶なり、コーヒーなり、何か飲み物をください。","en":"Please give me something to drink, like tea or coffee.","romaji":"Koucha nari, koohii nari, nanika nomimono o kudasai."},{"jp":"パンなり、おにぎりなり、何か食べてください。","en":"Please eat something—bread, onigiri, or whatever you’d like.","romaji":"Pan nari, onigiri nari, nanika tabete kudasai."},{"jp":"タクシーなり、バスなりに乗って来てください。","en":"Please come by either taxi or bus.","romaji":"Takushii nari, basu nari ni notte kite kudasai."}],"example":"映画なり、音楽なり、何か趣味はありますか。","exampleMeaning":"Do you have any hobbies, such as movies or music?"},{"pattern":"Noun なりとも","meaning":"Indicates even a small amount or degree; 'at least', 'even a little'.","formation":"Noun + なりとも","examples":[{"jp":"時間が限られているので、一時間なりとも練習すべきだ。","en":"Since time is limited, you should practice for at least an hour.","romaji":"Jikan ga kagirarete iru node, ichi-jikan nari tomo renshuu subeki da."},{"jp":"彼には一言なりとも謝罪の言葉を聞きたい。","en":"I’d like to hear at least a word of apology from him.","romaji":"Kare ni wa hitokoto nari tomo shazai no kotoba o kikitai."},{"jp":"このプロジェクトには、一人なりともメンバーが必要だ。","en":"We need at least one member for this project.","romaji":"Kono purojekuto ni wa, hitori nari tomo membaa ga hitsuyou da."},{"jp":"あなたには、一言なりとも感謝の言葉を述べたい。","en":"I want to offer at least a word of gratitude to you.","romaji":"Anata ni wa, hitokoto nari tomo kansha no kotoba o nobetai."}],"example":"時間が限られているので、一時間なりとも練習すべきだ。","exampleMeaning":"Since time is limited, you should practice for at least an hour."},{"pattern":"Noun に Noun を重ねて","meaning":"This expression is used to describe repeated actions or states, 'one after another' or 'pile up'.","formation":"Noun に Noun を重ねて","examples":[{"jp":"彼女は失敗に失敗を重ねて、とうとう会社を辞めた。","en":"She piled up failures upon failures and finally quit the company.","romaji":"Kanojo wa shippai ni shippai wo kasanete, toutou kaisha wo yameta."},{"jp":"仕事に仕事を重ねて、彼は疲れ果てた。","en":"He piled up work upon work and was completely exhausted.","romaji":"Shigoto ni shigoto wo kasanete, kare wa tsukarehateta."},{"jp":"彼は試験に不合格になり、失望に失望を重ねていた。","en":"He failed the exam and kept piling up his disappointments.","romaji":"Kare wa shiken ni fugōkaku ni nari, shitsubō ni shitsubō wo kasanete ita."},{"jp":"彼は問題に問題を重ねて、とうとう退学になった。","en":"He kept piling up problems upon problems until he was finally expelled.","romaji":"Kare wa mondai ni mondai wo kasanete, toutou taigaku ni natta."}],"example":"彼女は失敗に失敗を重ねて、とうとう会社を辞めた。","exampleMeaning":"She piled up failures upon failures and finally quit the company."},{"pattern":"Noun にあっては","meaning":"Indicates a specific situation or environment in which something happens or is the case.","formation":"Noun + にあっては","examples":[{"jp":"戦争時にあっては、すべての人々が困難に直面していました。","en":"In wartime, all people were facing difficulties.","romaji":"Sensouji ni atte wa, subete no hito ga konnan ni chokumen shiteimashita."},{"jp":"経済危機にあっては、多くの企業が倒産の危機に瀕している。","en":"In the economic crisis, many companies are on the verge of bankruptcy.","romaji":"Keizai kiki ni atte wa, ooku no kigyou ga tousan no kiki ni hinshite iru."},{"jp":"不況下にあっては、どの企業も経費削減を迫られている。","en":"In times of recession, every company is forced to cut costs.","romaji":"Fukyouka ni atte wa, dono kigyou mo keihi sakugen o semararete iru."},{"jp":"改革期にあっては、新しいアイデアを大切にする必要がある。","en":"In a period of reform, it's necessary to value new ideas.","romaji":"Kaikaku ki ni atte wa, atarashii aidea o taisetsu ni suru hitsuyou ga aru."}],"example":"戦争時にあっては、すべての人々が困難に直面していました。","exampleMeaning":"In wartime, all people were facing difficulties."},{"pattern":"Noun にあるまじき Noun","meaning":"Expresses the idea of 'unfitting', 'unbecoming' or 'inappropriate'.","formation":"Noun1 にあるまじき Noun2","examples":[{"jp":"彼は教師にあるまじき言動をとった。","en":"He took actions that are unbecoming of a teacher.","romaji":"Kare wa kyoushi ni aru majiki gendou wo totta."},{"jp":"これは人間にあるまじき行為だ。","en":"This is an act that is unfitting for a human.","romaji":"Kore wa ningen ni aru majiki koui da."},{"jp":"彼女は社長にあるまじき振る舞いをした。","en":"She behaved in a way that is unbecoming of a president.","romaji":"Kanojo wa shachou ni aru majiki furumai wo shita."},{"jp":"それは社会人にあるまじき行動だ。","en":"That is a behaviour that is not suitable for an adult.","romaji":"Sore wa shakaijin ni aru majiki koudou da."}],"example":"彼は教師にあるまじき言動をとった。","exampleMeaning":"He took actions that are unbecoming of a teacher."},{"pattern":"Noun にして","meaning":"Expresses the idea 'even for', 'even though', or 'in spite of'.","formation":"Noun + にして","examples":[{"jp":"彼は医者にしてその基本的な知識がないのが信じられない。","en":"I can't believe that even as a doctor, he doesn't have that basic knowledge.","romaji":"Kare wa isha ni shite sono kihonteki na chishiki ga nai no ga shinjirarenai."},{"jp":"彼は経験豊富な運転手にして、事故を起こした。","en":"Even as an experienced driver, he had an accident.","romaji":"Kare wa keiken houfu na untenshu ni shite, jiko wo okoshita."},{"jp":"彼は成績優秀な生徒にして、その問題が解けなかった。","en":"Even as an excellent student, he couldn't solve that problem.","romaji":"Kare wa seiseki yuushuu na seito ni shite, sono mondai ga tokenakatta."},{"jp":"彼は勉強家にして、その問題を理解できなかった。","en":"Even as a studious person, he could not understand that problem.","romaji":"Kare wa benkyouka ni shite, sono mondai o rikai dekinakatta."}],"example":"彼は医者にしてその基本的な知識がないのが信じられない。","exampleMeaning":"I can't believe that even as a doctor, he doesn't have that basic knowledge."},{"pattern":"Noun にして初めて","meaning":"Expresses 'only when/after... for the first time'.","formation":"Noun + にして初めて","examples":[{"jp":"大人にして初めて、親の苦労が分かった。","en":"Only when I became an adult did I understand my parents' struggles for the first time.","romaji":"Otona ni shite hajimete, oya no kurou ga wakatta."},{"jp":"彼は40歳にして初めて、海外旅行を経験した。","en":"Only when he turned 40 did he travel abroad for the first time.","romaji":"Kare wa yonjuu-sai ni shite hajimete, kaigai ryokou o keiken shita."},{"jp":"彼女は親にして初めて、子育ての大変さを理解した。","en":"It was only after she became a parent that she realized how challenging raising a child can be.","romaji":"Kanojo wa oya ni shite hajimete, kosodate no taihensa o rikai shita."},{"jp":"社長にして初めて、会社全体の重責を痛感した。","en":"Only when he became president did he feel the full weight of responsibility for the entire company.","romaji":"Shachou ni shite hajimete, kaisha zentai no juuseki o tsuukan shita."}],"example":"大人にして初めて、親の苦労が分かった。","exampleMeaning":"Only when I became an adult did I understand my parents' struggles for the first time."},{"pattern":"Noun にすら (〜ni sura)","meaning":"Expresses the concept of 'even'; 'even in', 'even as', 'even to'.","formation":"Noun + にすら","examples":[{"jp":"彼にすらその問題は解けなかった。","en":"Even he could not solve that problem.","romaji":"Kare ni sura sono mondai wa tokenakatta."},{"jp":"彼女はテストにすら合格しなかった。","en":"She did not even pass the test.","romaji":"Kanojo wa tesuto ni sura goukaku shinakatta."},{"jp":"この犬は自分の名前にすら反応しない。","en":"This dog doesn't even respond to its own name.","romaji":"Kono inu wa jibun no namae ni sura hannou shinai."},{"jp":"彼にすら話す余裕がなかった。","en":"I didn't even have the time to talk to him.","romaji":"Kare ni sura hanasu yoyuu ga nakatta."}],"example":"彼にすらその問題は解けなかった。","exampleMeaning":"Even he could not solve that problem."},{"pattern":"Noun にとどまらず～も","meaning":"This expresses the idea of 'not only...but also', 'not stopping at...'.","formation":"Noun + にとどまらず + Noun + も","examples":[{"jp":"このアプリは、日本語にとどまらず、他の言語もサポートしています。","en":"This app not only supports Japanese, but also other languages.","romaji":"Kono apuri wa, nihongo ni todomarazu, hoka no gengo mo sapooto shite imasu."},{"jp":"彼は、音楽にとどまらず、映画製作にも興味がある。","en":"He is not only interested in music, but also in filmmaking.","romaji":"Kare wa, ongaku ni todomarazu, eiga seisaku ni mo kyoumi ga aru."},{"jp":"彼の影響は、家族にとどまらず、地域全体にも及んでいます。","en":"His influence extends not only to his family but also to the entire region.","romaji":"Kare no eikyou wa, kazoku ni todomarazu, chiiki zentai ni mo oyonde imasu."},{"jp":"彼女の才能は、絵画にとどまらず、文学にも及ぶ。","en":"Her talent extends not only to painting, but also to literature.","romaji":"Kanojo no sainou wa, kaiga ni todomarazu, bungaku ni mo oyobu."}],"example":"このアプリは、日本語にとどまらず、他の言語もサポートしています。","exampleMeaning":"This app not only supports Japanese, but also other languages."},{"pattern":"Noun にひきかえ Noun は","meaning":"Represents 'in contrast to', 'as opposed to'.","formation":"Noun 1 + にひきかえ + Noun 2 + は","examples":[{"jp":"彼の親切さにひきかえ、彼女は無感情だ。","en":"In contrast to his kindness, she is emotionless.","romaji":"Kare no shinsetsusa ni hikikae, kanojo wa mukanjou da."},{"jp":"夏にひきかえ、冬は雪で寒い。","en":"As opposed to summer, winter is cold with snow.","romaji":"Natsu ni hikikae, fuyu wa yuki de samui."},{"jp":"日本の駅にひきかえ、アメリカの駅は広い。","en":"As opposed to Japanese stations, American stations are wide.","romaji":"Nihon no eki ni hikikae, Amerika no eki wa hiroi."},{"jp":"昔にひきかえ、現代はテクノロジーが進歩した。","en":"As opposed to the old days, modern times have advanced technology.","romaji":"Mukashi ni hikikae, gendai wa tekunorojii ga shinpo shita."}],"example":"彼の親切さにひきかえ、彼女は無感情だ。","exampleMeaning":"In contrast to his kindness, she is emotionless."},{"pattern":"Noun にもまして (〜ni mo mashite)","meaning":"This expresses 'Even more than; exceeding'.","formation":"Noun + にもまして","examples":[{"jp":"私は彼にもまして、音楽を愛しています。","en":"I love music even more than he does.","romaji":"Watashi wa kare ni mo mashite, ongaku o aishiteimasu."},{"jp":"彼女は年齢にもまして、経験豊富です。","en":"She has even more experience than her age would suggest.","romaji":"Kanojo wa nenrei ni mo mashite, keiken houfu desu."},{"jp":"今日は昨日にもまして寒いです。","en":"It is even colder today than it was yesterday.","romaji":"Kyou wa kinou ni mo mashite samui desu."},{"jp":"このビルは高さにもまして、美しい設計が有名です。","en":"This building is famous for its beautiful design even more than its height.","romaji":"Kono biru wa takasa ni mo mashite, utsukushii sekkei ga yuumei desu."}],"example":"私は彼にもまして、音楽を愛しています。","exampleMeaning":"I love music even more than he does."},{"pattern":"Noun によらず","meaning":"Regardless of, irrespective of.","formation":"Noun + によらず","examples":[{"jp":"結果は勉強時間によらず変わらないでしょう。","en":"The result will not change regardless of the study time.","romaji":"Kekka wa benkyou jikan ni yorazu kawaranai deshou."},{"jp":"季節によらず、この地域は常に暖かいです。","en":"This region is always warm, regardless of the season.","romaji":"Kisetsu ni yorazu, kono chiiki wa tsune ni atatakai desu."},{"jp":"年齢によらず、皆が楽しめるイベントです。","en":"It is an event that everyone can enjoy, regardless of age.","romaji":"Nenrei ni yorazu, mina ga tanoshimeru ibento desu."},{"jp":"国籍によらず、誰でも参加できます。","en":"Anyone can participate, regardless of nationality.","romaji":"Kokuseki ni yorazu, dare demo sanka dekimasu."}],"example":"結果は勉強時間によらず変わらないでしょう。","exampleMeaning":"The result will not change regardless of the study time."},{"pattern":"Noun に先駆けて (〜ni saki gakete)","meaning":"Meaning 'ahead of', 'before', or 'preceding in time'.","formation":"Noun + に先駆けて","examples":[{"jp":"この映画は日本に先駆けて、アメリカで公開されました。","en":"This film was released in America ahead of Japan.","romaji":"Kono eiga wa Nippon ni sakigakete, Amerika de koukai saremashita."},{"jp":"彼は周りの人々に先駆けて、その発表を聞いた。","en":"He heard the announcement before the people around him.","romaji":"Kare wa mawari no hitobito ni sakigakete, sono happyou o kiita."},{"jp":"ジョンソンさんは他の参加者に先駆けて、会場に到着しました。","en":"Mr. Johnson arrived at the venue ahead of the other participants.","romaji":"Jonson-san wa hoka no sankasha ni sakigakete, kaijou ni touchaku shimashita."},{"jp":"彼女は同級生に先駆けて卒業することができました。","en":"She was able to graduate before her classmates.","romaji":"Kanojo wa doukyuusei ni sakigakete sotsugyou suru koto ga dekimashita."}],"example":"この映画は日本に先駆けて、アメリカで公開されました。","exampleMeaning":"This film was released in America ahead of Japan."},{"pattern":"Noun に即した Noun","meaning":"Expresses the idea of 'in accordance with', 'based on'.","formation":"Noun1 + に即した + Noun2","examples":[{"jp":"社会のニーズに即した教育改革が必要だ。","en":"We need an educational reform that is in accordance with the needs of society.","romaji":"Shakai no niizu ni sokushita kyouiku kaikaku ga hitsuyou da."},{"jp":"国際法に即した対応をとるべきだ。","en":"We should respond in accordance with international law.","romaji":"Kokusaihou ni sokushita taiou wo toru beki da."},{"jp":"チームのポリシーに即した行動を取りましょう。","en":"Let's take action in accordance with the team's policy.","romaji":"Chiimu no porishii ni sokushita koudou wo torimashou."},{"jp":"現実に即した計画を立てなければならない。","en":"We must make a plan based on reality.","romaji":"Genjitsu ni sokushita keikaku wo tatenakereba naranai."}],"example":"社会のニーズに即した教育改革が必要だ。","exampleMeaning":"We need an educational reform that is in accordance with the needs of society."},{"pattern":"Noun に即して Verb (〜ni soku shite ~)","meaning":"The grammar point Noun に即して Verb is used to mean 'to act in accordance with', 'in line with' or 'based on'.","formation":"Noun + に即して + Verb","examples":[{"jp":"会社のポリシーに即して行動しましょう。","en":"Let's act in accordance with the company's policy.","romaji":"Kaisha no porishii ni soku shite koudou shimashou."},{"jp":"法律に即して判断を下すことが重要です。","en":"It's important to make judgments in accordance with the law.","romaji":"Houritsu ni soku shite hantei o kudasu koto ga juuyou desu."},{"jp":"彼の意見に即して、プランを変更しました。","en":"Based on his opinion, we changed the plan.","romaji":"Kare no iken ni soku shite, puran o henkou shimashita."},{"jp":"ルールに即して行動すれば、問題は起きません。","en":"If we act in accordance with the rules, there will be no problem.","romaji":"Ruuru ni soku shite koudou sureba, mondai wa okimasen."}],"example":"会社のポリシーに即して行動しましょう。","exampleMeaning":"Let's act in accordance with the company's policy."},{"pattern":"Noun に言わせれば","meaning":"Expresses 'according to', 'if you ask', 'in the opinion of'.","formation":"Noun + に言わせれば","examples":[{"jp":"先生に言わせれば、毎日勉強することが重要だと言う。","en":"According to the teacher, it's important to study every day.","romaji":"Sensei ni iwasereba, mainichi benkyou suru koto ga juuyou da to iu."},{"jp":"彼に言わせれば、早く結婚する方がいいと思っている。","en":"If you ask him, he thinks it's better to get married early.","romaji":"Kare ni iwasereba, hayaku kekkon suru hou ga ii to omotte iru."},{"jp":"評論家に言わせれば、この映画は今年の最高の映画だそうだ。","en":"According to the critic, this movie is the best of the year.","romaji":"Hyouronka ni iwasereba, kono eiga wa kotoshi no saikou no eiga da sou da."},{"jp":"父に言わせれば、海外で働く経験はとても価値がある。","en":"In my father's opinion, the experience of working overseas is very valuable.","romaji":"Chichi ni iwasereba, kaigai de hataraku keiken wa totemo kachi ga aru."}],"example":"先生に言わせれば、毎日勉強することが重要だと言う。","exampleMeaning":"According to the teacher, it's important to study every day."},{"pattern":"Noun に限ったことではない (〜ni kagitta koto dewa nai)","meaning":"Indicates that something is not only limited to; 'not only', 'not just'.","formation":"Noun + に限ったことではない","examples":[{"jp":"この問題は日本に限ったことではない。","en":"This issue is not only limited to Japan.","romaji":"Kono mondai wa Nihon ni kagitta koto dewa nai."},{"jp":"英語はアメリカに限ったことではない。","en":"English is not just limited to America.","romaji":"Eigo wa Amerika ni kagitta koto dewa nai."},{"jp":"スマホの依存症は若者に限ったことではない。","en":"Smartphone addiction is not only limited to young people.","romaji":"Sumaho no izonshou wa wakamono ni kagitta koto dewa nai."},{"jp":"地球温暖化は我々人間に限ったことではない。","en":"Global warming is not just limited to us humans.","romaji":"Chikyuu ondanka wa wareware ningen ni kagitta koto dewa nai."}],"example":"この問題は日本に限ったことではない。","exampleMeaning":"This issue is not only limited to Japan."},{"pattern":"Noun に限ったことでもない","meaning":"'Not limited to'; 'not just', 'not exclusively'.","formation":"Noun + に限ったことでもない","examples":[{"jp":"この試験が難しいのは、数学に限ったことでもない。","en":"The exam being difficult is not limited to just math.","romaji":"Kono shiken ga muzukashii no wa, suugaku ni kagitta koto demo nai."},{"jp":"彼女が可愛いのは顔だけに限ったことでもない。性格も好きだ。","en":"Her being cute is not just limited to her face. I also like her personality.","romaji":"Kanojo ga kawaii no wa kao dake ni kagitta koto demo nai. Seikaku mo suki da."},{"jp":"その問題が起こるのは、我々の国に限ったことでもない。","en":"The occurrence of that problem is not limited to our country.","romaji":"Sono mondai ga okoru no wa, wareware no kuni ni kagitta koto demo nai."},{"jp":"この作家の本が売れているのは日本に限ったことでもない。","en":"The selling of this author's books is not limited to just Japan.","romaji":"Kono sakka no hon ga urete iru no wa Nippon ni kagitta koto demo nai."}],"example":"この試験が難しいのは、数学に限ったことでもない。","exampleMeaning":"The exam being difficult is not limited to just math."},{"pattern":"Noun に限る","meaning":"Expresses the idea that 'nothing but', 'nothing is better than'.","formation":"Noun + に限る","examples":[{"jp":"こういう時には家族に話すに限る。","en":"At times like this, there's nothing better than talking to your family.","romaji":"Kou iu toki ni wa kazoku ni hanasu ni kagiru."},{"jp":"寒い冬には温かいお茶に限る。","en":"In cold winter, there's nothing better than warm tea.","romaji":"Samui fuyu ni wa atatakai ocha ni kagiru."},{"jp":"疲れたときは、よい睡眠に限る。","en":"When you are tired, nothing is better than a good sleep.","romaji":"Tsukareta toki wa, yoi suimin ni kagiru."},{"jp":"ダイエットするなら、運動に限る。","en":"If you want to go on a diet, there is nothing better than exercise.","romaji":"Daietto suru nara, undou ni kagiru."}],"example":"こういう時には家族に話すに限る。","exampleMeaning":"At times like this, there's nothing better than talking to your family."},{"pattern":"Noun ぬいた Noun","meaning":"Expresses the idea of 'taking something out from something else'.","formation":"Noun1 + をぬいた + Noun2","examples":[{"jp":"このサラダはにんじんをぬいたサラダです。","en":"This is a salad with the carrots removed.","romaji":"Kono sarada wa ninjin o nuita sarada desu."},{"jp":"彼はコーヒーから砂糖をぬいた。","en":"He removed the sugar from the coffee.","romaji":"Kare wa koohii kara satou o nuita."},{"jp":"私は料理から塩をぬいた。","en":"I removed the salt from the cooking.","romaji":"Watashi wa ryouri kara shio o nuita."},{"jp":"彼女は服からシミをぬいた。","en":"She removed the stain from the clothes.","romaji":"Kanojo wa fuku kara shimi o nuita."}],"example":"このサラダはにんじんをぬいたサラダです。","exampleMeaning":"This is a salad with the carrots removed."},{"pattern":"Noun + ぬいて（~nuite)","meaning":"This is a way to express 'minus' or 'except for' some specific noun.","formation":"Noun + ぬいて","examples":[{"jp":"私たちは、彼ぬいて全員が集まることができました。","en":"We were able to gather everyone except for him.","romaji":"Watashitachi wa, kare nuite zen'in ga atsumaru koto ga dekimashita."},{"jp":"このレストランはお子様メニューをぬいてすべてが美味しい。","en":"Everything at this restaurant is delicious except for the kids' menu.","romaji":"Kono resutoran wa okosama menyuu o nuite subete ga oishii."},{"jp":"今日の仕事は昼休みをぬいて忙しかった。","en":"Today's work was busy except for the lunch break.","romaji":"Kyou no shigoto wa hiruyasumi o nuite isogashikatta."},{"jp":"休暇の日をぬいて、毎日彼は働きます。","en":"He works every day except for the holidays.","romaji":"Kyuuka no hi o nuite, mainichi kare wa hatarakimasu."}],"example":"私たちは、彼ぬいて全員が集まることができました。","exampleMeaning":"We were able to gather everyone except for him."},{"pattern":"～ぬく","meaning":"Expresses the concept of doing something completely or thoroughly.","formation":"Verb-stem + ぬく","examples":[{"jp":"彼は一日中本を読みぬく。","en":"He will read the book all day long.","romaji":"Kare wa ichinichijuu hon o yominuku."},{"jp":"私はこのプロジェクトを終わらせぬく。","en":"I will finish this project completely.","romaji":"Watashi wa kono purojekuto o owarasenuku."},{"jp":"彼女は毎日ジムに行き、エクササイズを終わりぬく。","en":"She goes to the gym every day and finishes her exercise completely.","romaji":"Kanojo wa mainichi jim ni iki, ekusasaizu o owari nuku."},{"jp":"私たちはこのゲームを解きぬく。","en":"We will solve this game completely.","romaji":"Watashitachi wa kono geemu o tokinuku."}],"example":"彼は一日中本を読みぬく。","exampleMeaning":"He will read the book all day long."},{"pattern":"Noun+のいかんだ","meaning":"Depends on; up to","formation":"Noun + のいかんだ/Noun + のいかんでは","examples":[{"jp":"彼が来るのいかんで決めよう。","en":"Let's decide depending on whether he comes or not.","romaji":"Kare ga kuru no ikan de kimeyou."},{"jp":"試験の結果のいかんで留年が決まります。","en":"Whether you repeat a year or not depends on the test results.","romaji":"Shiken no kekka no ikan de ryuunen ga kimarimasu."},{"jp":"天気のいかんでは、ピクニックをキャンセルします。","en":"I'll cancel the picnic depending on the weather.","romaji":"Tenki no ikan de wa, pikunikku o kyanseru shimasu."},{"jp":"彼の回答のいかんで、我々の次の行動が決まる。","en":"Our next action depends on his response.","romaji":"Kare no kaitou no ikan de, wareware no tsugi no koudou ga kimaru."}],"example":"彼が来るのいかんで決めよう。","exampleMeaning":"Let's decide depending on whether he comes or not."},{"pattern":"Noun のいかんでは","meaning":"It depends on the Noun","formation":"Noun + のいかんでは","examples":[{"jp":"試験の結果のいかんでは、大学の入学許可を得られるかどうかが決まります。","en":"Whether you can get permission to enter university depends on the result of the exam.","romaji":"Shiken no kekka no ikan dewa, daigaku no nyuugaku kyoka o erareru ka douka ga kimarimasu."},{"jp":"天気のいかんでは、ピクニックを延期するかもしれません。","en":"Depending on the weather, we might delay the picnic.","romaji":"Tenki no ikan dewa, pikunikku o enki suru kamoshiremasen."},{"jp":"交通事情のいかんでは、遅れることがあります。","en":"Depending on the traffic conditions, I might be late.","romaji":"Koutsuujijou no ikan dewa, okureru koto ga arimasu."},{"jp":"経済の状況のいかんでは、会社の将来は決まります。","en":"Depending on the state of the economy, the company's future is determined.","romaji":"Keizai no joukyou no ikan dewa, kaisha no shourai wa kimarimasu."}],"example":"試験の結果のいかんでは、大学の入学許可を得られるかどうかが決まります。","exampleMeaning":"Whether you can get permission to enter university depends on the result of the exam."},{"pattern":"Noun のいかんにかかわらず","meaning":"Regardless of, irrespective of.","formation":"Noun + のいかんにかかわらず","examples":[{"jp":"結果のいかんにかかわらず、彼は決定を後悔しなかった。","en":"Regardless of the outcome, he didn't regret his decision.","romaji":"Kekka no ikan ni kakawarazu, kare wa kettei wo koukai shinakatta."},{"jp":"年齢のいかんにかかわらず、どんな人でも学ぶことは可能です。","en":"Regardless of age, anyone can learn.","romaji":"Nenrei no ikan ni kakawarazu, donna hito demo manabu koto wa kanou desu."},{"jp":"経験のいかんにかかわらず、始めることが大切です。","en":"Regardless of experience, it's important to start.","romaji":"Keiken no ikan ni kakawarazu, hajimeru koto ga taisetsu desu."},{"jp":"天候のいかんにかかわらず、ハイキングは予定通りに行われます。","en":"Regardless of the weather, the hiking will take place as scheduled.","romaji":"Tenkou no ikan ni kakawarazu, haikingu wa yotei doori ni okonawaremasu."}],"example":"結果のいかんにかかわらず、彼は決定を後悔しなかった。","exampleMeaning":"Regardless of the outcome, he didn't regret his decision."},{"pattern":"Noun のいかんによっては","meaning":"Depending on the matter; depending on noun","formation":"Noun + のいかんによっては","examples":[{"jp":"天気のいかんによっては、ピクニックを延期しましょう。","en":"Depending on the weather, we should postpone the picnic.","romaji":"Tenki no ikan ni yotte wa, pikunikku o enki shimashou."},{"jp":"試験の結果のいかんによっては、進学できます。","en":"You can go on to further education, depending on the result of the exam.","romaji":"Shiken no kekka no ikan ni yotte wa, shingaku dekimasu."},{"jp":"状況のいかんによっては、早期退職を考えます。","en":"Depending on the situation, I will consider early retirement.","romaji":"Joukyou no ikan ni yotte wa, souki taishoku o kangaemasu."},{"jp":"彼の反応のいかんによっては、私たちの次の行動を決めます。","en":"Depending on his reaction, we will decide our next move.","romaji":"Kare no hannou no ikan ni yotte wa, watashitachi no tsugi no koudou o kimemasu."}],"example":"天気のいかんによっては、ピクニックを延期しましょう。","exampleMeaning":"Depending on the weather, we should postpone the picnic."},{"pattern":"Noun のいかんによらず","meaning":"Means 'regardless of', 'irrespective of', or 'no matter'","formation":"Noun + のいかんによらず","examples":[{"jp":"試験の結果のいかんによらず、自分を信じ続けてください。","en":"Regardless of the test results, keep believing in yourself.","romaji":"Shiken no kekka no ikan ni yorazu, jibun o shinji tsudzukete kudasai."},{"jp":"天気のいかんによらず、毎日、ジョギングをします。","en":"Regardless of the weather, I jog every day.","romaji":"Tenki no ikan ni yorazu, mainichi, jogingu o shimasu."},{"jp":"彼の年齢のいかんによらず、彼は非常に経験豊富です。","en":"Regardless of his age, he is very experienced.","romaji":"Kare no nenrei no ikan ni yorazu, kare wa hijou ni keikenhoufu desu."},{"jp":"国籍のいかんによらず、誰でもイベントに参加できます。","en":"Regardless of nationality, anyone can participate in the event.","romaji":"Kokuseki no ikan ni yorazu, daredemo ibento ni sanka dekimasu."}],"example":"試験の結果のいかんによらず、自分を信じ続けてください。","exampleMeaning":"Regardless of the test results, keep believing in yourself."},{"pattern":"Noun のごとき Noun","meaning":"Expresses 'like' or 'as if'; something/someone resembles something else strongly.","formation":"Noun1 + のごとき + Noun2","examples":[{"jp":"彼は神のごとき存在だ。","en":"He is an existence like a god.","romaji":"Kare wa kami no gotoki sonzai da."},{"jp":"彼女の美しさは花のごときものだ。","en":"Her beauty is like a flower.","romaji":"Kanojo no utsukushisa wa hana no gotoki mono da."},{"jp":"彼は悪魔のごとき行動をした。","en":"He acted like a devil.","romaji":"Kare wa akuma no gotoki koudou o shita."},{"jp":"この地方は春のごとき気候だ。","en":"This region has a climate like spring.","romaji":"Kono chiho wa haru no gotoki kiko da."}],"example":"彼は神のごとき存在だ。","exampleMeaning":"He is an existence like a god."},{"pattern":"Noun のことだから (〜no koto dakara)","meaning":"Because it is about ~, considering it's ~","formation":"Noun + のことだから","examples":[{"jp":"彼のことだから、きっと大丈夫だと思う。","en":"Because it's him, I think it will certainly be fine.","romaji":"Kare no koto dakara, kitto daijoubu da to omou."},{"jp":"この店のことだから、料理は美味しいはずです。","en":"Considering it's this restaurant, the food should be delicious.","romaji":"Kono mise no koto dakara, ryouri wa oishii hazu desu."},{"jp":"彼女のことだから、もうすぐ到着するでしょう。","en":"Since it's her, she will probably arrive soon.","romaji":"Kanojo no koto dakara, mou sugu touchaku suru deshou."},{"jp":"この会社のことだから、もうすぐ新製品が発表されるでしょう。","en":"Given this company, a new product will probably be announced soon.","romaji":"Kono kaisha no koto dakara, mou sugu shinseihin ga happyou sareru deshou."}],"example":"彼のことだから、きっと大丈夫だと思う。","exampleMeaning":"Because it's him, I think it will certainly be fine."},{"pattern":"Noun の 嫌いがある","meaning":"Have a dislike for a particular Noun","formation":"Noun + の嫌いがある","examples":[{"jp":"彼は魚の嫌いがあるので、寿司を食べません。","en":"He has a dislike for fish, so he doesn't eat sushi.","romaji":"Kare wa sakana no kirai ga aru node, sushi o tabemasen."},{"jp":"彼女は高いところの嫌いがあるから、山登りはしない。","en":"She has a dislike for high places, so she doesn't go mountain climbing.","romaji":"Kanojo wa takai tokoro no kirai ga aru kara, yamanobori wa shinai."},{"jp":"私の父は人ごみの嫌いがあるので、混雑した場所には行かない。","en":"My father has a dislike for crowds, so he doesn't go to crowded places.","romaji":"Watashi no chichi wa hitogomi no kirai ga aru node, konzatsu shita basho ni wa ikanai."},{"jp":"子供の頃、私は野菜の嫌いがあったが、今は好きだ。","en":"When I was a child, I had a dislike for vegetables, but now I like them.","romaji":"Kodomo no koro, watashi wa yasai no kirai ga atta ga, ima wa suki da."}],"example":"彼は魚の嫌いがあるので、寿司を食べません。","exampleMeaning":"He has a dislike for fish, so he doesn't eat sushi."},{"pattern":"Noun の手前","meaning":"Expresses the idea of 'Before doing something; on the verge of'.","formation":"Noun + の手前","examples":[{"jp":"試験の手前、遊びに行くのはやめた方がいい。","en":"Just before the exam, it's better to stop going out to play.","romaji":"Shiken no temae, asobi ni iku no wa yameta hou ga ii."},{"jp":"彼女と別れる手前、思い直しました。","en":"Just before breaking up with her, I changed my mind.","romaji":"Kanojo to wakareru temae, omoinaoshimashita."},{"jp":"締め切りの手前で、やっとレポートが完成しました。","en":"I finally finished the report just before the deadline.","romaji":"Shimekiri no temae de, yatto repooto ga kansei shimashita."},{"jp":"選挙の手前、政治の話が多くなります。","en":"Just before the election, there will be a lot of political talk.","romaji":"Senkyo no temae, seiji no hanashi ga ooku narimasu."}],"example":"試験の手前、遊びに行くのはやめた方がいい。","exampleMeaning":"Just before the exam, it's better to stop going out to play."},{"pattern":"Noun の極み (〜no kiwami)","meaning":"Used to express the extreme or utmost point of something.","formation":"Noun + の極み","examples":[{"jp":"彼の料理の極みは、誰もマネできない。","en":"The pinnacle of his cooking is something nobody can imitate.","romaji":"Kare no ryouri no kiwami wa, daremo mane dekinai."},{"jp":"彼女の努力の極みが、この成功を作り出した。","en":"The extreme of her effort has created this success.","romaji":"Kanojo no doryoku no kiwami ga, kono seikou wo tsukuridashita."},{"jp":"彼は音楽の極みを追求し続けている。","en":"He continues to pursue the pinnacle of music.","romaji":"Kare wa ongaku no kiwami o tsuikyuu shitsuzukete iru."},{"jp":"この風景は美の極みだ。","en":"This scenery is the epitome of beauty.","romaji":"Kono fuukei wa bi no kiwami da."}],"example":"彼の料理の極みは、誰もマネできない。","exampleMeaning":"The pinnacle of his cooking is something nobody can imitate."},{"pattern":"Noun の 至り","meaning":"Expresses 'the height of', 'the extreme of' something.","formation":"Noun + の至り","examples":[{"jp":"彼の冗談には驚きの至りだ。","en":"His jokes are the height of surprise.","romaji":"Kare no joudan ni wa odoroki no itari da."},{"jp":"父がプロジェクトのリーダーになったのは、光栄の至りです。","en":"It is the height of honor that my father became the project leader.","romaji":"Chichi ga purojekuto no riidaa ni natta no wa, kouei no itari desu."},{"jp":"彼女の素晴らしい演技には感動の至りだった。","en":"Her wonderful performance was the height of emotion.","romaji":"Kanojo no subarashii engi ni wa kandou no itari datta."},{"jp":"その失敗は恥ずかしさの至りだった。","en":"That failure was the height of embarrassment.","romaji":"Sono shippai wa hazukashisa no itari datta."}],"example":"彼の冗談には驚きの至りだ。","exampleMeaning":"His jokes are the height of surprise."},{"pattern":"Noun はいざ知らず","meaning":"‘I can understand it for ~, but for …? (surprising)’","formation":"Noun + はいざ知らず, Noun + とは/なんて/しかし etc.","examples":[{"jp":"彼が遅れるのはいざ知らず、彼女まで遅刻するとは意外だ。","en":"Well, I can understand him being late, but even her...? That's surprising.","romaji":"Kare ga okureru no wa iza shirazu, kanojo made chikoku suru to wa igai da."},{"jp":"夏はいざ知らず、冬にアイスクリームを食べるのは寒すぎませんか？","en":"I can see eating ice cream in summer, but in winter…isn't it too cold?","romaji":"Natsu wa iza shirazu, fuyu ni aisukuriimu o taberu no wa samusugimasen ka?"},{"jp":"子供がテレビゲームに夢中になるのはいざ知らず、大人までそんなに夢中になるとは思わなかった。","en":"I can see why kids get hooked on video games, but I didn't think even adults would get that absorbed.","romaji":"Kodomo ga terebi geemu ni muchuu ni naru no wa iza shirazu, otona made sonnani muchuu ni naru to wa omowanakatta."},{"jp":"苦しい時はいざ知らず、平時でもそんなに努力するなんてすばらしい。","en":"Well, I can understand working hard in tough times, but to do so even in normal times is impressive.","romaji":"Kurushii toki wa iza shirazu, heiji demo sonnani doryoku suru nante subarashii."}],"example":"彼が遅れるのはいざ知らず、彼女まで遅刻するとは意外だ。","exampleMeaning":"Well, I can understand him being late, but even her...? That's surprising."},{"pattern":"Noun はおろか～すら","meaning":"Expresses 'not to mention ~, even ~'.","formation":"Noun1 はおろか, Noun2 すら/さえ ～","examples":[{"jp":"彼は走るはおろか、速く歩くことすらできない。","en":"He can't even walk fast, let alone run.","romaji":"Kare wa hashiru wa oroka, hayaku aruku koto sura dekinai."},{"jp":"日本語はおろか、英語さえ話しません。","en":"He doesn't even speak English, let alone Japanese.","romaji":"Nihongo wa oroka, eigo sae hanashimasen."},{"jp":"彼は食事はおろか、一日中何も飲まなかった。","en":"He didn't even drink anything all day, let alone eat a meal.","romaji":"Kare wa shokuji wa oroka, ichinichijuu nani mo nomanakatta."},{"jp":"このレストランは味はおろか、サービスさえ悪い。","en":"Never mind the taste; even the service is bad.","romaji":"Kono resutoran wa aji wa oroka, saabisu sae warui."}],"example":"彼は走るはおろか、速く歩くことすらできない。","exampleMeaning":"He can't even walk fast, let alone run."},{"pattern":"Noun はおろか～まで","meaning":"Means 'not just A, but even B'; 'let alone A, even B'.","formation":"Noun1 + はおろか + Noun2 + まで","examples":[{"jp":"彼は英語はおろか、日本語までペラペラなんです。","en":"He is not just fluent in English, but even in Japanese.","romaji":"Kare wa eigo wa oroka, nihongo made perapera nan desu."},{"jp":"彼女は数学はおろか、物理まで得意なんです。","en":"She is not just good at math, but even at physics.","romaji":"Kanojo wa suugaku wa oroka, butsuri made tokui nan desu."},{"jp":"この料理は見た目はおろか、味まで最高だ。","en":"This dish is not only visually appealing, but it even tastes fantastic.","romaji":"Kono ryouri wa mitame wa oroka, aji made saikou da."},{"jp":"彼は歌はおろか、ダンスまで上手だ。","en":"He is not just good at singing, but even at dancing.","romaji":"Kare wa uta wa oroka, dansu made umai da."}],"example":"彼は英語はおろか、日本語までペラペラなんです。","exampleMeaning":"He is not just fluent in English, but even in Japanese."},{"pattern":"Noun はおろか～も","meaning":"'Not only...but also', 'not to mention', 'to say nothing of'","formation":"Noun + はおろか + Noun + も","examples":[{"jp":"絵を描くことはおろか、字さえ書けない。","en":"Needless to say drawing pictures, he can’t even write letters.","romaji":"E wo kaku koto wa oroka, ji sae kakenai."},{"jp":"彼は英語はおろか、日本語もわからない。","en":"Needless to say English, he doesn’t even understand Japanese.","romaji":"Kare wa eigo wa oroka, nihongo mo wakaranai."},{"jp":"彼女は数学はおろか、算数も得意ではない。","en":"Needless to say mathematics, she isn’t even good at arithmetic.","romaji":"Kanojo wa suugaku wa oroka, sansuu mo tokui dewa nai."},{"jp":"彼は走ることはおろか、歩くことも難しい。","en":"Needless to say running, he finds even walking difficult.","romaji":"Kare wa hashiru koto wa oroka, aruku koto mo muzukashii."}],"example":"絵を描くことはおろか、字さえ書けない。","exampleMeaning":"Needless to say drawing pictures, he can’t even write letters."},{"pattern":"Noun はさておき","meaning":"Means 'putting aside', 'aside from', 'notwithstanding'.","formation":"Noun + はさておき","examples":[{"jp":"試験の結果はさておき、この学期はとても学ぶことが多かった。","en":"Aside from the exam results, I learned a lot this semester.","romaji":"Shiken no kekka wa sateoki, kono gakki wa totemo manabu koto ga ookatta."},{"jp":"天候はさておき、明日のピクニックは楽しみにしています。","en":"Putting aside the weather, I am looking forward to tomorrow's picnic.","romaji":"Tenkou wa sateoki, ashita no pikunikku wa tanoshimi ni shiteimasu."},{"jp":"彼の性格はさておき、彼のスキルは認めざるを得ない。","en":"Notwithstanding his personality, his skills are undeniable.","romaji":"Kare no seikaku wa sateoki, kare no sukiru wa mitomezaru wo enai."},{"jp":"彼があまりにも遅いことはさておき、彼が来ると思われること自体が問題だ。","en":"Aside from him being late, the issue is that he is expected to come at all.","romaji":"Kare ga amari ni mo osoi koto wa sateoki, kare ga kuru to omowareru koto jitai ga mondai da."}],"example":"試験の結果はさておき、この学期はとても学ぶことが多かった。","exampleMeaning":"Aside from the exam results, I learned a lot this semester."},{"pattern":"Noun + はどうであれ","meaning":"This phrase means 'regardless of' or 'no matter how…'.","formation":"Noun + はどうであれ","examples":[{"jp":"天候はどうであれ、試合は行われます。","en":"No matter what the weather is, the match will be held.","romaji":"Tenkou wa dou de are, shiai wa okonawaremasu."},{"jp":"結果はどうであれ、最善を尽くすだけです。","en":"No matter what the result is, all we can do is try our best.","romaji":"Kekka wa dou de are, saizen wo tsukusu dake desu."},{"jp":"あなたの意見はどうであれ、私は彼を信じます。","en":"No matter what your opinion is, I believe him.","romaji":"Anata no iken wa dou de are, watashi wa kare wo shinjimasu."},{"jp":"試験の結果はどうであれ、あなたには何も変わりません。","en":"No matter what the result of the test is, nothing will change for you.","romaji":"Shiken no kekka wa dou de are, anata ni wa nani mo kawarimasen."}],"example":"天候はどうであれ、試合は行われます。","exampleMeaning":"No matter what the weather is, the match will be held."},{"pattern":"Noun まみれ","meaning":"Expresses a state in which something is entirely covered or filled with something else.","formation":"Noun + まみれ","examples":[{"jp":"彼は泥まみれになって帰ってきた。","en":"He returned home covered in mud.","romaji":"Kare wa doro mamire ni natte kaette kita."},{"jp":"彼女は涙まみれになりながら告白した。","en":"She confessed while crying her eyes out.","romaji":"Kanojo wa namida mamire ni narinagara kokuhaku shita."},{"jp":"その事件後、彼はスキャンダルまみれになった。","en":"After that incident, he was completely embroiled in scandal.","romaji":"Sono jiken go, kare wa sukandaru mamire ni natta."},{"jp":"この部屋は埃まみれだ。","en":"This room is covered in dust.","romaji":"Kono heya wa hokori mamire da."}],"example":"彼は泥まみれになって帰ってきた。","exampleMeaning":"He returned home covered in mud."},{"pattern":"Noun もさることながら Noun も","meaning":"Means 'not only... but also'; the second noun is especially emphasized.","formation":"Noun1 + もさることながら + Noun2 + も","examples":[{"jp":"彼の歌唱力もさることながら、ダンスも素晴らしい。","en":"Not only his singing ability but also his dancing is wonderful.","romaji":"Kare no kashou-ryoku mo saru koto nagara, dansu mo subarashii."},{"jp":"このレストラン、味もさることながら、サービスもすばらしい。","en":"At this restaurant, not only the taste but also the service is wonderful.","romaji":"Kono resutoran, aji mo saru koto nagara, saabisu mo subarashii."},{"jp":"彼女の美しさもさることながら、その知性も魅力的だ。","en":"Not only her beauty but also her intelligence is attractive.","romaji":"Kanojo no utsukushisa mo saru koto nagara, sono chisei mo miryoku-teki da."},{"jp":"その映画、ストーリーもさることながら、音楽も素晴らしかった。","en":"In that movie, not only the story but also the music was wonderful.","romaji":"Sono eiga, sutoorii mo saru koto nagara, ongaku mo subarashikatta."}],"example":"彼の歌唱力もさることながら、ダンスも素晴らしい。","exampleMeaning":"Not only his singing ability but also his dancing is wonderful."},{"pattern":"Noun も兼ねて","meaning":"Used to express 'as well as', 'also', or 'at the same time'.","formation":"Noun + も兼ねて","examples":[{"jp":"散歩も兼ねて、公園に行きました。","en":"I went to the park, also for a walk.","romaji":"Sanpo mo kanete, kouen ni ikimashita."},{"jp":"今日は日本語の勉強も兼ねて、日本の映画を見ます。","en":"Today, I will watch a Japanese movie, also to study Japanese.","romaji":"Kyou wa Nihongo no benkyou mo kanete, Nihon no eiga wo mimasu."},{"jp":"仕事も兼ねて、海外に行く予定です。","en":"I plan to go abroad, also for work.","romaji":"Shigoto mo kanete, kaigai ni iku yotei desu."},{"jp":"旅行も兼ねて、友人の結婚式に出席します。","en":"I will attend a friend's wedding, also as a trip.","romaji":"Ryokou mo kanete, yuujin no kekkonshiki ni shusseki shimasu."}],"example":"散歩も兼ねて、公園に行きました。","exampleMeaning":"I went to the park, also for a walk."},{"pattern":"Noun も相まって","meaning":"Used to express that combined with something else, it caused a certain outcome.","formation":"Noun + も相まって","examples":[{"jp":"気候も相まって、この地域は農業に適しています。","en":"Combined with the climate, this area is suitable for agriculture.","romaji":"Kikou mo aimatte, kono chiiki wa nougyou ni tekishiteimasu."},{"jp":"彼の才能も相まって、彼は急速に昇進した。","en":"Combined with his talent, he was rapidly promoted.","romaji":"Kare no sainou mo aimatte, kare wa kyuusoku ni shoushin shita."},{"jp":"技術進歩も相まって、私たちはより効率的に仕事をこなすことができるようになりました。","en":"Combined with technological progress, we have become able to handle our work more efficiently.","romaji":"Gijutsu shinpo mo aimatte, watashitachi wa yori kouritsu-teki ni shigoto wo konasu koto ga dekiru you ni narimashita."},{"jp":"彼の努力も相まって、プロジェクトは成功しました。","en":"Combined with his efforts, the project was successful.","romaji":"Kare no doryoku mo aimatte, purojekuto wa seikou shimashita."}],"example":"気候も相まって、この地域は農業に適しています。","exampleMeaning":"Combined with the climate, this area is suitable for agriculture."},{"pattern":"Noun を おいて他に Verb ない (〜wo oite hoka ni〜nai)","meaning":"Means 'apart from ~ there's nothing else,' implying the Noun is the best or most suitable choice.","formation":"Noun + をおいて他に + Verb negative form","examples":[{"jp":"この仕事を彼に任せる人をおいて他にいない。","en":"Apart from him, there's no one else to entrust this job to.","romaji":"Kono shigoto wo kare ni makaseru hito wo oite hoka ni inai."},{"jp":"この問題を解決できるのは彼をおいて他にいない。","en":"Apart from him, there's no one else who can solve this problem.","romaji":"Kono mondai wo kaiketsu dekiru no wa kare o oite hoka ni inai."},{"jp":"この地域で美味しい麺を作る店をおいて他にない。","en":"There is no other restaurant in this area that makes delicious noodles apart from this one.","romaji":"Kono chiiki de oishii men o tsukuru mise o oite hoka ni nai."},{"jp":"彼女の歌声を超える歌手をおいて他にいない。","en":"There is no other singer who could surpass her singing voice.","romaji":"Kanojo no utagoe o koeru kashu o oite hoka ni inai."}],"example":"この仕事を彼に任せる人をおいて他にいない。","exampleMeaning":"Apart from him, there's no one else to entrust this job to."},{"pattern":"Noun をもって","meaning":"Used to indicate means, methods, or time; 'with', 'by means of', 'at'.","formation":"Noun + をもって","examples":[{"jp":"彼は誠実さをもって人々に信頼されています。","en":"He is trusted by people with his honesty.","romaji":"Kare wa seijitsusa wo motte hitobito ni shinrai sarete imasu."},{"jp":"この賞をもって、彼女の努力が認められました。","en":"With this award, her efforts were recognized.","romaji":"Kono shou wo motte, kanojo no doryoku ga mitomeraremashita."},{"jp":"彼は強い決意をもって問題に取り組んだ。","en":"He tackled the problem with strong determination.","romaji":"Kare wa tsuyoi ketsui wo motte mondai ni torikunda."},{"jp":"3月をもって、この店は閉店します。","en":"This store will close at the end of March.","romaji":"Sangatsu wo motte, kono mise wa heiten shimasu."}],"example":"彼は誠実さをもって人々に信頼されています。","exampleMeaning":"He is trusted by people with his honesty."},{"pattern":"Noun をものともせずに","meaning":"Expresses the idea that 'despite something, action was carried out', translating to 'without being fazed by something'.","formation":"Noun + をものともせずに","examples":[{"jp":"彼女は怖さをものともせずに、暗闇の中へ進んで行った。","en":"Despite her fear, she went ahead into the darkness.","romaji":"Kanojo wa kowasa wo mono tomo sezu ni, kurayami no naka e susunde itta."},{"jp":"試験のプレッシャーをものともせずに、彼は自信満々に答えた。","en":"Unfazed by the pressure of the exam, he answered with full confidence.","romaji":"Shiken no puresshaa wo mono tomo sezu ni, kare wa jishin manman ni kotaeta."},{"jp":"彼は風雪をものともせずに山を登った。","en":"He climbed the mountain unfazed by the wind and snow.","romaji":"Kare wa fuusetsu wo mono tomo sezu ni, yama wo nobotta."},{"jp":"彼は失敗をものともせずに、前に進み続けた。","en":"He continued to move forward, undeterred by failure.","romaji":"Kare wa shippai wo mono tomo sezu ni, mae ni susumi tsuzuketa."}],"example":"彼女は怖さをものともせずに、暗闇の中へ進んで行った。","exampleMeaning":"Despite her fear, she went ahead into the darkness."},{"pattern":"Noun をよそに","meaning":"Despite; Notwithstanding; Regardless of","formation":"Noun + をよそに","examples":[{"jp":"経済危機をよそに、彼は高級な車を買った。","en":"Despite the economic crisis, he bought a luxury car.","romaji":"Keizai kiki wo yoso ni, kare wa koukyuu na kuruma wo katta."},{"jp":"試験が迫るをよそに、彼は遊び続けている。","en":"Despite the approaching test, he keeps on playing.","romaji":"Shiken ga semaru wo yoso ni, kare wa asobi tsuzukete iru."},{"jp":"親の反対をよそに、彼女は彼と結婚しました。","en":"Despite her parents' opposition, she married him.","romaji":"Oya no hantai wo yoso ni, kanojo wa kare to kekkon shimashita."},{"jp":"その国の経済状況をよそに、多くの企業が進出し続けている。","en":"Despite the country's economic situation, many companies continue to expand.","romaji":"Sono kuni no keizai joukyou wo yoso ni, ooku no kigyou ga shinshutsu shi tsuzukete iru."}],"example":"経済危機をよそに、彼は高級な車を買った。","exampleMeaning":"Despite the economic crisis, he bought a luxury car."},{"pattern":"Noun を余儀なくされる","meaning":"Expresses the idea of being forced into a certain situation, 'to be compelled', 'to be obliged'.","formation":"Noun + を + 余儀なくされる","examples":[{"jp":"彼は経済的困難により、退学を余儀なくされた。","en":"Due to financial difficulties, he was forced to drop out of school.","romaji":"Kare wa keizai-teki konnan ni yori, taigaku wo yogi naku saremashita."},{"jp":"厳しい天候によって、私たちは遠足を中止する余儀なくされた。","en":"We were forced to cancel the excursion due to the severe weather.","romaji":"Kibishi tenkou ni yotte, watashitachi wa ensoku wo chushi suru yogi naku sareta."},{"jp":"怪我のため、彼は入院を余儀なくされた。","en":"Due to his injury, he was forced to be hospitalized.","romaji":"Kega no tame, kare wa nyuuin wo yogi naku sareta."},{"jp":"リストラの恐怖により、多くの従業員が転職を余儀なくされた。","en":"Fear of layoffs forced many employees to change jobs.","romaji":"Risutora no kyoufu ni yori, ooku no juugyouin ga tenshoku wo yogi naku sareta."}],"example":"彼は経済的困難により、退学を余儀なくされた。","exampleMeaning":"Due to financial difficulties, he was forced to drop out of school."},{"pattern":"Noun を前提として","meaning":"Used to express 'on the assumption of', 'based on'.","formation":"Noun + を前提として","examples":[{"jp":"成功を前提として、ビジネスプランを作成しました。","en":"We made a business plan on the assumption of success.","romaji":"Seikou wo zentei toshite, bijinesu puran wo sakusei shimashita."},{"jp":"彼の勝利を前提として、パーティーの準備を始めました。","en":"We started preparing for the party assuming his victory.","romaji":"Kare no shouri wo zentei toshite, paatii no junbi wo hajimemashita."},{"jp":"両親の理解を前提として、旅行計画を進めます。","en":"I will proceed with the travel plan based on my parents’ understanding.","romaji":"Ryoushin no rikai wo zentei toshite, ryokou keikaku wo susumemasu."},{"jp":"このプロジェクトは、資金が揃うことを前提としています。","en":"This project assumes that the funds will be in place.","romaji":"Kono purojekuto wa, shikin ga sorou koto wo zentei toshiteimasu."}],"example":"成功を前提として、ビジネスプランを作成しました。","exampleMeaning":"We made a business plan on the assumption of success."},{"pattern":"Noun を前提にして","meaning":"Assuming; presupposing; on the assumption of.","formation":"Noun + を前提にして","examples":[{"jp":"好天を前提にして、明日のピクニックの計画を立てました。","en":"We planned tomorrow's picnic assuming fine weather.","romaji":"Kouten wo zentei ni shite, ashita no pikunikku no keikaku wo tatemashita."},{"jp":"彼女の合格を前提にして、祝いのパーティーの準備を始めました。","en":"We started preparing for the celebration party assuming she would pass the exam.","romaji":"Kanojo no goukaku wo zentei ni shite, iwai no paatii no junbi wo hajimemashita."},{"jp":"経済成長を前提にして、予算案が作られた。","en":"The budget was made on the assumption of economic growth.","romaji":"Keizai seichou wo zentei ni shite, yosan-an ga tsukurareta."},{"jp":"彼の参加を前提にして、会議の日程を決めました。","en":"We decided the meeting schedule assuming his participation.","romaji":"Kare no sanka wo zentei ni shite, kaigi no nittei wo kimemashita."}],"example":"好天を前提にして、明日のピクニックの計画を立てました。","exampleMeaning":"We planned tomorrow's picnic assuming fine weather."},{"pattern":"Noun を境にして","meaning":"Means 'as a turning point', 'since (time)', or 'from (time) on'.","formation":"Noun + を境に(して)","examples":[{"jp":"父の死を境にして、彼の性格が一変した。","en":"His personality changed completely since his father's death.","romaji":"Chichi no shi wo sakai ni shite, kare no seikaku ga ippen shita."},{"jp":"試験を境にして、休暇を取る予定です。","en":"I plan to take a vacation after the exam.","romaji":"Shiken wo sakai ni shite, kyuka wo toru yotei desu."},{"jp":"春を境にして、新しい生活を始めるつもりだ。","en":"I intend to start a new life from spring onwards.","romaji":"Haru wo sakai ni shite, atarashii seikatsu o hajimeru tsumori da."},{"jp":"彼女は入学を境にして、ファッションに興味を持ち始めた。","en":"She began to take an interest in fashion from the time she entered school.","romaji":"Kanojo wa nyuugaku wo sakai ni shite, fasshon ni kyoumi o mochi hajimeta."}],"example":"父の死を境にして、彼の性格が一変した。","exampleMeaning":"His personality changed completely since his father's death."},{"pattern":"Noun を機にして","meaning":"To take the opportunity to; taking the occasion to; on the occasion of.","formation":"Noun + を機にして","examples":[{"jp":"引っ越しを機にして、家具を新しくしました。","en":"I took the opportunity of moving to get new furniture.","romaji":"Hikkoshi wo ki ni shite, kagu wo atarashiku shimashita."},{"jp":"卒業を機にして、新しい仕事を探し始めた。","en":"I started looking for a new job on the occasion of graduation.","romaji":"Sotsugyou wo ki ni shite, atarashii shigoto wo sagashi hajimeta."},{"jp":"このプロジェクトの失敗を機にして、会社全体の仕事のやり方を見直すことにした。","en":"We decided to review the way the entire company works, taking this project's failure as an opportunity.","romaji":"Kono purojekuto no shippai wo ki ni shite, kaisha zentai no shigoto no yarikata wo minaosu koto ni shita."},{"jp":"結婚を機にして、私たちは新しい町へ引っ越しました。","en":"We moved to a new town on the occasion of our marriage.","romaji":"Kekkon wo ki ni shite, watashitachi wa atarashii machi e hikkoshimashita."}],"example":"引っ越しを機にして、家具を新しくしました。","exampleMeaning":"I took the opportunity of moving to get new furniture."},{"pattern":"Noun を皮切りに / を皮切りにして","meaning":"Used to indicate the starting point of some series of events or actions; 'starting with', 'beginning with'.","formation":"Noun + を皮切りに / を皮切りにして","examples":[{"jp":"彼はその論文を皮切りにして複数の研究を開始した。","en":"Starting with that thesis, he started multiple research projects.","romaji":"Kare wa sono ronbun o kawakiri ni shite fukusū no kenkyū o kaishi shita."},{"jp":"彼女はこのコンペティションを皮切りにして彼女のダンスキャリアが飛躍的に成長した。","en":"Starting with this competition, her dance career drastically grew.","romaji":"Kanojo wa kono konpetishon o kawakiri ni shite kanojo no dansu kyaria ga hiyakuteki ni seichō shita."},{"jp":"この映画を皮切りに、彼は人気俳優としての立場を確立した。","en":"Starting with this movie, he established his position as a popular actor.","romaji":"Kono eiga o kawakiri ni, kare wa ninki haiyū to shite no tachiba o kakuritsu shita."},{"jp":"このプロジェクトを皮切りにして、会社は新たな方向性を示し始めた。","en":"Starting with this project, the company began to show a new direction.","romaji":"Kono purojekuto o kawakiri ni shite, kaisha wa arata na hōkōsei o shimeshi hajimeta."}],"example":"彼はその論文を皮切りにして複数の研究を開始した。","exampleMeaning":"Starting with that thesis, he started multiple research projects."},{"pattern":"Noun を皮切りにして","meaning":"Used to express 'Starting with', 'Beginning with'","formation":"Noun + を皮切りに (して)","examples":[{"jp":"彼はその日を皮切りにして毎日ジムに通い始めました。","en":"Starting from that day, he began to go to the gym every day.","romaji":"Kare wa sono hi o kawakiri ni shite mainichi jimu ni kayoi hajimemashita."},{"jp":"新年会を皮切りにして、今年はたくさんのイベントが開催されます。","en":"Starting with the New Year's party, a lot of events will be held this year.","romaji":"Shinnenkai o kawakiri ni shite, kotoshi wa takusan no ibento ga kaisai saremasu."},{"jp":"この映画を皮切りにして彼の人気は急上昇しました。","en":"Beginning with this movie, his popularity skyrocketed.","romaji":"Kono eiga o kawakiri ni shite kare no ninki wa kyūjōshō shimashita."},{"jp":"東京を皮切りにして、彼の展示会は全国で開かれる予定です。","en":"Starting in Tokyo, his exhibitions are set to be held nationwide.","romaji":"Tōkyō o kawakiri ni shite, kare no tenjikai wa zenkoku de hirakareru yotei desu."}],"example":"彼はその日を皮切りにして毎日ジムに通い始めました。","exampleMeaning":"Starting from that day, he began to go to the gym every day."},{"pattern":"Noun を禁じ得ない (〜wo kinjienai)","meaning":"'Cannot help but do', or 'inevitable'","formation":"Noun + を禁じ得ない","examples":[{"jp":"この結果には驚きを禁じ得ない。","en":"I can't help but be surprised at this result.","romaji":"Kono kekka ni wa odoroki o kinjienai."},{"jp":"そのニュースを聞いて、彼の成功を祝福する気持ちを禁じ得ない。","en":"Hearing that news, I can't help but feel the urge to celebrate his success.","romaji":"Sono nyūsu o kiite, kare no seikō o shukufuku suru kimochi o kinjienai."},{"jp":"彼女の美しさには感動を禁じ得ない。","en":"I can't help but be moved by her beauty.","romaji":"Kanojo no utsukushisa ni wa kandō o kinjienai."},{"jp":"彼の話を聞いて、笑いを禁じ得ない。","en":"Hearing his story, I can't help but laugh.","romaji":"Kare no hanashi o kiite, warai o kinjienai."}],"example":"この結果には驚きを禁じ得ない。","exampleMeaning":"I can't help but be surprised at this result."},{"pattern":"Noun を経て (〜wo hete)","meaning":"Expresses the idea of 'through' or 'via'; going through some process or phase.","formation":"Noun + を経て","examples":[{"jp":"彼は苦労を経て成功を手に入れた。","en":"He achieved success through hardships.","romaji":"Kare wa kurō o hete seikō o te ni ireta."},{"jp":"彼女はニューヨークを経て日本に帰国した。","en":"She returned to Japan via New York.","romaji":"Kanojo wa Nyūyōku o hete Nihon ni kikoku shita."},{"jp":"私達は長い議論を経て決定を下した。","en":"We made a decision through a long discussion.","romaji":"Watashitachi wa nagai giron o hete kettei o kudashita."},{"jp":"多くの修練を経て、彼は達人のレベルになった。","en":"Through a lot of training, he reached a master's level.","romaji":"Ōku no shuren o hete, kare wa tatsujin no reberu ni natta."}],"example":"彼は苦労を経て成功を手に入れた。","exampleMeaning":"He achieved success through hardships."},{"pattern":"Noun を踏まえて (〜wo fumaete)","meaning":"Based on; taking into account; in light of","formation":"Noun + を踏まえて","examples":[{"jp":"過去の結果を踏まえて、新たな計画を立てました。","en":"Based on previous results, we have made a new plan.","romaji":"Kako no kekka o fumaete, aratana keikaku o tatemashita."},{"jp":"現地の文化を踏まえて、プレゼンテーションを準備します。","en":"I will prepare a presentation taking into account the local culture.","romaji":"Genchi no bunka o fumaete, purezentēshon o junbi shimasu."},{"jp":"教師の意見を踏まえて、規則を変更しました。","en":"We changed the rules in light of the teachers' opinions.","romaji":"Kyōshi no iken o fumaete, kisoku o henkō shimashita."},{"jp":"最新の研究結果を踏まえて、新しい薬が開発されました。","en":"Considering the latest research findings, a new medicine has been developed.","romaji":"Saishin no kenkyū kekka o fumaete, atarashii kusuri ga kaihatsu saremashita."}],"example":"過去の結果を踏まえて、新たな計画を立てました。","exampleMeaning":"Based on previous results, we have made a new plan."},{"pattern":"Noun を限りに","meaning":"Expresses the idea of 'as of', 'with', or 'from', indicating the end of something or a point of change.","formation":"Noun + を限りに","examples":[{"jp":"今年度を限りに、この大学での教授活動を終えるつもりです。","en":"I intend to end my teaching activities at this university as of this academic year.","romaji":"Konnendo o kagiri ni, kono daigaku de no kyouju katsudou o oeru tsumori desu."},{"jp":"今日を限りに、タバコを吸うのをやめます。","en":"As of today, I will stop smoking.","romaji":"Kyou o kagiri ni, tabako o suu no o yamemasu."},{"jp":"3月31日を限りに、会社を退職します。","en":"I will leave the company as of March 31.","romaji":"3-gatsu 31-nichi o kagiri ni, kaisha o taishoku shimasu."},{"jp":"来週を限りに、この番組は終了します。","en":"This program will end as of next week.","romaji":"Raishuu o kagiri ni, kono bangumi wa shuuryou shimasu."}],"example":"今年度を限りに、この大学での教授活動を終えるつもりです。","exampleMeaning":"I intend to end my teaching activities at this university as of this academic year."},{"pattern":"Noun 並み","meaning":"Indicates 'like' or 'as' something or someone; 'equivalent to', 'around'.","formation":"Noun + 並み","examples":[{"jp":"彼はプロのボクサー並みの力を持っています。","en":"He has power equivalent to a professional boxer.","romaji":"Kare wa puro no bokusaa nami no chikara o motte imasu."},{"jp":"彼女の料理の腕前はレストラン並みです。","en":"Her cooking skills are like those of a restaurant.","romaji":"Kanojo no ryouri no udemae wa resutoran nami desu."},{"jp":"このエリアの夏は砂漠並みの暑さです。","en":"The summer heat in this area is like a desert.","romaji":"Kono eria no natsu wa sabaku nami no atsusa desu."},{"jp":"今日の仕事は社長並みの忙しさだった。","en":"Today's work was as busy as a president's.","romaji":"Kyou no shigoto wa shachou nami no isogashisa datta."}],"example":"彼はプロのボクサー並みの力を持っています。","exampleMeaning":"He has power equivalent to a professional boxer."},{"pattern":"Noun + 前提で (Noun + zentei de)","meaning":"Expresses a condition or requirement for something to be established: 'on the assumption that', 'under the condition of'.","formation":"Noun + 前提で","examples":[{"jp":"説明できる英語力がある前提で、この仕事を引き受けてください。","en":"Please take on this job on the assumption that you have enough English skills to explain.","romaji":"Setsumei dekiru eigo-ryoku ga aru zentei de, kono shigoto o hikiukete kudasai."},{"jp":"彼が一緒に行く前提で、旅行の計画を立てました。","en":"I planned the trip on the assumption that he would go together.","romaji":"Kare ga issho ni iku zentei de, ryokou no keikaku o tatemashita."},{"jp":"成功する前提で、このプロジェクトを進めています。","en":"We are moving forward with this project on the assumption that we will succeed.","romaji":"Seikou suru zentei de, kono purojekuto o susumete imasu."},{"jp":"雨が降らない前提で、ピクニックの準備をしました。","en":"I prepared for the picnic under the condition that it wouldn't rain.","romaji":"Ame ga furanai zentei de, pikunikku no junbi o shimashita."}],"example":"説明できる英語力がある前提で、この仕事を引き受けてください。","exampleMeaning":"Please take on this job on the assumption that you have enough English skills to explain."},{"pattern":"Verbる / Noun(である) + 限り(は) (kagiri (wa))","meaning":"Expresses 'as long as', 'while this condition is true'.","formation":"Verb-dictionary form + 限り(は)\nNoun(である) + 限り(は)","examples":[{"jp":"私が生きている限りは、あなたを支えます。","en":"As long as I'm alive, I will support you.","romaji":"Watashi ga ikite iru kagiri wa, anata o sasaemasu."},{"jp":"子供が学校に通っている限り、私たちは彼らを守ります。","en":"As long as the kids are going to school, we will protect them.","romaji":"Kodomo ga gakkou ni kayotte iru kagiri, watashitachi wa karera o mamorimasu."},{"jp":"能力がある限り、最善を尽くします。","en":"I will do my best as long as I have the ability.","romaji":"Nouryoku ga aru kagiri, saizen o tsukushimasu."},{"jp":"あなたがここにいる限り、私は安心です。","en":"As long as you're here, I feel safe.","romaji":"Anata ga koko ni iru kagiri, watashi wa anshin desu."}],"example":"私が生きている限りは、あなたを支えます。","exampleMeaning":"As long as I'm alive, I will support you."},{"pattern":"Verb がてら","meaning":"Expresses doing something while doing another; 'while', 'on the occasion of'.","formation":"Verb (dictionary or -ます stem) + がてら","examples":[{"jp":"散歩がてらに郵便局へ行った。","en":"I went to the post office while taking a walk.","romaji":"Sanpo gatera ni yūbinkyoku e itta."},{"jp":"買い物がてらに友達に会いに行った。","en":"I went to see a friend while doing some shopping.","romaji":"Kaimono gatera ni tomodachi ni ai ni itta."},{"jp":"ジョギングがてらに新聞を買いに行った。","en":"I went to buy a newspaper while jogging.","romaji":"Jogingu gatera ni shinbun o kai ni itta."},{"jp":"公園でピクニックがてら読書をした。","en":"I read a book while having a picnic in the park.","romaji":"Kōen de pikunikku gatera dokusho o shita."}],"example":"散歩がてらに郵便局へ行った。","exampleMeaning":"I went to the post office while taking a walk."},{"pattern":"Verb こそすれ","meaning":"Often used in the pattern 'Xこそすれ、Y〜ない', meaning 'One might do X, but definitely not Y'.","formation":"Verb-ますstem + こそすれ、(絶対に)～ない","examples":[{"jp":"彼は友達を助けこそすれ、自分を卑下することはありません。","en":"He might help his friends, but he never belittles himself.","romaji":"Kare wa tomodachi o tasuke koso sure, jibun o higesuru koto wa arimasen."},{"jp":"彼女は料理こそすれ、掃除はほとんどしない。","en":"She might cook, but she rarely cleans.","romaji":"Kanojo wa ryōri koso sure, sōji wa hotondo shinai."},{"jp":"私の兄は勉強こそすれ、遊ぶ時間がほとんどない。","en":"He might study a lot, but he barely has time to have fun.","romaji":"Watashi no ani wa benkyō koso sure, asobu jikan ga hotondo nai."},{"jp":"母は働きこそすれ、自分のために時間を使うことはほとんどない。","en":"My mother might work a lot, but she hardly spends any time on herself.","romaji":"Haha wa hataraki koso sure, jibun no tame ni jikan o tsukau koto wa hotondo nai."}],"example":"彼は友達を助けこそすれ、自分を卑下することはありません。","exampleMeaning":"He might help his friends, but he never belittles himself."},{"pattern":"Verb させられる","meaning":"Expresses 'being forced to do something' or 'being made to do something'.","formation":"Verb-casual (non-past) + させられる","examples":[{"jp":"彼に無理やり飲ませられた。","en":"He forced me to drink against my will.","romaji":"Kare ni muriyari nomaserareta."},{"jp":"私は父に勉強させられました。","en":"My father made me study.","romaji":"Watashi wa chichi ni benkyō saseraremashita."},{"jp":"子供たちは毎日ピアノを弾かせられる。","en":"The kids are made to play the piano every day.","romaji":"Kodomo-tachi wa mainichi piano o hikaserareru."},{"jp":"私たちは強制的に早起きさせられました。","en":"We were forcibly made to wake up early.","romaji":"Watashitachi wa kyōsei-teki ni hayaoki saseraremashita."}],"example":"彼に無理やり飲ませられた。","exampleMeaning":"He forced me to drink against my will."},{"pattern":"Verb ざるを得ない","meaning":"'Cannot but', 'have no choice but to', 'forced to'","formation":"Verb-dictionary form + ざるを得ない (する → せざるを得ない)","examples":[{"jp":"この仕事が嫌ならもう辞めざるを得ない。","en":"If you hate this job, you have no choice but to quit.","romaji":"Kono shigoto ga iya nara mō yamezaru o enai."},{"jp":"試験が近いので、夜遅くまで勉強せざるを得ない。","en":"The exam is near, so I have no choice but to study late into the night.","romaji":"Shiken ga chikai no de, yoru osoku made benkyō sezaru o enai."},{"jp":"涙が止まらない。泣かざるを得ない。","en":"My tears won't stop. I can't help but cry.","romaji":"Namida ga tomaranai. Nakazaru o enai."},{"jp":"先生の命令だから、従わざるを得ない。","en":"It's the teacher's order, so I have no choice but to comply.","romaji":"Sensei no meirei dakara, shitagawazaru o enai."}],"example":"この仕事が嫌ならもう辞めざるを得ない。","exampleMeaning":"If you hate this job, you have no choice but to quit."},{"pattern":"Verb ずじまい","meaning":"Expressing regret for not having done something; not being able to; missing the chance to do it.","formation":"Verb-ない form (remove ない) + ずじまい","examples":[{"jp":"日本へ来たのに、一度も富士山を見ずじまいで帰国してしまった。","en":"I came to Japan but ended up going home without ever getting to see Mt. Fuji.","romaji":"Nihon e kita noni, ichidomo Fuji-san o mizu jimai de kikoku shite shimatta."},{"jp":"出張のため、彼女に会わずじまいだった。","en":"Because I was on a business trip, I ended up not meeting her.","romaji":"Shucchō no tame, kanojo ni awazu jimai datta."},{"jp":"昨日は疲れすぎて、宿題をせずじまいだ。","en":"I was too tired yesterday and ended up not doing my homework.","romaji":"Kinō wa tsukare-sugite, shukudai o sezu jimai da."},{"jp":"着物を買ったが、結局、一度も着ずじまいだ。","en":"I bought a kimono, but in the end, I never got the chance to wear it.","romaji":"Kimono o katta ga, kekkyoku, ichido mo kizu jimai da."}],"example":"日本へ来たのに、一度も富士山を見ずじまいで帰国してしまった。","exampleMeaning":"I came to Japan but ended up going home without ever getting to see Mt. Fuji."},{"pattern":"Verb ずとも (〜zu tomo)","meaning":"Means 'Even without doing (X), (Y) can still happen'.","formation":"Verb-negative stem + ずとも","examples":[{"jp":"朝ごはんを食べずとも、働くことができます。","en":"Even without eating breakfast, I can work.","romaji":"Asagohan o tabezu tomo, hataraku koto ga dekimasu."},{"jp":"車がなくとも、バスで行くことができます。","en":"Even without a car, you can go by bus.","romaji":"Kuruma ga nakutomo, basu de iku koto ga dekimasu."},{"jp":"お金がなくとも、幸せになれる。","en":"Even without money, one can be happy.","romaji":"Okane ga nakutomo, shiawase ni nareru."},{"jp":"インターネットがなくとも、情報を得る方法はいくつかあります。","en":"Even without the internet, there are several ways to obtain information.","romaji":"Intānetto ga nakutomo, jōhō o eru hōhō wa ikutsu ka arimasu."}],"example":"朝ごはんを食べずとも、働くことができます。","exampleMeaning":"Even without eating breakfast, I can work."},{"pattern":"Verb ずにはおかない","meaning":"Expresses 'cannot help but...', 'will definitely...', or 'must do something'.","formation":"Verb-ない form (remove ない) + ずにはおかない","examples":[{"jp":"彼が困っていると聞いたら、助けずにはおかない。","en":"If I hear he is in trouble, I cannot help but assist him.","romaji":"Kare ga komatte iru to kiitara, tasukezuni wa okanai."},{"jp":"食事の準備がこのままだと、手伝わずにはおかないだろう。","en":"If the meal prep stays like this, I won't be able to stop myself from helping.","romaji":"Shokuji no junbi ga kono mama da to, tetsudawazuni wa okanai darō."},{"jp":"この問題が解決しないなら、改善策を考えずにはおかない。","en":"If this issue isn't resolved, I can't help but think of a solution.","romaji":"Kono mondai ga kaiketsu shinai nara, kaizen-saku o kangaezuni wa okanai."},{"jp":"彼女が泣いているのを見たら、慰めずにはおかない。","en":"When I see her crying, I cannot help but comfort her.","romaji":"Kanojo ga naite iru no o mitara, nagusamezuni wa okanai."}],"example":"彼が困っていると聞いたら、助けずにはおかない。","exampleMeaning":"If I hear he is in trouble, I cannot help but assist him."},{"pattern":"Verb ずにはすまない","meaning":"'Cannot do without...', 'unavoidable', 'have to'.","formation":"Verb-ない form (remove ない) + ずにはすまない","examples":[{"jp":"この問題を解決しないと、社会全体が影響を受けるので、解決せずにはすまない。","en":"Since this issue will affect the entire society if not resolved, we cannot do without solving it.","romaji":"Kono mondai o kaiketsu shinai to, shakai zentai ga eikyō o ukeru node, kaiketsu sezu ni wa sumanai."},{"jp":"これは子供たちの未来を思うと、教育改革を行わずにはすまないことだ。","en":"For the sake of the children’s future, we cannot avoid carrying out educational reforms.","romaji":"Kore wa kodomo-tachi no mirai o omou to, kyōiku kaikaku o okonawazu ni wa sumanai koto da."},{"jp":"この件については、彼に謝らずにはすまない。","en":"Regarding this matter, I can’t do without apologizing to him.","romaji":"Kono ken ni tsuite wa, kare ni ayamarazu ni wa sumanai."},{"jp":"結婚式に出席するなら、プレゼントを渡さずにはすまない。","en":"If you attend a wedding, you have to bring a gift.","romaji":"Kekkonshiki ni shusseki suru nara, purezento o watasazu ni wa sumanai."}],"example":"この問題を解決しないと、社会全体が影響を受けるので、解決せずにはすまない。","exampleMeaning":"Since this issue will affect the entire society if not resolved, we cannot do without solving it."},{"pattern":"Verb そうにない","meaning":"Expresses unlikelihood or that something does not seem likely to happen.","formation":"Verb-ますstem + そうにない","examples":[{"jp":"彼はそんなに早く走れそうにない。","en":"He doesn't seem likely to run that fast.","romaji":"Kare wa sonna ni hayaku hashire sō ni nai."},{"jp":"この書類を明日までに終わりそうにない。","en":"It doesn’t seem like I’ll be able to finish these documents by tomorrow.","romaji":"Kono shorui o ashita made ni owarisō ni nai."},{"jp":"今日雨が降りそうにない。","en":"It doesn't look like it will rain today.","romaji":"Kyō ame ga furisō ni nai."},{"jp":"彼女は間違えそうにない。","en":"She doesn’t seem likely to make a mistake.","romaji":"Kanojo wa machigae sō ni nai."}],"example":"彼はそんなに早く走れそうにない。","exampleMeaning":"He doesn't seem likely to run that fast."},{"pattern":"Verb そうもない (〜sou mo nai)","meaning":"Expresses negative potential; 'it doesn't seem like...', 'it's not likely...'.","formation":"Verb-ますstem + そうもない","examples":[{"jp":"今日中に仕事を終えそうもない。","en":"It doesn't seem like I'll finish my work today.","romaji":"Kyōjū ni shigoto o oesō mo nai."},{"jp":"雨が止みそうもない。","en":"It doesn't seem like the rain will stop.","romaji":"Ame ga yamisō mo nai."},{"jp":"彼が約束を守りそうもない。","en":"It doesn't seem like he will keep his promise.","romaji":"Kare ga yakusoku o mamorisō mo nai."},{"jp":"この難しい問題は解決しそうもない。","en":"It doesn't seem like this difficult problem will be solved.","romaji":"Kono muzukashii mondai wa kaiketsu shisō mo nai."}],"example":"今日中に仕事を終えそうもない。","exampleMeaning":"It doesn't seem like I'll finish my work today."},{"pattern":"Verb そばから (〜soba kara)","meaning":"Expresses that as soon as one action finishes, another begins immediately.","formation":"Verb-ますstem + そばから","examples":[{"jp":"掃除をするそばから子供たちが散らかす。","en":"As soon as I clean, the kids mess it up.","romaji":"Sōji o suru soba kara kodomo-tachi ga chirakasu."},{"jp":"仕事を終えるそばから新たな仕事が舞い込んできた。","en":"As soon as I finished my work, a new task came in.","romaji":"Shigoto o oeru soba kara aratana shigoto ga maikonde kita."},{"jp":"それを解決するそばからまた別の問題が出てきた。","en":"As soon as we solve that, another problem arises.","romaji":"Sore o kaiketsu suru soba kara mata betsu no mondai ga detekita."},{"jp":"眠りにつくそばから電話が鳴った。","en":"The phone rang as soon as I fell asleep.","romaji":"Nemuri ni tsuku soba kara denwa ga natta."}],"example":"掃除をするそばから子供たちが散らかす。","exampleMeaning":"As soon as I clean, the kids mess it up."},{"pattern":"Verb たが最後 (〜ta ga saigo)","meaning":"Emphasizes 'once something happens, there is no going back'; 'once', 'as soon as', etc.","formation":"Verb-casual, past (た form) + が最後","examples":[{"jp":"彼が一度怒ったが最後、誰も彼を止めることはできません。","en":"Once he gets angry, no one can stop him.","romaji":"Kare ga ichido okotta ga saigo, dare mo kare o tomeru koto wa dekimasen."},{"jp":"このゲームを始めたが最後、一晩中やり続けた。","en":"As soon as I started this game, I played it all night.","romaji":"Kono gēmu o hajimeta ga saigo, hitobanjū yari tsuzuketa."},{"jp":"彼女が部屋を出たが最後、二度と戻ってこなかった。","en":"The moment she left the room, she never came back.","romaji":"Kanojo ga heya o deta ga saigo, nido to modotte konakatta."},{"jp":"私がその橋を渡ったが最後、それが最後の別れだった。","en":"Once I crossed that bridge, it was our final goodbye.","romaji":"Watashi ga sono hashi o watatta ga saigo, sore ga saigo no wakare datta."}],"example":"彼が一度怒ったが最後、誰も彼を止めることはできません。","exampleMeaning":"Once he gets angry, no one can stop him."},{"pattern":"Verb たことにしてください","meaning":"Asking someone to pretend or accept that something has already happened or taken a certain state.","formation":"Verb (past, casual) + ことにしてください","examples":[{"jp":"昨日のことは忘れたことにしてください。","en":"Please act as if you have forgotten about yesterday.","romaji":"Kinou no koto wa wasureta koto ni shite kudasai."},{"jp":"私がここに来たことを誰にも言わないで、秘密にしたことにしてください。","en":"Please don't tell anyone that I came here; act as if it’s a secret.","romaji":"Watashi ga koko ni kita koto o dare ni mo iwanaide, himitsu ni shita koto ni shite kudasai."},{"jp":"彼が間違えたと思ったことにしてください。","en":"Please pretend that you think he made a mistake.","romaji":"Kare ga machigaeta to omotta koto ni shite kudasai."},{"jp":"彼女が帰ったことにしてください。","en":"Let’s pretend that she has gone home.","romaji":"Kanojo ga kaetta koto ni shite kudasai."}],"example":"昨日のことは忘れたことにしてください。","exampleMeaning":"Please act as if you have forgotten about yesterday."},{"pattern":"Verb たら Verb たで","meaning":"Conveys that if something happens (or doesn’t happen), there is a particular consequence or situation either way.","formation":"Verb-た form + ら + (same Verb-た form) + で","examples":[{"jp":"行ったら行ったで大変だし、行かなかったら行かなかったで後悔しそうだ。","en":"If I go, it’s a hassle; if I don’t go, I’ll regret it.","romaji":"Ittara itta de taihen da shi, ikanakattara ikanakatta de kōkai shisō da."},{"jp":"買ったら買ったでお金がなくなるし、買わなかったら買わなかったで後で欲しくなる。","en":"If I buy it, I’ll run out of money; if I don’t buy it, I’ll want it later.","romaji":"Kattara katta de okane ga naku naru shi, kawanakattara kawanakatta de ato de hoshiku naru."},{"jp":"作ったら作ったで食べきれないし、作らなかったら作らなかったでお腹が空く。","en":"If I cook, I can’t finish it all; if I don’t, I’ll be hungry.","romaji":"Tsukuttara tsukutta de tabekirenai shi, tsukuranakattara tsukuranakatta de onaka ga suku."},{"jp":"旅行に出かけたら出かけたで疲れるし、家にいたらいたで退屈する。","en":"If I go on a trip, I'll get tired, but if I stay home, I'll be bored.","romaji":"Ryokō ni dekaketara dekaketa de tsukareru shi, ie ni itara itada de taikutsu suru."}],"example":"行ったら行ったで大変だし、行かなかったら行かなかったで後悔しそうだ。","exampleMeaning":"If I go, it’s a hassle; if I don’t go, I’ll regret it."},{"pattern":"Verb たら きりがない","meaning":"Indicates an endless or unending cycle once an action is started; 'if one starts doing something, it will not stop.'","formation":"Verb-た form + ら + きりがない","examples":[{"jp":"このエンジンを修理したら、またすぐ壊れて、直したらきりがない。","en":"If I fix this engine, it breaks again, and if I fix it again, it never ends.","romaji":"Kono enjin o shuuri shitara, mata sugu kowarete, naoshitara kiri ga nai."},{"jp":"飲み始めたらきりがない。","en":"Once I start drinking, I never stop.","romaji":"Nomihajimetara kiri ga nai."},{"jp":"彼女にお金を貸したら、きりがない。","en":"If I lend her money, there will be no end to it.","romaji":"Kanojo ni okane o kashitara, kiri ga nai."},{"jp":"彼の話を聞き始めたらきりがない。","en":"Once you start listening to his stories, it never ends.","romaji":"Kare no hanashi o kikihajimetara kiri ga nai."}],"example":"このエンジンを修理したら、またすぐ壊れて、直したらきりがない。","exampleMeaning":"If I fix this engine, it breaks again, and if I fix it again, it never ends."},{"pattern":"Verb たら最後 (〜tara saigo)","meaning":"Expresses that once a certain action happens, the situation changes irreversibly—usually in a negative way.","formation":"Verb-た form + ら最後","examples":[{"jp":"このゲームを始めたら最後、時間の経つのを忘れてしまいます。","en":"Once you start this game, you completely lose track of time.","romaji":"Kono gēmu o hajimetara saigo, jikan no tatsu no o wasurete shimaimasu."},{"jp":"彼はビールを一杯飲み始めたら最後、止まらなくなります。","en":"Once he starts drinking a beer, he can't stop.","romaji":"Kare wa bīru o ippai nomihajimetara saigo, tomaranaku narimasu."},{"jp":"この本を読み始めたら最後、一気に読破してしまいました。","en":"Once I started reading this book, I ended up finishing it in one go.","romaji":"Kono hon o yomihajimetara saigo, ikki ni dokuha shite shimaimashita."},{"jp":"彼を怒らせたら最後、なかなか許してもらえないよ。","en":"Once you make him angry, he won't forgive you so easily.","romaji":"Kare o okorasetara saigo, nakanaka yurushite moraenai yo."}],"example":"このゲームを始めたら最後、時間の経つのを忘れてしまいます。","exampleMeaning":"Once you start this game, you completely lose track of time."},{"pattern":"Verb つ Verb つ","meaning":"Expresses two alternating actions happening repeatedly.","formation":"Verb-ますstem + つ + Verb-ますstem + つ","examples":[{"jp":"朝から晩まで働きつ勉強しつで、疲れてしまった。","en":"I’ve been working and studying from morning till night, and now I’m exhausted.","romaji":"Asa kara ban made hataraki tsu benkyō shi tsu de, tsukarete shimatta."},{"jp":"彼は話しつ笑いつして楽しんでいた。","en":"He was talking and laughing, having a good time.","romaji":"Kare wa hanashi tsu warai tsu shite tanoshinde ita."},{"jp":"子供たちは食べつ遊びつしていた。","en":"The children were eating and playing.","romaji":"Kodomo-tachi wa tabe tsu asobi tsu shite ita."},{"jp":"私は読みつ書きつして過ごした。","en":"I spent my time reading and writing.","romaji":"Watashi wa yomi tsu kaki tsu shite sugoshita."}],"example":"朝から晩まで働きつ勉強しつで、疲れてしまった。","exampleMeaning":"I’ve been working and studying from morning till night, and now I’m exhausted."},{"pattern":"Verb てからというもの","meaning":"Expresses that ever since a certain event happened, a condition has continued until now.","formation":"Verb-て form + からというもの","examples":[{"jp":"彼女と別れてからというもの、一人で過ごす時間が増えました。","en":"Ever since I broke up with her, I've spent more time alone.","romaji":"Kanojo to wakarete kara to iu mono, hitori de sugosu jikan ga fuemashita."},{"jp":"子供が生まれてからというもの、自由な時間がなくなった。","en":"Since the baby was born, I have had no free time.","romaji":"Kodomo ga umarete kara to iu mono, jiyū na jikan ga nakunatta."},{"jp":"新しい仕事を始めてからというもの、毎日忙しくなりました。","en":"Ever since I started my new job, I've been busy every day.","romaji":"Atarashii shigoto o hajimete kara to iu mono, mainichi isogashiku narimashita."},{"jp":"大学に入ってからというもの、スポーツをする時間がなくなった。","en":"I haven’t had time to play sports since I entered university.","romaji":"Daigaku ni haitte kara to iu mono, supōtsu o suru jikan ga nakunatta."}],"example":"彼女と別れてからというもの、一人で過ごす時間が増えました。","exampleMeaning":"Ever since I broke up with her, I've spent more time alone."},{"pattern":"Verb てこそ","meaning":"Emphasizes 'only by doing something, a certain result or realization can occur.'","formation":"Verb-て form + こそ","examples":[{"jp":"実際に使ってこそ、その価値を理解できる。","en":"You can only understand its value by actually using it.","romaji":"Jissai ni tsukatte koso, sono kachi o rikai dekiru."},{"jp":"自分で経験してこそ、大切なことが学べる。","en":"Only by experiencing it yourself can you learn what’s truly important.","romaji":"Jibun de keiken shite koso, taisetsu na koto ga manaberu."},{"jp":"失敗してこそ、成功の味がわかる。","en":"Only by failing do you really understand the taste of success.","romaji":"Shippai shite koso, seikō no aji ga wakaru."},{"jp":"努力してこそ、何かを成し遂げることができる。","en":"Only through making an effort can you accomplish anything.","romaji":"Doryoku shite koso, nanika o nashitogeru koto ga dekiru."}],"example":"実際に使ってこそ、その価値を理解できる。","exampleMeaning":"You can only understand its value by actually using it."},{"pattern":"Verb ては","meaning":"Expresses a repeated pattern or cycle, often implying a frustrating outcome; 'whenever X happens, Y happens again.'","formation":"Verb-て form + は","examples":[{"jp":"彼女に会っては、いつも緊張してしまいます。","en":"Whenever I meet her, I get nervous.","romaji":"Kanojo ni atte wa, itsumo kinchō shite shimaimasu."},{"jp":"この部屋を掃除しては乱雑になり、片づけては散らかる。","en":"Whenever I clean this room, it gets messy again, and whenever I tidy it, it gets cluttered again.","romaji":"Kono heya o sōji shite wa konzatsu ni nari, katadzukete wa chirakaru."},{"jp":"運動しては食べ、食べては運動する生活が続いている。","en":"I keep exercising and then eating, and then eating and exercising.","romaji":"Undō shite wa tabe, tabete wa undō suru seikatsu ga tsudzuite iru."},{"jp":"勉強しては寝て、寝ては勉強する日々です。","en":"My days are spent studying and then sleeping, and then sleeping and studying.","romaji":"Benkyō shite wa nete, nete wa benkyō suru hibi desu."}],"example":"彼女に会っては、いつも緊張してしまいます。","exampleMeaning":"Whenever I meet her, I get nervous."},{"pattern":"Verb ては Verb","meaning":"Expresses a repeated pattern of action; translates as 'every time', 'whenever', etc.","formation":"Verb-て form + は + Verb","examples":[{"jp":"私が通勤しては、電子書籍を読んでいます。","en":"Whenever I commute, I read e-books.","romaji":"Watashi ga tsūkin shite wa, denshi shoseki o yonde imasu."},{"jp":"友達が部屋に来ては、ゲームをしています。","en":"Every time my friend comes to my room, we play games.","romaji":"Tomodachi ga heya ni kite wa, gēmu o shite imasu."},{"jp":"彼が酒を飲んでは、運転を止めさせています。","en":"Whenever he drinks alcohol, I make him stop driving.","romaji":"Kare ga sake o nonde wa, unten o tome sasete imasu."},{"jp":"私が新しい曲を作っては、すぐに録音します。","en":"Every time I create a new song, I record it immediately.","romaji":"Watashi ga atarashii kyoku o tsukutte wa, sugu ni rokuon shimasu."}],"example":"私が通勤しては、電子書籍を読んでいます。","exampleMeaning":"Whenever I commute, I read e-books."},{"pattern":"Verb てまでも","meaning":"Expresses 'even if it means doing...', 'no matter what it takes'.","formation":"Verb-て form + までも","examples":[{"jp":"試験に合格するために、寝る時間を削ってまでも勉強します。","en":"I will study to pass the exam, even if it means cutting down on sleep.","romaji":"Shiken ni gōkaku suru tame ni, neru jikan o kezutte mademo benkyō shimasu."},{"jp":"彼女と結婚できるなら、どんな苦労をしてまでもお金を貯めたい。","en":"If I can marry her, I'll save money no matter what hardships it takes.","romaji":"Kanojo to kekkon dekiru nara, donna kurō o shite mademo okane o tametai."},{"jp":"この会社で働きたいので、長時間かけてまでも通います。","en":"Because I want to work at this company, I'll commute even if it means spending hours traveling.","romaji":"Kono kaisha de hatarakitai node, chōjikan kakete mademo kayoimasu."},{"jp":"彼の快復のためなら、何をしてまでも支えたい。","en":"For his recovery, I'll support him no matter what it takes.","romaji":"Kare no kaifuku no tame nara, nani o shite mademo sasaetai."}],"example":"試験に合格するために、寝る時間を削ってまでも勉強します。","exampleMeaning":"I will study to pass the exam, even if it means cutting down on sleep."},{"pattern":"Verb てみせる","meaning":"'Show by doing', 'demonstrate', 'prove by action'.","formation":"Verb-て form + みせる","examples":[{"jp":"彼はそのパズルを解いてみせた。","en":"He solved the puzzle to show me.","romaji":"Kare wa sono pazuru o toite miseta."},{"jp":"私はこの仕事ができることをやってみせます。","en":"I will do this job to prove that I can.","romaji":"Watashi wa kono shigoto ga dekiru koto o yatte misemasu."},{"jp":"彼女は試験に合格するために一生懸命勉強してみせました。","en":"She studied hard to prove she could pass the exam.","romaji":"Kanojo wa shiken ni gōkaku suru tame ni isshōkenmei benkyō shite misemashita."},{"jp":"彼は自分が何も恐れていないと跳んでみせた。","en":"He jumped to show he wasn’t afraid of anything.","romaji":"Kare wa jibun ga nanimo osorete inai to tonde miseta."}],"example":"彼はそのパズルを解いてみせた。","exampleMeaning":"He solved the puzzle to show me."},{"pattern":"Verb てやまない","meaning":"Used with certain emotional/mental verbs to show a strong, unceasing emotion: 'can't stop', 'never cease to'.","formation":"Verb-て form + やまない (common with certain verbs)","examples":[{"jp":"私は母を思ってやまない。","en":"I can't stop thinking of my mother.","romaji":"Watashi wa haha o omotte yamanai."},{"jp":"彼は彼女を愛してやまない。","en":"He loves her beyond measure.","romaji":"Kare wa kanojo o aishite yamanai."},{"jp":"彼は日本の文化を尊敬してやまない。","en":"He has unceasing respect for Japanese culture.","romaji":"Kare wa Nihon no bunka o sonkei shite yamanai."},{"jp":"彼女の成功を願ってやまない。","en":"I can’t stop hoping for her success.","romaji":"Kanojo no seikō o negatte yamanai."}],"example":"私は母を思ってやまない。","exampleMeaning":"I can't stop thinking of my mother."},{"pattern":"Verb ないではおかない","meaning":"Means 'cannot help but do', 'will definitely do', or 'is bound to happen'.","formation":"Verb-ない form + ではおかない","examples":[{"jp":"彼女は毎回遅刻をしては、先生に怒られないではおかない。","en":"Every time she's late, she inevitably gets scolded by the teacher.","romaji":"Kanojo wa maikai chikoku o shite wa, sensei ni okorarenaide wa okanai."},{"jp":"美味しいものがあれば、彼は食べないではおかない。","en":"If there's delicious food, he can't help but eat it.","romaji":"Oishii mono ga areba, kare wa tabenai de wa okanai."},{"jp":"この小説は感動的で、読めば涙を流さないではおかない。","en":"This novel is so moving that you can't help but shed tears when you read it.","romaji":"Kono shōsetsu wa kandōteki de, yomeba namida o nagasanai de wa okanai."},{"jp":"毎日練習しているから、試合では勝たないではおかないだろう。","en":"He practices every day, so he's bound to win the match.","romaji":"Mainichi renshū shite iru kara, shiai de wa katanai de wa okanai darō."}],"example":"彼女は毎回遅刻をしては、先生に怒られないではおかない。","exampleMeaning":"Every time she's late, she inevitably gets scolded by the teacher."},{"pattern":"Verb ないではすまない","meaning":"'Cannot end without doing', 'must do'—an unavoidable moral or social necessity.","formation":"Verb-ない form + ではすまない","examples":[{"jp":"失敗をしたら、謝らないではすまない。","en":"If you make a mistake, you have to apologize—there’s no way around it.","romaji":"Shippai o shitara, ayamaranai de wa sumanai."},{"jp":"この問題は重大なので、報告しないではすまない。","en":"This issue is so serious that I must report it.","romaji":"Kono mondai wa jūdai na node, hōkoku shinai de wa sumanai."},{"jp":"この映画はとても感動的で、泣かないではすまない。","en":"This movie is so moving that you can’t help but cry.","romaji":"Kono eiga wa totemo kandōteki de, nakanai de wa sumanai."},{"jp":"子供が間違えたら、教えないではすまない。","en":"If a child makes a mistake, you must correct them—there’s no avoiding it.","romaji":"Kodomo ga machigaetara, oshienai de wa sumanai."}],"example":"失敗をしたら、謝らないではすまない。","exampleMeaning":"If you make a mistake, you have to apologize—there’s no way around it."},{"pattern":"Verb ないまでも","meaning":"'Even if not to the extent of...', 'although not completely...'.","formation":"Verb-ない form + までも","examples":[{"jp":"全てを理解しないまでも、基本的なことは分かってほしい。","en":"Even if you don't understand everything, I'd like you at least to grasp the basics.","romaji":"Subete o rikai shinai made mo, kihonteki na koto wa wakatte hoshii."},{"jp":"会えないまでも、電話で声を聞きたい。","en":"Even if we can’t meet, I still want to hear your voice over the phone.","romaji":"Aenai made mo, denwa de koe o kikitai."},{"jp":"毎日は無理にしても、週に一度くらいはジョギングを続けたい。","en":"Even if I can't do it every day, I want to at least keep jogging once a week.","romaji":"Mainichi wa muri ni shite mo, shū ni ichido kurai wa jogingu o tsuzuketai."},{"jp":"全員に気に入られないまでも、誠実に向き合いたい。","en":"Even if not everyone will like me, I still want to face them sincerely.","romaji":"Zen'in ni ki ni irarenai made mo, seijitsu ni mukiai tai."}],"example":"全てを理解しないまでも、基本的なことは分かってほしい。","exampleMeaning":"Even if you don't understand everything, I'd like you at least to grasp the basics."},{"pattern":"Verb ないものだろうか","meaning":"Expressing hope or wonder if something can be done: 'Isn't there a way...?', 'Can't we...?'","formation":"Verb-negative (often negative potential) + ものだろうか","examples":[{"jp":"もっと時間があれば、ここに来られないものだろうか。","en":"If I had more time, wouldn't it be possible to come here?","romaji":"Motto jikan ga areba, koko ni korarenai mono darou ka."},{"jp":"彼女にもっとよく説明すれば、理解できないものだろうか。","en":"If I explain it better to her, wouldn't she understand?","romaji":"Kanojo ni motto yoku setsumei sureba, rikai dekinai mono darou ka."},{"jp":"この問題を解決する方法はないものだろうか。","en":"Isn't there a way to solve this problem?","romaji":"Kono mondai o kaiketsu suru houhou wa nai mono darou ka."},{"jp":"自分の間違いを認められないものだろうか。","en":"Can't I admit my own mistakes?","romaji":"Jibun no machigai o mitomerarenai mono darou ka."}],"example":"もっと時間があれば、ここに来られないものだろうか。","exampleMeaning":"If I had more time, wouldn't it be possible to come here?"},{"pattern":"Verb ないものでもない","meaning":"Expresses the idea that it's not entirely impossible or non-existent: 'It's not that I don't...', 'It's not that there aren't...'","formation":"Verb-negative form (ない form) + ものでもない","examples":[{"jp":"旅行に行きたいと思わないものでもない。","en":"It's not that I never want to travel.","romaji":"Ryokou ni ikitai to omowanai mono demo nai."},{"jp":"彼の言ったこと全部が間違いないものでもない。","en":"It's not that everything he said is completely free from mistakes.","romaji":"Kare no itta koto zenbu ga machigai nai mono demo nai."},{"jp":"その問題が解けないものでもない。","en":"It's not that the problem can't be solved.","romaji":"Sono mondai ga tokenai mono demo nai."},{"jp":"彼に会いたくないものでもない。","en":"It's not that I don't want to see him.","romaji":"Kare ni aitakunai mono demo nai."}],"example":"旅行に行きたいと思わないものでもない。","exampleMeaning":"It's not that I never want to travel."},{"pattern":"Verb の ない Noun","meaning":"Used to modify a noun with a negative verb form; 'a Noun without (Verb)'.","formation":"Verb in negative form + の + Noun","examples":[{"jp":"笑いのない人生は、つまらない。","en":"A life without laughter is boring.","romaji":"Warai no nai jinsei wa, tsumaranai."},{"jp":"水のない場所には、人は住めない。","en":"People cannot live in a place without water.","romaji":"Mizu no nai basho ni wa, hito wa sumenai."},{"jp":"言葉のない世界は、想像するのが難しい。","en":"It's hard to imagine a world without words.","romaji":"Kotoba no nai sekai wa, souzou suru no ga muzukashii."},{"jp":"愛のない結婚は、長続きしない。","en":"A marriage without love will not last.","romaji":"Ai no nai kekkon wa, nagatsudzuki shinai."}],"example":"笑いのない人生は、つまらない。","exampleMeaning":"A life without laughter is boring."},{"pattern":"Verb ば きりがない (〜ba kiri ga nai)","meaning":"Indicates there's no end once you start listing, doing, or saying something: 'If one starts to..., there will be no end.'","formation":"Verb-conditional form (ば) + きりがない","examples":[{"jp":"悪口を言い始めればきりがない。","en":"Once I start speaking ill of someone, there's no end.","romaji":"Waruguchi o iihajimereba kiri ga nai."},{"jp":"彼の欠点を数えればきりがない。","en":"If I start counting his flaws, there will be no end.","romaji":"Kare no ketten o kazoereba kiri ga nai."},{"jp":"この国の美しい場所は、挙げればきりがない。","en":"If I start listing this country's beautiful places, there's no end.","romaji":"Kono kuni no utsukushii basho wa, agereba kiri ga nai."},{"jp":"ほかにも例を挙げればきりがない。","en":"If I start giving more examples, there will be no end.","romaji":"Hoka ni mo rei o agereba kiri ga nai."}],"example":"悪口を言い始めればきりがない。","exampleMeaning":"Once I start speaking ill of someone, there's no end."},{"pattern":"Verb もしないで","meaning":"Means 'without even doing'.","formation":"Verb (masu stem) + もしないで","examples":[{"jp":"調べもしないで、答えを書きました。","en":"I wrote the answer without even investigating.","romaji":"Shirabe mo shinai de, kotae o kakimashita."},{"jp":"彼は試験を勉強もしないで、テストに合格した。","en":"He passed the test without even studying.","romaji":"Kare wa shiken o benkyou mo shinai de, tesuto ni goukaku shita."},{"jp":"彼女はその本を読みもしないで、レポートを書いた。","en":"She wrote her report without even reading the book.","romaji":"Kanojo wa sono hon o yomi mo shinai de, repooto o kaita."},{"jp":"準備もしないで、プレゼンテーションを始めました。","en":"He started the presentation without even preparing.","romaji":"Junbi mo shinai de, purezenteeshon o hajimemashita."}],"example":"調べもしないで、答えを書きました。","exampleMeaning":"I wrote the answer without even investigating."},{"pattern":"Verb やしない","meaning":"Expresses a strong denial or refusal: 'I would never...', 'No way I would...'.","formation":"Verb (masu stem) + やしない","examples":[{"jp":"こんな時に泣きやしない。","en":"I would never cry at a time like this.","romaji":"Konna toki ni naki-yashinai."},{"jp":"私が彼を助けやしない。","en":"There's no way I'd help him.","romaji":"Watashi ga kare o tasuke-yashinai."},{"jp":"彼がそんなことを言いやしない。","en":"He would never say such a thing.","romaji":"Kare ga sonna koto o ii-yashinai."},{"jp":"私がそんな高価なものを買いやしない。","en":"There's no way I'd buy something so expensive.","romaji":"Watashi ga sonna kouka na mono o kai-yashinai."}],"example":"こんな時に泣きやしない。","exampleMeaning":"I would never cry at a time like this."},{"pattern":"Verb よう","meaning":"Expresses 'the way/manner of doing something' or 'in order to / so that / try to'.","formation":"Verb (dictionary or negative form) + ように (する / etc.)","examples":[{"jp":"この問題を解くように努力します。","en":"I will try to solve this problem.","romaji":"Kono mondai o toku you ni doryoku shimasu."},{"jp":"彼が言ったようにやりましょう。","en":"Let's do it the way he said.","romaji":"Kare ga itta you ni yarimashou."},{"jp":"毎日走るようにしています。","en":"I make it a point to run every day.","romaji":"Mainichi hashiru you ni shiteimasu."},{"jp":"自分の心を大切にするように。","en":"Try to take care of your own heart.","romaji":"Jibun no kokoro o taisetsu ni suru you ni."}],"example":"この問題を解くように努力します。","exampleMeaning":"I will try to solve this problem."},{"pattern":"Verb ようか Verbるまいか","meaning":"Expresses indecision: 'Should I do it or not?'.","formation":"Verb-volitional form + か + Verb-volitional negative form (まい) + か","examples":[{"jp":"彼に話そうか話すまいか、本当に迷っている。","en":"I'm really unsure whether to talk to him or not.","romaji":"Kare ni hanasou ka hanasu mai ka, hontou ni mayotte iru."},{"jp":"試験を受けようか受けまいか迷っています。","en":"I'm wondering whether to take the exam or not.","romaji":"Shiken o ukeyou ka ukemai ka mayotte imasu."},{"jp":"あの人に謝ろうか謝るまいか考えています。","en":"I'm considering whether to apologize to that person or not.","romaji":"Ano hito ni ayamarou ka ayamaru mai ka kangaete imasu."},{"jp":"進学しようかしまいか悩んでいる。","en":"I'm worried about whether to continue my studies or not.","romaji":"Shingaku shiyou ka shimai ka nayande iru."}],"example":"彼に話そうか話すまいか、本当に迷っている。","exampleMeaning":"I'm really unsure whether to talk to him or not."},{"pattern":"Verb ようが Verb るまいが","meaning":"Expresses 'whether or not', 'no matter if something happens or not'.","formation":"Verb-volitional form + が + Verb-negative volitional form + が","examples":[{"jp":"彼が来ようが来るまいが、パーティーは始まります。","en":"Whether he comes or not, the party will start.","romaji":"Kare ga koyou ga kurumai ga, paatii wa hajimarimasu."},{"jp":"勉強しようがしまいが、テストの結果は変わらない。","en":"Whether you study or not, the test results won't change.","romaji":"Benkyou shiyou ga shimai ga, tesuto no kekka wa kawaranai."},{"jp":"雨が降ろうが降るまいが、ピクニックに行きます。","en":"Whether it rains or not, we're going on a picnic.","romaji":"Ame ga furou ga furumai ga, pikunikku ni ikimasu."},{"jp":"暑かろうが寒かろうが、毎日ジョギングします。","en":"Whether it's hot or cold, I jog every day.","romaji":"Atsukarou ga samukarou ga, mainichi jogingu shimasu."}],"example":"彼が来ようが来るまいが、パーティーは始まります。","exampleMeaning":"Whether he comes or not, the party will start."},{"pattern":"Verb ようがない (〜you ga nai)","meaning":"Expresses 'no way to do something,' 'impossible to do'.","formation":"Verb (masu stem) + ようがない","examples":[{"jp":"電車が混んでいて、動きようがない。","en":"The train is so crowded that I can't move.","romaji":"Densha ga konde ite, ugoki you ga nai."},{"jp":"彼はとても早く走るので、追いつきようがない。","en":"He runs so fast, there's no way I can catch up.","romaji":"Kare wa totemo hayaku hashiru no de, oitsuki you ga nai."},{"jp":"私には理解しようがない。","en":"There's no way for me to understand it.","romaji":"Watashi ni wa rikai shiyou ga nai."},{"jp":"どうやっても、これを直しようがない。","en":"No matter what I try, there's no way to fix this.","romaji":"Dou yatte mo, kore o naoshi you ga nai."}],"example":"電車が混んでいて、動きようがない。","exampleMeaning":"The train is so crowded that I can't move."},{"pattern":"Verb ようと Verbる まいと","meaning":"This structure indicates that regardless of whether one does (verb) or not, the outcome/attitude remains unchanged.","formation":"Verb-volitional + と + Verb-negative volitional (～まい) + と","examples":[{"jp":"あなたが来ようと来るまいと、パーティーは予定通りに始まります。","en":"Whether you come or not, the party will start as scheduled.","romaji":"Anata ga koyou to kuru mai to, paatii wa yotei doori ni hajimarimasu."},{"jp":"彼があそこに行こうと行くまいと、私たちは止めることができません。","en":"Whether he tries to go there or not, we can't stop him.","romaji":"Kare ga asoko ni ikou to iku mai to, watashitachi wa tomeru koto ga dekimasen."},{"jp":"彼女が謝ろうと謝るまいと、事実は変わらない。","en":"Whether she apologizes or not, the fact won't change.","romaji":"Kanojo ga ayamarou to ayamaru mai to, jijitsu wa kawaranai."},{"jp":"試験を受けようと受けるまいと、親として私はあなたを支えます。","en":"Whether you take the exam or not, I will support you as your parent.","romaji":"Shiken o ukeyou to ukeru mai to, oya to shite watashi wa anata o sasaemasu."}],"example":"あなたが来ようと来るまいと、パーティーは予定通りに始まります。","exampleMeaning":"Whether you come or not, the party will start as scheduled."},{"pattern":"Verb ようにも (〜you ni mo)","meaning":"Used to express 'even though one wants to do something, one can't for some reason'.","formation":"Verb-volitional form + にも + (reason/potential negative, etc.)","examples":[{"jp":"もう少し速く走ろうにも、足が痛くて無理だ。","en":"I'd like to run a bit faster, but I can’t because my leg hurts.","romaji":"Mou sukoshi hayaku hashirou ni mo, ashi ga itakute muri da."},{"jp":"彼に話そうにも、彼は私を無視している。","en":"I want to talk to him, but he's ignoring me.","romaji":"Kare ni hanasou ni mo, kare wa watashi o mushi shite iru."},{"jp":"もっと勉強しようにも、時間がない。","en":"I want to study more, but I have no time.","romaji":"Motto benkyou shiyou ni mo, jikan ga nai."},{"jp":"彼女に謝ろうにも、彼女はもう怒っている。","en":"I would like to apologize to her, but she's already angry.","romaji":"Kanojo ni ayamarou ni mo, kanojo wa mou okotte iru."}],"example":"もう少し速く走ろうにも、足が痛くて無理だ。","exampleMeaning":"I'd like to run a bit faster, but I can’t because my leg hurts."},{"pattern":"Verb ようにも Verb れない (〜you ni mo 〜renai)","meaning":"Expresses the inability to do something even if one wants/tries.","formation":"Verb-volitional form + にも + (potential negative form / reason)","examples":[{"jp":"彼を信じようにも信じられない証拠がある。","en":"Even if I want to believe him, there's evidence that prevents me from doing so.","romaji":"Kare o shinjiyou ni mo shinjirarenai shouko ga aru."},{"jp":"早く出発しようにも車が故障してしまった。","en":"Even if I want to leave early, my car has broken down.","romaji":"Hayaku shuppatsu shiyou ni mo kuruma ga koshou shite shimatta."},{"jp":"彼に電話しようにも電話番号を知らない。","en":"I want to call him, but I don’t know his phone number.","romaji":"Kare ni denwa shiyou ni mo denwa bangou o shiranai."},{"jp":"もっと勉強しようにも時間がない。","en":"I want to study more, but there is no time.","romaji":"Motto benkyou shiyou ni mo jikan ga nai."}],"example":"彼を信じようにも信じられない証拠がある。","exampleMeaning":"Even if I want to believe him, there's evidence that prevents me from doing so."},{"pattern":"Verb ようもない","meaning":"Expresses 'it's impossible to do something'.","formation":"Verb-ます stem + ようもない","examples":[{"jp":"この問題は解きようもない。","en":"It's impossible to solve this problem.","romaji":"Kono mondai wa toki you mo nai."},{"jp":"これ以上我慢しようもない。","en":"It's impossible to endure any further.","romaji":"Kore ijou gaman shiyou mo nai."},{"jp":"彼には通じようもない。","en":"There's no way to get through to him.","romaji":"Kare ni wa tsuujiyou mo nai."},{"jp":"その薬は飲みようもない。","en":"It's impossible to take (swallow) that medicine.","romaji":"Sono kusuri wa nomiyou mo nai."}],"example":"この問題は解きようもない。","exampleMeaning":"It's impossible to solve this problem."},{"pattern":"Verbる がままに (〜ga mama ni)","meaning":"Expresses 'letting something happen as it is'; 'just as something does'.","formation":"Verb-dictionary form + がままに","examples":[{"jp":"窓を開けるがままにしておいたら、風が部屋に入ってきました。","en":"I left the window open as it was, and the wind came into the room.","romaji":"Mado o akeru ga mama ni shite oitara, kaze ga heya ni haitte kimashita."},{"jp":"彼女は涙を流すがままに、ただ黙って座っていた。","en":"She just sat quietly, letting her tears flow.","romaji":"Kanojo wa namida o nagasu ga mama ni, tada damatte suwatte ita."},{"jp":"子供たちは笑うがままに、公園で走り回っていた。","en":"The children ran around the park, laughing freely as they pleased.","romaji":"Kodomo-tachi wa warau ga mama ni, kouen de hashirimawatte ita."},{"jp":"日が沈むがままに、私たちは海辺で話し続けました。","en":"We kept talking by the sea, letting the sun set as it would.","romaji":"Hi ga shizumu ga mama ni, watashitachi wa umibe de hanashi tsudzukemashita."}],"example":"窓を開けるがままにしておいたら、風が部屋に入ってきました。","exampleMeaning":"I left the window open as it was, and the wind came into the room."},{"pattern":"Verbる が早いか (verb-ru ga hayai ka)","meaning":"Expresses 'as soon as...' or 'the moment when...'.","formation":"Verb-dictionary form + が早いか","examples":[{"jp":"部屋に入るが早いか、彼はテレビをつけた。","en":"No sooner had he entered the room than he turned on the TV.","romaji":"Heya ni hairu ga hayai ka, kare wa terebi o tsuketa."},{"jp":"電車に乗るが早いか、私はすぐに眠ってしまった。","en":"As soon as I got on the train, I immediately fell asleep.","romaji":"Densha ni noru ga hayai ka, watashi wa sugu ni nemutte shimatta."},{"jp":"彼女が見るが早いか、すぐに泣き始めた。","en":"The moment she looked, she began to cry.","romaji":"Kanojo ga miru ga hayai ka, sugu ni naki hajimeta."},{"jp":"給料をもらうが早いか、全て使い果たしてしまった。","en":"No sooner had I received my salary than I spent it all.","romaji":"Kyuuryou o morau ga hayai ka, subete tsukaihatashite shimatta."}],"example":"部屋に入るが早いか、彼はテレビをつけた。","exampleMeaning":"No sooner had he entered the room than he turned on the TV."},{"pattern":"Verbる くらいなら (〜ru kurai nara)","meaning":"Expresses preference to avoid something: 'rather than...', 'if it comes to doing X, I'd rather...'.","formation":"Verb-dictionary form + くらいなら","examples":[{"jp":"一人で行くくらいなら、家にいるほうがましです。","en":"I'd rather stay at home than go alone.","romaji":"Hitori de iku kurai nara, ie ni iru hou ga mashi desu."},{"jp":"負けるくらいなら、試合をしないほうがいい。","en":"Rather than lose, it's better not to compete.","romaji":"Makeru kurai nara, shiai o shinai hou ga ii."},{"jp":"遅刻するくらいなら、一日休んだほうがいい。","en":"It's better to take a day off than to be late.","romaji":"Chikoku suru kurai nara, ichinichi yasunda hou ga ii."},{"jp":"痛い目に遭うくらいなら、そのリスクは避けます。","en":"I'd rather avoid that risk than suffer the consequences.","romaji":"Itai me ni au kurai nara, sono risuku wa sakemasu."}],"example":"一人で行くくらいなら、家にいるほうがましです。","exampleMeaning":"I'd rather stay at home than go alone."},{"pattern":"Verbる こと なし に (Verb-ru koto nashi ni)","meaning":"Used to express 'without doing something'.","formation":"Verb-dictionary form + ことなしに","examples":[{"jp":"試験を勉強することなしに、合格しました。","en":"I passed the exam without studying.","romaji":"Shiken o benkyou suru koto nashi ni, goukaku shimashita."},{"jp":"試着することなしに、服を買いました。","en":"I bought the clothes without trying them on.","romaji":"Shichaku suru koto nashi ni, fuku o kaimashita."},{"jp":"彼は働くことなしに生活しています。","en":"He is living without working.","romaji":"Kare wa hataraku koto nashi ni seikatsu shite imasu."},{"jp":"手続きをすることなしに、退職しました。","en":"I retired without going through any procedures.","romaji":"Tetsuzuki o suru koto nashi ni, taishoku shimashita."}],"example":"試験を勉強することなしに、合格しました。","exampleMeaning":"I passed the exam without studying."},{"pattern":"Verbる ことのないように (Verb-ru koto no nai you ni)","meaning":"Expresses the desire or effort to prevent something: 'so as not to...', 'to avoid...'.","formation":"Verb-dictionary form + ことのないように","examples":[{"jp":"車をなくすことのないように、駐車場で必ずロックしましょう。","en":"Lock your car in the parking lot so you don't lose it.","romaji":"Kuruma o nakusu koto no nai you ni, chuushajou de kanarazu rokku shimashou."},{"jp":"風邪を引くことのないように、手をよく洗いましょう。","en":"Wash your hands well so you don't catch a cold.","romaji":"Kaze o hiku koto no nai you ni, te o yoku araimashou."},{"jp":"試験に落ちることのないように、毎日勉強しましょう。","en":"Study every day so you don't fail the exam.","romaji":"Shiken ni ochiru koto no nai you ni, mainichi benkyou shimashou."},{"jp":"間違いをすることのないように、仕事を慎重に行いましょう。","en":"Let's work carefully to avoid making mistakes.","romaji":"Machigai o suru koto no nai you ni, shigoto o shinchou ni okonaimashou."}],"example":"車をなくすことのないように、駐車場で必ずロックしましょう。","exampleMeaning":"Lock your car in the parking lot so you don't lose it."},{"pattern":"Verbる ときりがない (verb-ru to kiri ga nai)","meaning":"Used to indicate that something can go on endlessly or without limits.","formation":"Verb-casual + と + きりがない","examples":[{"jp":"彼の悪口を言うときりがない。","en":"If we start talking about his faults, there's no end.","romaji":"Kare no waruguchi o iu to kiri ga nai."},{"jp":"その問題を考えるときりがない。","en":"If you start thinking about that problem, there's no end.","romaji":"Sono mondai o kangaeru to kiri ga nai."},{"jp":"彼女の美点を挙げるときりがない。","en":"If you start listing her virtues, there would be no end.","romaji":"Kanojo no biten o ageru to kiri ga nai."},{"jp":"この世でおいしいものを食べるときりがない。","en":"If you start eating all the delicious things in this world, there's no end.","romaji":"Kono yo de oishii mono o taberu to kiri ga nai."}],"example":"彼の悪口を言うときりがない。","exampleMeaning":"If we start talking about his faults, there's no end."},{"pattern":"Verbる ともなく Verb (Verb-ru tomonaku Verb)","meaning":"Used to express 'without a particular intention', 'unconsciously', or 'before one knows it'.","formation":"Verb-dictionary form + ともなく + Verb","examples":[{"jp":"遠くを見るともなく窓の外を眺めた。","en":"I found myself gazing out the window, not really looking at anything in particular.","romaji":"Tooku o miru tomonaku mado no soto o nagameta."},{"jp":"知るともなく、彼が去ったことを感じた。","en":"Without really knowing, I felt that he had left.","romaji":"Shiru tomonaku, kare ga satta koto o kanjita."},{"jp":"本を読むともなく、ページをめくっていた。","en":"Without intending to read, I was just flipping through the pages of the book.","romaji":"Hon o yomu tomonaku, peiji o mekutte ita."},{"jp":"寝るともなく、ベッドに横になっていた。","en":"I was lying in bed without really intending to sleep.","romaji":"Neru tomonaku, beddo ni yoko ni natte ita."}],"example":"遠くを見るともなく窓の外を眺めた。","exampleMeaning":"I found myself gazing out the window, not really looking at anything in particular."},{"pattern":"Verbる ともなしに Verb (Verb-ru tomonashi ni Verb)","meaning":"Expresses doing something unintentionally or without conscious thought.","formation":"Verb-dictionary form + ともなしに + Verb","examples":[{"jp":"本を読むともなしに眠ってしまった。","en":"I ended up falling asleep while reading the book without really meaning to.","romaji":"Hon o yomu tomonashi ni nemutte shimatta."},{"jp":"軽い気持ちで手紙を書くともなしに、彼に本心を告白した。","en":"While writing a letter casually, I ended up confessing my true feelings to him.","romaji":"Karui kimochi de tegami o kaku tomonashi ni, kare ni honshin o kokuhaku shita."},{"jp":"散歩をするともなしに、新しいカフェを見つけた。","en":"While I was walking with no particular destination, I found a new cafe.","romaji":"Sanpo o suru tomonashi ni, atarashii kafe o mitsuketa."},{"jp":"洋服を整理するともなしに、昔の写真を見つけた。","en":"As I was absentmindedly organizing clothes, I came across some old photos.","romaji":"Youfuku o seiri suru tomonashi ni, mukashi no shashin o mitsuketa."}],"example":"本を読むともなしに眠ってしまった。","exampleMeaning":"I ended up falling asleep while reading the book without really meaning to."},{"pattern":"Verbる なり (Verb-ru nari)","meaning":"Expresses 'as soon as' or 'the moment'.","formation":"Verb-dictionary form + なり","examples":[{"jp":"家に帰るなり、すぐに寝た。","en":"As soon as I got home, I went to sleep.","romaji":"Ie ni kaeru nari, sugu ni neta."},{"jp":"彼が駅に着くなり、電話をかけてきた。","en":"He called me the moment he arrived at the station.","romaji":"Kare ga eki ni tsuku nari, denwa o kakete kita."},{"jp":"ドアを開けるなり、犬が吠え始めた。","en":"As soon as I opened the door, the dog started barking.","romaji":"Doa o akeru nari, inu ga hoe hajimeta."},{"jp":"テストが終わるなり、彼は教室を出て行った。","en":"He left the classroom the moment the test ended.","romaji":"Tesuto ga owaru nari, kare wa kyoushitsu o dete itta."}],"example":"家に帰るなり、すぐに寝た。","exampleMeaning":"As soon as I got home, I went to sleep."},{"pattern":"Verbる にとどまらず～も (Verb-ru ni todomarazu ~ mo)","meaning":"Expresses 'not only… but also', 'not limited to…'.","formation":"Noun / Verb-dictionary form + にとどまらず + も/ほかのこと","examples":[{"jp":"彼は仕事にとどまらず、ボランティア活動もしている。","en":"He does not just work; he also does volunteer activities.","romaji":"Kare wa shigoto ni todomarazu, borantia katsudou mo shite iru."},{"jp":"この機能は写真撮影にとどまらず、動画撮影も可能です。","en":"This function is not limited to taking photos; it can also record videos.","romaji":"Kono kinou wa shashin satsuei ni todomarazu, douga satsuei mo kanou desu."},{"jp":"このレストランは日本料理にとどまらず、中華料理も提供しています。","en":"This restaurant not only serves Japanese food, but also Chinese cuisine.","romaji":"Kono resutoran wa Nihon ryouri ni todomarazu, Chuuka ryouri mo teikyou shiteimasu."},{"jp":"その企業は製造業にとどまらず、流通業務も手がけている。","en":"That company’s operations go beyond manufacturing; they also handle distribution.","romaji":"Sono kigyou wa seizougyou ni todomarazu, ryuutsuugyou mo tegakete iru."}],"example":"彼は仕事にとどまらず、ボランティア活動もしている。","exampleMeaning":"He does not just work; he also does volunteer activities."},{"pattern":"Verbる にはあたらない (Verb-ru ni wa ataranai)","meaning":"Used to say 'there is no need to...', 'it’s not necessary to...'.","formation":"Verb-dictionary form + にはあたらない","examples":[{"jp":"パニックに陥るにはあたらない。","en":"There’s no need to panic.","romaji":"Panikku ni ochiiru ni wa ataranai."},{"jp":"彼に謝るにはあたらない。","en":"There’s no need to apologize to him.","romaji":"Kare ni ayamaru ni wa ataranai."},{"jp":"そのようなことを心配するにはあたらない。","en":"It’s not worth worrying about such things.","romaji":"Sono you na koto o shinpai suru ni wa ataranai."},{"jp":"それについて深く考えるにはあたらない。","en":"There’s no need to think too deeply about it.","romaji":"Sore ni tsuite fukaku kangaeru ni wa ataranai."}],"example":"パニックに陥るにはあたらない。","exampleMeaning":"There’s no need to panic."},{"pattern":"Verbる にも (Verb-ru ni mo)","meaning":"Indicates that doing the verb is impossible or difficult, even if one wants to.","formation":"Verb-dictionary form + にも + (reason it can't be done)","examples":[{"jp":"明日雨が降ったとしても、傘を持つにも荷物が多すぎる。","en":"Even if it rains tomorrow, I have too much luggage to bring an umbrella.","romaji":"Ashita ame ga futta to shite mo, kasa o motsu ni mo nimotsu ga oosugiru."},{"jp":"試験に落ちたが、もう一度受けるにもお金が足りない。","en":"I failed the exam, but I don’t have the money to take it again even if I wanted to.","romaji":"Shiken ni ochita ga, mou ichido ukeru ni mo okane ga tarinai."},{"jp":"彼に会いたいと思っても、彼に会うにも難しい状況だ。","en":"Even if I want to see him, it's a difficult situation to meet him.","romaji":"Kare ni aitai to omotte mo, kare ni au ni mo muzukashii joukyou da."},{"jp":"この空港から彼女の家に行くにもタクシーが必要だ。","en":"I'd need a taxi to get from this airport to her house, even if I wanted to go.","romaji":"Kono kuukou kara kanojo no ie ni iku ni mo takushii ga hitsuyou da."}],"example":"明日雨が降ったとしても、傘を持つにも荷物が多すぎる。","exampleMeaning":"Even if it rains tomorrow, I have too much luggage to bring an umbrella."},{"pattern":"Verbる にも Verb れない (Verb-ru ni mo Verb-re nai)","meaning":"Expresses: 'Even if I try/want to do something, I cannot.'","formation":"Verb-volitional + にも + Verb-potential negative","examples":[{"jp":"彼を理解しようにも理解できない。","en":"Even if I try to understand him, I can't.","romaji":"Kare o rikai shiyou ni mo rikai dekinai."},{"jp":"走ろうにも走れない。","en":"Even if I want to run, I can't.","romaji":"Hashirou ni mo hashirenai."},{"jp":"泣こうにも泣けない。","en":"Even if I want to cry, I can't.","romaji":"Nakou ni mo nakenai."},{"jp":"忘れようにも忘れられない。","en":"Even if I try to forget, I just can’t.","romaji":"Wasureyou ni mo wasurerarenai."}],"example":"彼を理解しようにも理解できない。","exampleMeaning":"Even if I try to understand him, I can't."},{"pattern":"Verbる べからざる Noun (Verb-ru bekara zaru Noun)","meaning":"Used to express what should not be done; 'must not', 'should not'.","formation":"Verb-dictionary form + べからざる + Noun","examples":[{"jp":"人を裏切るべからざる行為だ。","en":"Betraying others is an act that must not be done.","romaji":"Hito o uragiru bekara zaru koui da."},{"jp":"子供を傷つけるべからざる行動だ。","en":"Hurting a child is a behavior that must not happen.","romaji":"Kodomo o kizutsukeru bekara zaru koudou da."},{"jp":"公に嘘をつくべからざる行動だ。","en":"Lying publicly is an act that should not be done.","romaji":"Ooyake ni uso o tsuku bekara zaru koudou da."},{"jp":"他人の財産を侵すべからざる行為だ。","en":"Infringing on someone else’s property is an act that must not be performed.","romaji":"Tanin no zaisan o okasu bekara zaru koui da."}],"example":"人を裏切るべからざる行為だ。","exampleMeaning":"Betraying others is an act that must not be done."},{"pattern":"Verbる べからず (〜ru bekara zu)","meaning":"Expresses the idea of 'must not do' or 'should not do'.","formation":"Verb-ru + べからず","examples":[{"jp":"嘘をつくべからず。","en":"One must not tell lies.","romaji":"Uso o tsuku bekara zu."},{"jp":"彼らの秘密を漏らすべからず。","en":"You must not leak their secrets.","romaji":"Karera no himitsu o morasu bekara zu."},{"jp":"ルールを破るべからず。","en":"You must not break the rules.","romaji":"Ruuru o yaburu bekara zu."},{"jp":"勉強を怠るべからず。","en":"One must not neglect their studies.","romaji":"Benkyou o okotaru bekara zu."}],"example":"嘘をつくべからず。","exampleMeaning":"One must not tell lies."},{"pattern":"Verbる べく (Verb-ru beku)","meaning":"Expresses the meaning of 'in order to', 'for the purpose of'.","formation":"Verb-dictionary form + べく","examples":[{"jp":"成功するべく、日々努力しています。","en":"In order to succeed, I am working hard every day.","romaji":"Seikou suru beku, hibi doryoku shite imasu."},{"jp":"健康を維持するべく、毎日運動をしています。","en":"In order to maintain my health, I exercise every day.","romaji":"Kenkou o iji suru beku, mainichi undou o shite imasu."},{"jp":"彼は学位を得るべく、毎日勉強しています。","en":"He studies every day in order to get a degree.","romaji":"Kare wa gakui o eru beku, mainichi benkyou shite imasu."},{"jp":"早く目的地に到着するべく、タクシーを呼びました。","en":"I called a taxi in order to arrive at the destination quickly.","romaji":"Hayaku mokutekichi ni touchaku suru beku, takushii o yobimashita."}],"example":"成功するべく、日々努力しています。","exampleMeaning":"In order to succeed, I am working hard every day."},{"pattern":"Verbる べくもない (Verb-ru beku mo nai)","meaning":"Means 'it's impossible to...' or 'there's no way to...'.","formation":"Verb-dictionary form + べくもない","examples":[{"jp":"その問題はとても難しく、解くべくもない。","en":"That problem is so difficult that it's impossible to solve.","romaji":"Sono mondai wa totemo muzukashiku, toku beku mo nai."},{"jp":"彼女はあまりに速く走って、追いつくべくもない。","en":"She runs so fast that there's no way to catch up.","romaji":"Kanojo wa amari ni hayaku hashitte, oitsuku beku mo nai."},{"jp":"試験の筆記用具を忘れた。書くべくもない。","en":"I forgot my writing utensils for the test. It's impossible to write.","romaji":"Shiken no hikki yougu o wasureta. Kaku beku mo nai."},{"jp":"彼はとても高く跳ぶ。追い越すべくもない。","en":"He jumps so high that there's no way to surpass him.","romaji":"Kare wa totemo takaku tobu. Oikosu beku mo nai."}],"example":"その問題はとても難しく、解くべくもない。","exampleMeaning":"That problem is so difficult that it's impossible to solve."},{"pattern":"Verbる までもない (〜ru made mo nai)","meaning":"It's not necessary to the extent of; no need to.","formation":"Verb-る + までもない","examples":[{"jp":"そんなに心配するまでもない。","en":"There's no need to worry that much.","romaji":"Sonna ni shinpai suru made mo nai."},{"jp":"電話するまでもないことだ。","en":"It's not something you need to call about.","romaji":"Denwa suru made mo nai koto da."},{"jp":"小さな失敗であきらめるまでもない。","en":"You don't need to give up over a small mistake.","romaji":"Chiisana shippai de akirameru made mo nai."},{"jp":"この問題は、会議で話し合うまでもない。","en":"This problem doesn't need to be discussed at a meeting.","romaji":"Kono mondai wa, kaigi de hanashiau made mo nai."}],"example":"そんなに心配するまでもない。","exampleMeaning":"There's no need to worry that much."},{"pattern":"Verbる ものとする (〜ru mono to suru)","meaning":"Assuming or deciding something as...","formation":"Verb-dictionary form + ものとする","examples":[{"jp":"ここでの話し合いは秘密とするものとします。","en":"The discussions here are to be kept confidential.","romaji":"Koko de no hanashiai wa himitsu to suru mono to shimasu."},{"jp":"この契約は明日から有効とするものとする。","en":"This contract shall become effective from tomorrow.","romaji":"Kono keiyaku wa ashita kara yuukou to suru mono to suru."},{"jp":"彼をチームのリーダーとするものとします。","en":"We will designate him as the team leader.","romaji":"Kare o chiimu no riidaa to suru mono to shimasu."},{"jp":"この件については終了とするものとする。","en":"We will consider this matter closed.","romaji":"Kono ken ni tsuite wa shuuryou to suru mono to suru."}],"example":"ここでの話し合いは秘密とするものとします。","exampleMeaning":"The discussions here are to be kept confidential."},{"pattern":"Verbる や否や (Verb-ru ya ina ya)","meaning":"Expresses the idea of 'as soon as', 'the moment...'.","formation":"Verb-dictionary form + や否や","examples":[{"jp":"彼女が家に帰るや否や、すぐにテレビをつけました。","en":"As soon as she returned home, she turned on the TV.","romaji":"Kanojo ga ie ni kaeru ya ina ya, sugu ni terebi o tsukemashita."},{"jp":"私が郵便箱を開けるや否や、手紙が落ちました。","en":"The moment I opened the mailbox, the letters fell out.","romaji":"Watashi ga yuubinbako o akeru ya ina ya, tegami ga ochimashita."},{"jp":"子供たちは学校が終わるや否や、公園に走りました。","en":"As soon as school was over, the children ran to the park.","romaji":"Kodomo-tachi wa gakkou ga owaru ya ina ya, kouen ni hashirimashita."},{"jp":"父が新聞を読むや否や、何かに震えていました。","en":"The moment my father read the newspaper, he started trembling about something.","romaji":"Chichi ga shinbun o yomu ya ina ya, nanika ni furuete imashita."}],"example":"彼女が家に帰るや否や、すぐにテレビをつけました。","exampleMeaning":"As soon as she returned home, she turned on the TV."},{"pattern":"Verbる 始末だ (〜ru shimatsu da)","meaning":"Indicates a (often unfortunate) result or conclusion of an action.","formation":"Verb-dictionary form + 始末だ","examples":[{"jp":"忘れてしまって、パスポートを家に置いてくる始末だった。","en":"I ended up leaving my passport at home because I forgot.","romaji":"Wasurete shimatte, pasupooto o ie ni oite-kuru shimatsu datta."},{"jp":"毎晩遅くまで働いて、倒れる始末だ。","en":"I work until late every night and end up collapsing.","romaji":"Maiban osoku made hataraite, taoreru shimatsu da."},{"jp":"勉強しなかったので、試験に落ちる始末だ。","en":"I didn't study, so I ended up failing the exam.","romaji":"Benkyou shinakatta node, shiken ni ochiru shimatsu da."},{"jp":"電車が遅れたため、会議に遅れる始末だ。","en":"Because the train was delayed, I ended up being late for the meeting.","romaji":"Densha ga okureta tame, kaigi ni okureru shimatsu da."}],"example":"忘れてしまって、パスポートを家に置いてくる始末だった。","exampleMeaning":"I ended up leaving my passport at home because I forgot."},{"pattern":"Verbる 嫌いがある","meaning":"Tendency to do a negative action; have a bad habit of ~.","formation":"Verb-dictionary form + 嫌いがある","examples":[{"jp":"彼女は遅刻する嫌いがある。","en":"She has a tendency to be late.","romaji":"Kanojo wa chikoku suru kirai ga aru."},{"jp":"私の父はお酒を飲み過ぎる嫌いがある。","en":"My father has a habit of drinking too much alcohol.","romaji":"Watashi no chichi wa osake o nomisugiru kirai ga aru."},{"jp":"彼は物をすぐ忘れる嫌いがある。","en":"He tends to forget things quickly.","romaji":"Kare wa mono o sugu wasureru kirai ga aru."},{"jp":"彼女は人の話を途中で切る嫌いがある。","en":"She has a habit of interrupting people while they are speaking.","romaji":"Kanojo wa hito no hanashi o tochuu de kiru kirai ga aru."}],"example":"彼女は遅刻する嫌いがある。","exampleMeaning":"She has a tendency to be late."},{"pattern":"いつまで～のやら","meaning":"Expresses uncertainty regarding duration; 'don't know when... will end'.","formation":"いつまで + Verb (dictionary form) + のやら","examples":[{"jp":"この試験勉強はいつまで続くのやら。","en":"I don't know when this exam study will end.","romaji":"Kono shiken benkyou wa itsumade tsuzuku no yara."},{"jp":"彼の話がいつ終わるのやら、わからない。","en":"I don't know when his talk will finish.","romaji":"Kare no hanashi ga itsu owaru no yara, wakaranai."},{"jp":"この雨がいつまで降り続くのやら。","en":"I don't know when this rain will stop.","romaji":"Kono ame ga itsumade furitsuzuku no yara."},{"jp":"コロナのパンデミックがいつまで続くのやら。","en":"I don't know when this coronavirus pandemic will end.","romaji":"Korona no pandemikku ga itsumade tsuzuku no yara."}],"example":"この試験勉強はいつまで続くのやら。","exampleMeaning":"I don't know when this exam study will end."},{"pattern":"～が Verb られる (〜ga Verb rareru)","meaning":"Expresses potential or ability to do something; 'can', 'able to'.","formation":"❶ (Group 1) Verb:  書く → 書ける / 飲む → 飲める, etc.\n❷ (Group 2) Verb-ます stem + られる (食べる→食べられる、見る→見られる)","examples":[{"jp":"彼がこの問題を解けると思いますか？","en":"Do you think he can solve this problem?","romaji":"Kare ga kono mondai o tokeru to omoimasu ka?"},{"jp":"私がその大きな箱を運べるか？","en":"Can I carry that big box?","romaji":"Watashi ga sono ookina hako o hakoberu ka?"},{"jp":"彼が早く走れると思います。","en":"I think he can run fast.","romaji":"Kare ga hayaku hashireru to omoimasu."},{"jp":"彼女は日本語が話せる。","en":"She can speak Japanese.","romaji":"Kanojo wa nihongo ga hanaseru."}],"example":"彼がこの問題を解けると思いますか？","exampleMeaning":"Do you think he can solve this problem?"},{"pattern":"～かと思いきや (〜ka to omoikiya)","meaning":"Expressing unexpected outcomes; 'just when I thought...', 'but...'.","formation":"Sentence + かと思いきや (Verb plain form, i-/na-Adjective, or Noun + だ + かと思いきや)","examples":[{"jp":"明日は晴れるかと思いきや、まさかの雨が降った。","en":"I thought it would be sunny tomorrow, but unexpectedly it rained.","romaji":"Ashita wa hareru ka to omoikiya, masaka no ame ga futta."},{"jp":"彼が試験に落ちたかと思いきや、合格していた。","en":"I thought he had failed the test, but he actually passed.","romaji":"Kare ga shiken ni ochita ka to omoikiya, goukaku shite ita."},{"jp":"このケーキは美味しそうだったかと思いきや、全然甘くなかった。","en":"I thought this cake would be delicious, but it wasn’t sweet at all.","romaji":"Kono keeki wa oishisou datta ka to omoikiya, zenzen amakunakatta."},{"jp":"列車が遅れるかと思いきや、時間通りに到着した。","en":"I thought the train would be late, but it arrived on time.","romaji":"Ressha ga okureru ka to omoikiya, jikan doori ni touchaku shita."}],"example":"明日は晴れるかと思いきや、まさかの雨が降った。","exampleMeaning":"I thought it would be sunny tomorrow, but unexpectedly it rained."},{"pattern":"～がゆえに","meaning":"Expresses the reason or cause; 'because', 'due to', 'as a result of'.","formation":"Noun / Verb / Adjective + がゆえに","examples":[{"jp":"愛情がゆえに、彼は彼女を許した。","en":"Because of love, he forgave her.","romaji":"Aijou ga yue ni, kare wa kanojo o yurushita."},{"jp":"突然の雨がゆえに、試合は延期された。","en":"Due to the sudden rain, the match was postponed.","romaji":"Totsuzen no ame ga yue ni, shiai wa enki sareta."},{"jp":"彼の努力がゆえに、彼は成功を収めた。","en":"Because of his efforts, he achieved success.","romaji":"Kare no doryoku ga yue ni, kare wa seikou o osameta."},{"jp":"彼の死がゆえに、彼の家族は深い悲しみに包まれた。","en":"Due to his death, his family was enveloped in deep sorrow.","romaji":"Kare no shi ga yue ni, kare no kazoku wa fukai kanashimi ni tsutsumareta."}],"example":"愛情がゆえに、彼は彼女を許した。","exampleMeaning":"Because of love, he forgave her."},{"pattern":"～がゆえの Noun (〜ga yue no Noun)","meaning":"Expresses the reason or cause for something; 'because of', 'due to'.","formation":"Noun / Verb-dictionary form + がゆえの + Noun","examples":[{"jp":"愛がゆえの悲しみ。","en":"Sadness due to love.","romaji":"Ai ga yue no kanashimi."},{"jp":"健康がゆえの幸せ。","en":"Happiness due to good health.","romaji":"Kenkou ga yue no shiawase."},{"jp":"悪行がゆえの罰。","en":"Punishment due to wrongdoing.","romaji":"Akugyou ga yue no batsu."},{"jp":"努力がゆえの成功。","en":"Success due to effort.","romaji":"Doryoku ga yue no seikou."}],"example":"愛がゆえの悲しみ。","exampleMeaning":"Sadness due to love."},{"pattern":"～から Noun に 至る まで (〜kara 〜ni itaru made)","meaning":"Expressing range from one thing to another; 'from...to', 'ranging from...to'.","formation":"Noun (start) + から + Noun (end) + に至るまで","examples":[{"jp":"このバンドの曲は、青年から老人に至るまで、人々に愛されています。","en":"The songs of this band are loved by people ranging from the young to the elderly.","romaji":"Kono bando no kyoku wa, seinen kara roujin ni itaru made, hitobito ni aisarete imasu."},{"jp":"小さい物件から大きな建物に至るまで、全てのプロパティの管理を我々が行います。","en":"We handle all property management, ranging from small units to large buildings.","romaji":"Chiisai bukken kara ooki na tatemono ni itaru made, subete no property no kanri o wareware ga okonaimasu."},{"jp":"朝のニュース放送から夜のドラマに至るまで、テレビは毎日見ています。","en":"I watch TV every day, from the morning news broadcasts to the night dramas.","romaji":"Asa no nyuusu housou kara yoru no dorama ni itaru made, terebi wa mainichi mite imasu."},{"jp":"この地域は、春から冬に至るまで旅行者で賑わいます。","en":"This area is bustling with tourists from spring to winter.","romaji":"Kono chiiki wa, haru kara fuyu ni itaru made ryokousha de nigiwaimasu."}],"example":"このバンドの曲は、青年から老人に至るまで、人々に愛されています。","exampleMeaning":"The songs of this band are loved by people ranging from the young to the elderly."},{"pattern":"～ごとく (〜gotoku)","meaning":"To seem like; as if; as though.","formation":"Verb-て + ごとく / Noun + の + ごとく","examples":[{"jp":"彼は鳥のごとく飛んでいるように見えた。","en":"He looked as though he was flying like a bird.","romaji":"Kare wa tori no gotoku tonde iru you ni mieta."},{"jp":"彼は死んだごとく眠っていた。","en":"He was sleeping as though he were dead.","romaji":"Kare wa shinda gotoku nemutte ita."},{"jp":"彼女はアイドルのごとく崇められている。","en":"She is revered as if she were an idol.","romaji":"Kanojo wa aidoru no gotoku agamerarete iru."},{"jp":"彼は風のごとく走った。","en":"He ran like the wind.","romaji":"Kare wa kaze no gotoku hashitta."}],"example":"彼は鳥のごとく飛んでいるように見えた。","exampleMeaning":"He looked as though he was flying like a bird."},{"pattern":"～こととて (〜koto tote)","meaning":"Used to express the reason or premise for a decision or judgment; 'since', 'because'.","formation":"Verb (plain form) + こととて / Noun + の + こととて / (な-Adjective + な) + こととて","examples":[{"jp":"彼は裁判に勝つために全資産を使うこととて、弁護士に頼んだ。","en":"Since he's using all his assets to win the trial, he hired a lawyer.","romaji":"Kare wa saiban ni katsu tame ni zenshisan o tsukau koto tote, bengoshi ni tanonda."},{"jp":"明日は大切な試験があることとて、今夜は早く寝ます。","en":"Since I have an important exam tomorrow, I’m going to bed early tonight.","romaji":"Ashita wa taisetsu na shiken ga aru koto tote, konya wa hayaku nemasu."},{"jp":"このプロジェクトの成功は会社の未来に影響することとて、全力を尽くします。","en":"Because the success of this project will affect the company's future, I will do my best.","romaji":"Kono purojekuto no seikou wa kaisha no mirai ni eikyou suru koto tote, zenryoku o tsukushimasu."},{"jp":"彼が有名人であることとて、プライバシーが保護されるべきだ。","en":"Since he is a celebrity, his privacy should be protected.","romaji":"Kare ga yuumeijin de aru koto tote, puraibashii ga hogo sareru beki da."}],"example":"彼は裁判に勝つために全資産を使うこととて、弁護士に頼んだ。","exampleMeaning":"Since he's using all his assets to win the trial, he hired a lawyer."},{"pattern":"～ずにすんだ (〜zuni sunda)","meaning":"Expresses the idea of 'was able to do without'; 'managed to avoid'.","formation":"Verb-ず form + に + すんだ","examples":[{"jp":"彼は事故を起こさずにすんだ。","en":"He managed to avoid having an accident.","romaji":"Kare wa jiko o okosazu ni sunda."},{"jp":"私は手術せずにすんだ。","en":"I was able to do without surgery.","romaji":"Watashi wa shujutsu sezu ni sunda."},{"jp":"雨が降らずにすんだ。","en":"We managed to avoid the rain.","romaji":"Ame ga furazu ni sunda."},{"jp":"罰金を払わずにすんだ。","en":"I managed to avoid paying a fine.","romaji":"Bakkin o harawazu ni sunda."}],"example":"彼は事故を起こさずにすんだ。","exampleMeaning":"He managed to avoid having an accident."},{"pattern":"～だろうとなかろうと (〜darou to nakarou to)","meaning":"Expresses 'regardless of whether it is or isn't'.","formation":"Noun / i-Adjective / na-Adjective / Verb + だろうとなかろうと","examples":[{"jp":"試験が難しいだろうとなかろうと、全力で頑張ります。","en":"Regardless of whether the exam is difficult or not, I will do my best.","romaji":"Shiken ga muzukashii darou to nakarou to, zenryoku de ganbarimasu."},{"jp":"彼が来るだろうとなかろうと、私たちは始めます。","en":"Whether he comes or not, we will start.","romaji":"Kare ga kuru darou to nakarou to, watashitachi wa hajimemasu."},{"jp":"この仕事が面白いだろうとなかろうと、私は続けます。","en":"Whether this job is interesting or not, I will continue.","romaji":"Kono shigoto ga omoshiroi darou to nakarou to, watashi wa tsuzukemasu."},{"jp":"彼が賛成するだろうとなかろうと、私たちは進行します。","en":"Whether he agrees or not, we will proceed.","romaji":"Kare ga sansei suru darou to nakarou to, watashitachi wa shinkou shimasu."}],"example":"試験が難しいだろうとなかろうと、全力で頑張ります。","exampleMeaning":"Regardless of whether the exam is difficult or not, I will do my best."},{"pattern":"～つもりだ (〜tsumori da)","meaning":"Expresses the speaker's intention or plan.","formation":"Verb-dictionary form + つもりだ","examples":[{"jp":"明日は早く起きるつもりです。","en":"I plan to wake up early tomorrow.","romaji":"Ashita wa hayaku okiru tsumori desu."},{"jp":"私は日本語を勉強するつもりです。","en":"I intend to study Japanese.","romaji":"Watashi wa nihongo o benkyou suru tsumori desu."},{"jp":"彼は留学するつもりだと言った。","en":"He said he plans to study abroad.","romaji":"Kare wa ryuugaku suru tsumori da to itta."},{"jp":"私は来週末に家族と旅行するつもりだ。","en":"I plan to travel with my family next weekend.","romaji":"Watashi wa raishuumatsu ni kazoku to ryokou suru tsumori da."}],"example":"明日は早く起きるつもりです。","exampleMeaning":"I plan to wake up early tomorrow."},{"pattern":"～つもりで (〜tsumori de)","meaning":"Expresses the speaker's intention or plan; 'with the intention of', 'planning to'.","formation":"Verb-dictionary form + つもりで","examples":[{"jp":"私は日本に住むつもりで日本語を勉強しています。","en":"I am studying Japanese with the intention of living in Japan.","romaji":"Watashi wa Nihon ni sumu tsumori de Nihongo o benkyou shiteimasu."},{"jp":"彼は全てを失うつもりでギャンブルをしました。","en":"He gambled with the intention of risking everything.","romaji":"Kare wa subete o ushinau tsumori de gyanburu o shimashita."},{"jp":"明日のテストに合格するつもりで一生懸命勉強します。","en":"I will study hard with the intention of passing tomorrow’s test.","romaji":"Ashita no tesuto ni goukaku suru tsumori de isshoukenmei benkyou shimasu."},{"jp":"彼は早く起きるつもりで早く寝ました。","en":"He went to bed early with the intention of waking up early.","romaji":"Kare wa hayaku okiru tsumori de hayaku nemashita."}],"example":"私は日本に住むつもりで日本語を勉強しています。","exampleMeaning":"I am studying Japanese with the intention of living in Japan."},{"pattern":"～ではすまない (〜dewa sumanai)","meaning":"Expresses that just doing something is not enough or will not suffice.","formation":"Verb-dictionary form + ではすまない / い-Adjective + ではすまない / な-Adjective + ではすまない / Noun + ではすまない","examples":[{"jp":"ただ謝るではすまない。何か行動を取らなければならない。","en":"Just apologizing will not suffice. Some action needs to be taken.","romaji":"Tada ayamaru dewa sumanai. Nanika koudou o toranakereba naranai."},{"jp":"この問題は議論だけではすまない。具体的な計画が必要だ。","en":"This problem won't be solved with just discussions. A concrete plan is needed.","romaji":"Kono mondai wa giron dake dewa sumanai. Gutaiteki na keikaku ga hitsuyou da."},{"jp":"彼の失敗は注意だけではすまない。彼はその責任を取るべきだ。","en":"His failure won't be resolved with just a warning. He should take responsibility.","romaji":"Kare no shippai wa chuui dake dewa sumanai. Kare wa sono sekinin o toru beki da."},{"jp":"この失敗は金だけではすまない。信頼を取り戻すため、真心で謝罪するべきだ。","en":"This mistake cannot be settled with money alone. To regain trust, an earnest apology is needed.","romaji":"Kono shippai wa kane dake dewa sumanai. Shinrai o torimodosu tame, magokoro de shazai suru beki da."}],"example":"ただ謝るではすまない。何か行動を取らなければならない。","exampleMeaning":"Just apologizing will not suffice. Some action needs to be taken."},{"pattern":"～とあって (〜to atte)","meaning":"Expresses a special situation or event due to certain circumstances.","formation":"Noun + とあって / (Sometimes Verb + とあって, depending on context)","examples":[{"jp":"春休みとあって、公園は子供たちでいっぱいだ。","en":"Because it's spring break, the park is full of children.","romaji":"Haruyasumi to atte, kouen wa kodomo-tachi de ippai da."},{"jp":"試験前とあって、図書館は学生で混んでいる。","en":"With exams coming up, the library is crowded with students.","romaji":"Shiken mae to atte, toshokan wa gakusei de konde iru."},{"jp":"開店日とあって、その店にはたくさんの人が並んでいた。","en":"Because it was the store's opening day, a lot of people lined up.","romaji":"Kaitenbi to atte, sono mise ni wa takusan no hito ga narande ita."},{"jp":"彼の誕生日とあって、友人たちはサプライズパーティーを計画した。","en":"Because it was his birthday, his friends planned a surprise party.","romaji":"Kare no tanjoubi to atte, yuujin-tachi wa sapuraizu paatii o keikaku shita."}],"example":"春休みとあって、公園は子供たちでいっぱいだ。","exampleMeaning":"Because it's spring break, the park is full of children."},{"pattern":"～とあれば (〜to areba)","meaning":"Expresses a condition; 'if', 'when', 'since'.","formation":"Verb-casual + とあれば / い-Adjective + とあれば / な-Adjective + だとあれば / Noun + だとあれば","examples":[{"jp":"無料とあれば、誰でも利用したいと思います。","en":"If it's free, anyone would want to use it.","romaji":"Muryou to areba, dare demo riyou shitai to omoimasu."},{"jp":"この曲が流れるとあれば、彼は必ず踊り始めます。","en":"If this song starts playing, he will definitely begin to dance.","romaji":"Kono kyoku ga nagareru to areba, kare wa kanarazu odorihajimemasu."},{"jp":"明日が休日だとあれば、今夜は遅くまで起きていられます。","en":"If tomorrow is a holiday, I can stay up late tonight.","romaji":"Ashita ga kyuujitsu da to areba, konya wa osoku made okite iraremasu."},{"jp":"彼が参加するとあれば、このイベントは成功でしょう。","en":"If he participates, this event will surely be successful.","romaji":"Kare ga sanka suru to areba, kono ibento wa seikou deshou."}],"example":"無料とあれば、誰でも利用したいと思います。","exampleMeaning":"If it's free, anyone would want to use it."},{"pattern":"～といえども (〜to iedomo)","meaning":"Even if it is said that; Even though; Although.","formation":"Noun + といえども / Verb-plain form + といえども / Adjective + といえども","examples":[{"jp":"彼が天才といえども、ミスをすることはあります。","en":"Even though he’s a genius, he still makes mistakes.","romaji":"Kare ga tensai to iedomo, misu o suru koto wa arimasu."},{"jp":"このパソコンが新しいといえども、問題があります。","en":"Even though this computer is new, it has problems.","romaji":"Kono pasokon ga atarashii to iedomo, mondai ga arimasu."},{"jp":"春といえども、まだ寒い日があります。","en":"Even though it's spring, there are still cold days.","romaji":"Haru to iedomo, mada samui hi ga arimasu."},{"jp":"彼女が一番好きな人といえども、嫌なことは嫌です。","en":"Even though she’s my favorite person, unpleasant things are still unpleasant.","romaji":"Kanojo ga ichiban suki na hito to iedomo, iya na koto wa iya desu."}],"example":"彼が天才といえども、ミスをすることはあります。","exampleMeaning":"Even though he’s a genius, he still makes mistakes."},{"pattern":"～といったらありはしない (〜to ittara ari wa shinai)","meaning":"Express extreme exclamation; 'extremely', 'unbelievable', 'unsurpassed'.","formation":"Noun + といったらありはしない / な-Adjective + といったらありはしない","examples":[{"jp":"彼の英語の上手さといったらありはしない。","en":"His English is unbelievably good.","romaji":"Kare no eigo no jouzusa to ittara ari wa shinai."},{"jp":"このスイーツの美味しさといったらありはしない。","en":"These sweets are unbelievably delicious.","romaji":"Kono suiitsu no oishisa to ittara ari wa shinai."},{"jp":"その子の頭の良さといったらありはしない。","en":"That kid's intelligence is unsurpassed.","romaji":"Sono ko no atama no yosa to ittara ari wa shinai."},{"jp":"彼女の美しさといったらありはしない。","en":"Her beauty is beyond belief.","romaji":"Kanojo no utsukushisa to ittara ari wa shinai."}],"example":"彼の英語の上手さといったらありはしない。","exampleMeaning":"His English is unbelievably good."},{"pattern":"～といったらありゃしない (〜to ittara arya shinai)","meaning":"Emphasizes that something is to the extreme; 'you have no idea how...', 'it's incredibly...'.","formation":"Verb-casual + といったらありゃしない / い-Adjective + といったらありゃしない / な-Adjective + だ + といったらありゃしない / Noun + だ + といったらありゃしない","examples":[{"jp":"その店のラーメンは美味しいといったらありゃしない。","en":"You have no idea how delicious the ramen at that shop is.","romaji":"Sono mise no ramen wa oishii to ittara arya shinai."},{"jp":"彼女の料理の腕前は上手だといったらありゃしない。","en":"You have no idea how skilled she is at cooking.","romaji":"Kanojo no ryouri no udemae wa jouzu da to ittara arya shinai."},{"jp":"この冬の寒さは厳しいといったらありゃしない。","en":"You have no idea how harsh this winter's cold is.","romaji":"Kono fuyu no samusa wa kibishii to ittara arya shinai."},{"jp":"その小説は面白いといったらありゃしない。","en":"You have no idea how interesting that novel is.","romaji":"Sono shousetsu wa omoshiroi to ittara arya shinai."}],"example":"その店のラーメンは美味しいといったらありゃしない。","exampleMeaning":"You have no idea how delicious the ramen at that shop is."},{"pattern":"～といったらない (〜to ittara nai)","meaning":"Expresses the extreme of something; 'nothing can be more ... than this'.","formation":"い-Adjective + といったらない / な-Adjective + だといったらない / Noun + だといったらない","examples":[{"jp":"今日は寒いといったらない。","en":"It’s extremely cold today.","romaji":"Kyou wa samui to ittara nai."},{"jp":"彼女の料理の美味しさといったらない。","en":"Nothing can be more delicious than her cooking.","romaji":"Kanojo no ryouri no oishisa to ittara nai."},{"jp":"この子の頭の良さだといったらない。","en":"This child is unbelievably smart.","romaji":"Kono ko no atama no yosa da to ittara nai."},{"jp":"彼の怠けっぷりだといったらない。","en":"Nobody could be lazier than him.","romaji":"Kare no namakeppuri da to ittara nai."}],"example":"今日は寒いといったらない。","exampleMeaning":"It’s extremely cold today."},{"pattern":"～ときている (〜to kite iru)","meaning":"Highlights a situation or condition that is serious/extreme, often with a negative nuance.","formation":"Verb-casual / い-Adjective / な-Adjective（＋だ） / Noun（＋だ） + ときている","examples":[{"jp":"仕事が忙しいときているので、なかなか休みが取れません。","en":"Because work is so busy, I just can’t take any time off.","romaji":"Shigoto ga isogashii to kite iru no de, nakanaka yasumi ga toremasen."},{"jp":"経済が悪いときているだけに、会社が大量解雇を発表した。","en":"Since the economy is in such bad shape, the company announced mass layoffs.","romaji":"Keizai ga warui to kite iru dake ni, kaisha ga tairyou kaiko o happyou shita."},{"jp":"旅行先で荷物を盗まれたときているから、旅行を楽しむどころではない。","en":"Given that my luggage was stolen while traveling, there’s no way I can enjoy the trip.","romaji":"Ryokousaki de nimotsu o nusumareta to kite iru kara, ryokou o tanoshimu dokoro de wa nai."},{"jp":"試験が近いときているうえに、課題も山ほどあって大変だ。","en":"Not only are exams coming up, but I also have a mountain of assignments, so it’s really tough.","romaji":"Shiken ga chikai to kite iru ue ni, kadai mo yamahodo atte taihen da."}],"example":"仕事が忙しいときているので、なかなか休みが取れません。","exampleMeaning":"Because work is so busy, I just can’t take any time off."},{"pattern":"～ところを (〜tokoro wo)","meaning":"Indicates a contrasting or inconvenient timing; 'just when...', 'even though...'.","formation":"Verb-ている + ところを / Noun + の + ところを / い-Adjective + ところを / な-Adjective + な + ところを","examples":[{"jp":"ちょうど映画を見ているところを、停電で真っ暗になった。","en":"Just when I was in the middle of watching a movie, the power went out and everything went dark.","romaji":"Choudo eiga o mite iru tokoro o, teiden de makkura ni natta."},{"jp":"美味しく食べているところを、彼が全部横取りしてしまった。","en":"Right when I was enjoying my meal, he took it all away.","romaji":"Oishiku tabete iru tokoro o, kare ga zenbu yokodori shite shimatta."},{"jp":"飛行機が離陸しようとしているところを、急にエンジンが止まった。","en":"Just as the plane was about to take off, the engine suddenly stopped.","romaji":"Hikouki ga ririku shiyou to shite iru tokoro o, kyuu ni enjin ga tomatta."},{"jp":"彼女が怒っているところを、私は冗談を言ってしまった。","en":"Even though she was angry, I went ahead and made a joke.","romaji":"Kanojo ga okotte iru tokoro o, watashi wa joudan o itte shimatta."}],"example":"ちょうど映画を見ているところを、停電で真っ暗になった。","exampleMeaning":"Just when I was in the middle of watching a movie, the power went out and everything went dark."},{"pattern":"～とされる (〜to sareru)","meaning":"Indicates a general belief or widely accepted view; 'is considered', 'is seen as', 'is said to be'.","formation":"Verb-casual + とされる / い-Adjective + とされる / な-Adjective + だとされる / Noun + だとされる","examples":[{"jp":"サッカーは世界で最も人気のあるスポーツとされています。","en":"Soccer is considered the most popular sport in the world.","romaji":"Sakkaa wa sekai de mottomo ninki no aru supootsu to sarete imasu."},{"jp":"彼は最も有能な科学者とされる。","en":"He is considered the most talented scientist.","romaji":"Kare wa mottomo yuunou na kagakusha to sareru."},{"jp":"この建物は地元のランドマークだとされています。","en":"This building is said to be a local landmark.","romaji":"Kono tatemono wa jimoto no randomaaku da to sarete imasu."},{"jp":"そのお寺は古代の美術品とされている。","en":"That temple is considered an ancient work of art.","romaji":"Sono otera wa kodai no bijutsuhin to sarete iru."}],"example":"サッカーは世界で最も人気のあるスポーツとされています。","exampleMeaning":"Soccer is considered the most popular sport in the world."},{"pattern":"～としたところで (〜to shita tokoro de)","meaning":"Means 'even if' or 'even assuming'; emphasizes that the outcome won’t change.","formation":"Verb-casual + としたところで / い-Adjective + としたところで / な-Adjective + だとしたところで / Noun + だとしたところで","examples":[{"jp":"彼が来るとしたところで、何も変わらないだろう。","en":"Even if he comes, nothing will probably change.","romaji":"Kare ga kuru to shita tokoro de, nani mo kawaranai darou."},{"jp":"美味しいお菓子を作るとしたところで、それが売れる保証はない。","en":"Even if we make delicious sweets, there's no guarantee they’ll sell.","romaji":"Oishii okashi o tsukuru to shita tokoro de, sore ga ureru hoshou wa nai."},{"jp":"電話をかけるとしたところで、彼女が出るとは限らない。","en":"Even if I call her, she might not pick up.","romaji":"Denwa o kakeru to shita tokoro de, kanojo ga deru to wa kagiranai."},{"jp":"最高の材料を使うとしたところで、美味しくなるとは限らない。","en":"Even if you use the best ingredients, it might not turn out delicious.","romaji":"Saikou no zairyou o tsukau to shita tokoro de, oishiku naru to wa kagiranai."}],"example":"彼が来るとしたところで、何も変わらないだろう。","exampleMeaning":"Even if he comes, nothing will probably change."},{"pattern":"～とすると (〜to suru to)","meaning":"Expresses 'if', 'when', or 'assuming that' in a speculative sense.","formation":"Verb-casual + とすると / い-Adjective + とすると / な-Adjective + だとすると / Noun + だとすると","examples":[{"jp":"彼が来るとすると、もうすぐ到着するはずです。","en":"If he’s coming, he should arrive soon.","romaji":"Kare ga kuru to suru to, mou sugu touchaku suru hazu desu."},{"jp":"この仕事を終えるとすると、最低でも3日はかかるでしょう。","en":"Assuming we finish this work, it will take at least three days.","romaji":"Kono shigoto o oeru to suru to, saitei demo mikka wa kakaru deshou."},{"jp":"戦争が起きるとすると、多くの人々が犠牲になるでしょう。","en":"If a war were to break out, many people would become victims.","romaji":"Sensou ga okiru to suru to, ooku no hitobito ga gisei ni naru deshou."},{"jp":"彼が経営者だとすると、多くの責任を負うことになるでしょう。","en":"If he’s the manager, he will bear a lot of responsibility.","romaji":"Kare ga keieisha da to suru to, ooku no sekinin o ou koto ni naru deshou."}],"example":"彼が来るとすると、もうすぐ到着するはずです。","exampleMeaning":"If he’s coming, he should arrive soon."},{"pattern":"～とすれば","meaning":"Used to express 'if it were the case that...', 'if we assume that...'.","formation":"Verb-casual + とすれば / い-Adjective + とすれば / な-Adjective + だとすれば / Noun + だとすれば","examples":[{"jp":"彼が嘘つきだとすれば、その話は信じられない。","en":"If he’s a liar, then his story can’t be believed.","romaji":"Kare ga usotsuki da to sureba, sono hanashi wa shinjirarenai."},{"jp":"あなたが一緒に行くとすれば、私も行きます。","en":"If you are going, I'll go too.","romaji":"Anata ga issho ni iku to sureba, watashi mo ikimasu."},{"jp":"彼が浮気しているとすれば、どうすればいい？","en":"If he’s cheating, what should I do?","romaji":"Kare ga uwaki shite iru to sureba, dou sureba ii?"},{"jp":"その薬が効かないとすれば、他の方法を試すべきだ。","en":"If that medicine doesn’t work, we should try something else.","romaji":"Sono kusuri ga kikanai to sureba, hoka no houhou o tamesu beki da."}],"example":"彼が嘘つきだとすれば、その話は信じられない。","exampleMeaning":"If he’s a liar, then his story can’t be believed."},{"pattern":"～となったら (〜to nattara)","meaning":"Used to express 'if it comes to...', 'when it becomes the case that...'.","formation":"Verb-casual + となったら / Noun + となったら","examples":[{"jp":"旅行に行くとなったら、荷造りをしなければいけません。","en":"If it comes to going on a trip, we have to pack.","romaji":"Ryokou ni iku to nattara, nizukuri o shinakereba ikemasen."},{"jp":"試験に落ちるとなったら、どうしよう。","en":"What should I do if I fail the exam?","romaji":"Shiken ni ochiru to nattara, dou shiyou."},{"jp":"彼女と別れるとなったら、とても悲しいです。","en":"If it comes to breaking up with her, I’ll be very sad.","romaji":"Kanojo to wakareru to nattara, totemo kanashii desu."},{"jp":"結婚するとなったら、人生が大きく変わるでしょう。","en":"When it comes to getting married, life will probably change drastically.","romaji":"Kekkon suru to nattara, jinsei ga ookiku kawaru deshou."}],"example":"旅行に行くとなったら、荷造りをしなければいけません。","exampleMeaning":"If it comes to going on a trip, we have to pack."},{"pattern":"～となると (〜to naru to)","meaning":"Used to highlight a certain circumstance; 'when it comes to...', 'if it becomes...', 'in the event that...'.","formation":"Verb-casual + となると / い-Adjective + となると / な-Adjective + だとなると / Noun + だとなると","examples":[{"jp":"試験となると、多くの学生が緊張する。","en":"When it comes to exams, many students get nervous.","romaji":"Shiken to naru to, ooku no gakusei ga kinchou suru."},{"jp":"東京へ引っ越すとなると、生活費が一気に上がる。","en":"If you move to Tokyo, the cost of living goes up drastically.","romaji":"Toukyou e hikkosu to naru to, seikatsuhi ga ikki ni agaru."},{"jp":"締め切りが明日となると、今夜は徹夜になりそうだ。","en":"If the deadline is tomorrow, I’ll probably be up all night.","romaji":"Shimekiri ga ashita to naru to, konya wa tetsuya ni narisou da."},{"jp":"彼がリーダーとなると、チームの活動は大きく改善されるかもしれない。","en":"If he becomes the leader, the team’s activities might improve significantly.","romaji":"Kare ga riidaa to naru to, chiimu no katsudou wa ookiku kaizen sareru kamoshirenai."}],"example":"試験となると、多くの学生が緊張する。","exampleMeaning":"When it comes to exams, many students get nervous."},{"pattern":"～となれば (〜to nareba)","meaning":"Expresses the idea of 'if it comes to...; when we talk about...; in the case of...'.","formation":"Verb-casual + となれば, い-Adjective + となれば, な-Adjective + だとなれば, Noun + だとなれば","examples":[{"jp":"彼がリーダーとなれば、プロジェクトは成功するでしょう。","en":"If he becomes the leader, the project will probably succeed.","romaji":"Kare ga riidaa to nareba, purojekuto wa seikou suru deshou."},{"jp":"明日が雨だとなれば、ピクニックをキャンセルしましょう。","en":"If it turns out to be raining tomorrow, let's cancel the picnic.","romaji":"Ashita ga ame da to nareba, pikunikku wo kyanseru shimashou."},{"jp":"この仕事が終わったとなれば、休暇を取ることができます。","en":"If this job is over, you can take a vacation.","romaji":"Kono shigoto ga owatta to nareba, kyuuka wo toru koto ga dekimasu."},{"jp":"そのテストが難しいとなれば、より一層勉強しなければならない。","en":"If that test is difficult, we must study all the more.","romaji":"Sono tesuto ga muzukashii to nareba, yori issou benkyou shinakereba naranai."}],"example":"彼がリーダーとなれば、プロジェクトは成功するでしょう。","exampleMeaning":"If he becomes the leader, the project will probably succeed."},{"pattern":"～とのことだ (〜to no koto da)","meaning":"Expresses something that the speaker heard; 'I've heard that', 'I was told that'.","formation":"Simplified phrase + とのことだ","examples":[{"jp":"週末にパーティーがあるとのことだ。","en":"I've heard that there is a party this weekend.","romaji":"Shuumatsu ni paatii ga aru to no koto da."},{"jp":"彼は来年ロンドンに引っ越すとのことだ。","en":"I was told that he is moving to London next year.","romaji":"Kare wa rainen Rondon ni hikkosu to no koto da."},{"jp":"彼女は新しい仕事についたとのことだ。","en":"I've heard that she has gotten a new job.","romaji":"Kanojo wa atarashii shigoto ni tsuita to no koto da."},{"jp":"明日は試験がないとのことだ。","en":"I was told that there is no exam tomorrow.","romaji":"Ashita wa shiken ga nai to no koto da."}],"example":"週末にパーティーがあるとのことだ。","exampleMeaning":"I've heard that there is a party this weekend."},{"pattern":"～とはいえ","meaning":"Even though; although; but","formation":"Noun + とはいえ, な-Adjective + だとはいえ, い-Adjective + とはいえ, Verb-casual + とはいえ","examples":[{"jp":"彼は頭が良いとはいえ、少し怠け者だ。","en":"Although he is smart, he is a bit lazy.","romaji":"Kare wa atama ga yoi to wa ie, sukoshi namakemono da."},{"jp":"このレストランは美味しいとはいえ、ちょっと高い。","en":"While this restaurant is delicious, it's a bit expensive.","romaji":"Kono resutoran wa oishii to wa ie, chotto takai."},{"jp":"日本は小さい国だとはいえ、技術は世界一だ。","en":"Even though Japan is a small country, its technology is among the best in the world.","romaji":"Nihon wa chiisai kuni da to wa ie, gijutsu wa sekaiichi da."},{"jp":"彼女は若いとはいえ、経験豊富だ。","en":"Even though she is young, she is very experienced.","romaji":"Kanojo wa wakai to wa ie, keiken houfu da."}],"example":"彼は頭が良いとはいえ、少し怠け者だ。","exampleMeaning":"Although he is smart, he is a bit lazy."},{"pattern":"～とみえて (〜to miete)","meaning":"It seems that; apparently","formation":"Verb-casual + とみえて, い-Adjective + とみえて, な-Adjective + だとみえて, Noun + だとみえて","examples":[{"jp":"彼は運動が得意とみえて、毎日ジムに行っています。","en":"He seems to be good at exercise, as he goes to the gym every day.","romaji":"Kare wa undou ga tokui to miete, mainichi jimu ni itteimasu."},{"jp":"彼女は忙しいとみえて、なかなか会えない。","en":"She seems to be busy, as it's hard to meet her.","romaji":"Kanojo wa isogashii to miete, nakanaka aenai."},{"jp":"田中さんは疲れているとみえて、早く帰りました。","en":"It seems that Tanaka-san was tired, as he went home early.","romaji":"Tanaka-san wa tsukarete iru to miete, hayaku kaerimashita."},{"jp":"その店は人気だとみえて、いつも行列ができている。","en":"That shop seems to be popular, as there is always a line.","romaji":"Sono mise wa ninki da to miete, itsumo retsu ga dekite iru."}],"example":"彼は運動が得意とみえて、毎日ジムに行っています。","exampleMeaning":"He seems to be good at exercise, as he goes to the gym every day."},{"pattern":"～とみられる","meaning":"It is considered that; It is thought that; It is believed that","formation":"Verb-casual + とみられる, Noun + とみられる","examples":[{"jp":"彼の行動は無責任とみられる。","en":"His behavior is considered irresponsible.","romaji":"Kare no koudou wa musekinin to mirareru."},{"jp":"この絵はピカソの作品とみられている。","en":"This painting is believed to be a work of Picasso.","romaji":"Kono e wa pikaso no sakuhin to mirareteiru."},{"jp":"地震の後、被害はさらに増加するとみられる。","en":"After the earthquake, damage is expected to increase further.","romaji":"Jishin no ato, higai wa sara ni zouka suru to mirareru."},{"jp":"週末は天気が良くなるとみられる。","en":"The weather is expected to improve on the weekend.","romaji":"Shuumatsu wa tenki ga yoku naru to mirareru."}],"example":"彼の行動は無責任とみられる。","exampleMeaning":"His behavior is considered irresponsible."},{"pattern":"～とみると (〜to miru to)","meaning":"Expresses the concept of 'when one sees it as', 'viewed as', or 'considering'.","formation":"Verb-casual + とみると, い-Adjective + とみると, な-Adjective + だとみると, Noun + だとみると","examples":[{"jp":"この問題を数学の視点でとみると、解決策が見えてきます。","en":"When one sees this problem from a mathematical perspective, a solution begins to emerge.","romaji":"Kono mondai o suugaku no shiten de to miru to, kaiketsusaku ga miete kimasu."},{"jp":"彼女が優秀な学生だとみると、その賞をもらったのは当然です。","en":"Considering she is an excellent student, it's natural that she received that award.","romaji":"Kanojo ga yuushuuna gakusei da to miru to, sono shou o moratta no wa touzen desu."},{"jp":"彼が新入社員だとみると、その成果は素晴らしいです。","en":"Viewing him as a new employee, his achievements are exceptional.","romaji":"Kare ga shinnyuushain da to miru to, sono seika wa subarashii desu."},{"jp":"このパンダが絶滅危惧種だとみると、保護が必要です。","en":"Considering this panda is an endangered species, it needs protection.","romaji":"Kono panda ga zetsumetsu kigushu da to miru to, hogo ga hitsuyou desu."}],"example":"この問題を数学の視点でとみると、解決策が見えてきます。","exampleMeaning":"When one sees this problem from a mathematical perspective, a solution begins to emerge."},{"pattern":"どんなに～うが","meaning":"Expresses 'no matter how much...', 'even if...'.","formation":"どんなに + Verb-volitional + うが, どんなに + い-Adjective(～かろう) + が, どんなに + な-Adjective + だろうが","examples":[{"jp":"どんなに頑張ろうが、彼の速さには追いつけない。","en":"No matter how hard I try, I can't catch up with his speed.","romaji":"Donna ni ganbarou ga, kare no hayasa ni wa oitsukenai."},{"jp":"どんなに食べようが、彼女は太らない。","en":"No matter how much she eats, she doesn't gain weight.","romaji":"Donna ni tabeyou ga, kanojo wa futoranai."},{"jp":"どんなに寒かろうが、彼は毎日ジョギングをします。","en":"No matter how cold it is, he goes jogging every day.","romaji":"Donna ni samukarou ga, kare wa mainichi jogging wo shimasu."},{"jp":"どんなに暑かろうが、エアコンは使いません。","en":"No matter how hot it is, I don't use air conditioning.","romaji":"Donna ni atsukarou ga, eakon wa tsukaimasen."}],"example":"どんなに頑張ろうが、彼の速さには追いつけない。","exampleMeaning":"No matter how hard I try, I can't catch up with his speed."},{"pattern":"～と言わんばかりに (〜to iwan bakari ni)","meaning":"Indicates an action or behavior that strongly implies a certain unspoken message or feeling.","formation":"Verb-volitional + と言わんばかりに, い-Adjective + と言わんばかりに, な-Adjective + だと言わんばかりに, Noun + だと言わんばかりに","examples":[{"jp":"彼女は優勝したと言わんばかりに笑った。","en":"She laughed as if to say she won.","romaji":"Kanojo wa yuushou shita to iwan bakari ni waratta."},{"jp":"彼は倒れると言わんばかりの疲労感があった。","en":"He was so fatigued it was as if he might collapse.","romaji":"Kare wa taoreru to iwan bakari no hiroukan ga atta."},{"jp":"彼女は雨の日を恐れていて、晴れてほしいと言わんばかりに窓の外を見つめていた。","en":"She was afraid of rainy days, almost as if to say she wanted it to be sunny, as she gazed out the window.","romaji":"Kanojo wa ame no hi o osorete ite, harete hoshii to iwan bakari ni mado no soto o mitsumete ita."},{"jp":"彼の行動は、誰にも信じてもらえないと言わんばかりだった。","en":"His behavior was as if to say that no one would believe him.","romaji":"Kare no koudou wa, dare ni mo shinjite moraenai to iwan bakari datta."}],"example":"彼女は優勝したと言わんばかりに笑った。","exampleMeaning":"She laughed as if to say she won."},{"pattern":"～と言わんばかりの Noun","meaning":"Expresses the concept of 'as if to say'; 'almost says'; 'suggests'.","formation":"Verb-plain form + と言わんばかりの Noun","examples":[{"jp":"田中さんは嬉しくて飛び上がると言わんばかりの笑顔を見せた。","en":"Tanaka showed a smile as if to say he was so happy he could jump for joy.","romaji":"Tanaka-san wa ureshikute tobiagaru to iwan bakari no egao wo miseta."},{"jp":"彼女は僕に話しかけると言わんばかりの視線を送った。","en":"She sent me glances as if to say she wanted to speak with me.","romaji":"Kanojo wa boku ni hanashikakeru to iwan bakari no shisen wo okutta."},{"jp":"その老人は寒さで震えていると言わんばかりの姿を見せていた。","en":"The old man was shivering as if to say he was freezing from the cold.","romaji":"Sono roujin wa samusa de furueteiru to iwan bakari no sugata wo miseteita."},{"jp":"彼の体は緊張で固まっていると言わんばかりの風格を放っている。","en":"He exudes an air as if his body were stiff from tension.","romaji":"Kare no karada wa kinchou de katamatteiru to iwan bakari no fuukaku wo hanatteiru."}],"example":"田中さんは嬉しくて飛び上がると言わんばかりの笑顔を見せた。","exampleMeaning":"Tanaka showed a smile as if to say he was so happy he could jump for joy."},{"pattern":"～ながらに","meaning":"Expresses a state or condition continuing just as it is (e.g. 'from birth', 'while crying', 'in the old way').","formation":"Common set phrases: 生まれながらに, 涙ながらに, 昔ながらに, 子供ながらに, etc.","examples":[{"jp":"彼女は生まれながらにして優れた音感を持っている。","en":"She has had an excellent sense of pitch from birth.","romaji":"Kanojo wa umare nagara ni shite sugureta onkan o motte iru."},{"jp":"彼は子供ながらに大人の会話を理解していた。","en":"Even though he was just a child, he understood adult conversations.","romaji":"Kare wa kodomo nagara ni otona no kaiwa o rikaishite ita."},{"jp":"彼女は涙ながらに真実を訴えた。","en":"She pleaded the truth while in tears.","romaji":"Kanojo wa namida nagara ni shinjitsu o uttaeta."},{"jp":"私たちは昔ながらに伝わる祭りを大切にしている。","en":"We cherish the traditional festival that has been passed down unchanged from old times.","romaji":"Watashi-tachi wa mukashi nagara ni tsutawaru matsuri o taisetsu ni shite iru."}],"example":"彼女は生まれながらにして優れた音感を持っている。","exampleMeaning":"She has had an excellent sense of pitch from birth."},{"pattern":"～ながらの Noun (〜nagara no Noun)","meaning":"Indicates one action or state happening at the same time as the noun in question (e.g. 'dinner while watching TV').","formation":"Verb-ますstem (or plain minus る) + ながら + の + Noun","examples":[{"jp":"テレビを見ながらの夕食は、子供たちにとって楽しいだろう。","en":"Eating dinner while watching TV might be fun for the children.","romaji":"Terebi o mi-nagara no yuushoku wa, kodomotachi ni totte tanoshii darou."},{"jp":"地図を読みながらの運転は危険です。","en":"Driving while reading a map is dangerous.","romaji":"Chizu o yomi-nagara no unten wa kiken desu."},{"jp":"散歩しながらの会話はリラックスできます。","en":"Talking during a walk can be relaxing.","romaji":"Sanpo shi-nagara no kaiwa wa rirakkusu dekimasu."},{"jp":"音楽を聴きながらの勉強は集中力を高めるかもしれません。","en":"Studying while listening to music might improve concentration.","romaji":"Ongaku o kiki-nagara no benkyou wa shuuchuuryoku o takameru kamoshiremasen."}],"example":"テレビを見ながらの夕食は、子供たちにとって楽しいだろう。","exampleMeaning":"Eating dinner while watching TV might be fun for the children."},{"pattern":"～ながらも (〜nagara mo)","meaning":"Means 'even though' or 'despite'.","formation":"Verb stem + ながらも, い-Adjective + ながらも, な-Adjective/Noun + ながらも","examples":[{"jp":"彼は貧しいながらも、幸せな生活を送っている。","en":"Despite being poor, he leads a happy life.","romaji":"Kare wa mazushii nagara mo, shiawase na seikatsu o okutte iru."},{"jp":"僕は忙しいながらも、毎日運動しています。","en":"Even though I am busy, I exercise every day.","romaji":"Boku wa isogashii nagara mo, mainichi undou shiteimasu."},{"jp":"病気ながらも、彼は仕事を続けました。","en":"Despite being sick, he continued working.","romaji":"Byouki nagara mo, kare wa shigoto o tsuzukemashita."},{"jp":"雨が降っているながらも、彼は散歩に出かけた。","en":"Even though it was raining, he went for a walk.","romaji":"Ame ga futte iru nagara mo, kare wa sanpo ni dekaketa."}],"example":"彼は貧しいながらも、幸せな生活を送っている。","exampleMeaning":"Despite being poor, he leads a happy life."},{"pattern":"～なくはない (〜naku wa nai)","meaning":"Expresses the idea 'it's not that it's impossible' or 'it's not that I can't'.","formation":"Verb-ないform + なくはない, い-Adjective－い + くはない, な-Adjective + ではなくはない, Noun + ではなくはない","examples":[{"jp":"それを終えるのは難しくなくはない。","en":"It's not that it's impossible to finish it.","romaji":"Sore o oeru no wa muzukashiku naku wa nai."},{"jp":"彼に話すのは怖くなくはない。","en":"It's not that I'm entirely unafraid to talk to him.","romaji":"Kare ni hanasu no wa kowaku naku wa nai."},{"jp":"映画を見に行く時間がなくはない。","en":"It's not that I don't have time to go see a movie.","romaji":"Eiga o mi ni iku jikan ga naku wa nai."},{"jp":"日本語で講演するのは難しくなくはない。","en":"It's not impossible to give a lecture in Japanese, but it won't be easy.","romaji":"Nihongo de kouen suru no wa muzukashiku naku wa nai."}],"example":"それを終えるのは難しくなくはない。","exampleMeaning":"It's not that it's impossible to finish it."},{"pattern":"～なくもない (〜naku mo nai)","meaning":"Expresses 'not impossible' or 'might as well'.","formation":"Verb-ないform + なくもない, い-Adjective－い + くもない, な-Adjective + でもない, Noun + でもない","examples":[{"jp":"彼がもうすぐ戻るなら、待つなくもない。","en":"If he’s coming back soon, waiting wouldn’t be a bad idea.","romaji":"Kare ga mou sugu modoru nara, matsu naku mo nai."},{"jp":"この本が役に立つなら、買うなくもない。","en":"If this book is useful, it might not be a bad idea to buy it.","romaji":"Kono hon ga yaku ni tatsu nara, kau naku mo nai."},{"jp":"天気が良ければ、ピクニックに行くなくもない。","en":"If the weather is nice, it wouldn't be impossible for us to go on a picnic.","romaji":"Tenki ga yokereba, pikunikku ni iku naku mo nai."},{"jp":"そのプロジェクトが成功すれば、プロモーションもあり得なくもない。","en":"If that project succeeds, a promotion might not be out of the question.","romaji":"Sono purojekuto ga seikou sureba, puromooshon mo arienaku mo nai."}],"example":"彼がもうすぐ戻るなら、待つなくもない。","exampleMeaning":"If he’s coming back soon, waiting wouldn’t be a bad idea."},{"pattern":"～なら～なりに","meaning":"Means 'if it is X, then it's X in its own way', emphasizing unique qualities.","formation":"Noun/Adjective + なら + (same Noun/Adjective) + なりに","examples":[{"jp":"彼はまだ初心者なら初心者なりに頑張っている。","en":"Since he’s still a beginner, he’s doing his best in his own beginner way.","romaji":"Kare wa mada shoshinsha nara shoshinsha nari ni ganbatteiru."},{"jp":"この料理は辛いなら辛いなりに美味しい。","en":"If this dish is spicy, it’s delicious in its own spicy way.","romaji":"Kono ryouri wa karai nara karai nari ni oishii."},{"jp":"あの人は変なら変なりに面白い。","en":"If that person is strange, they’re interesting in their own strange way.","romaji":"Ano hito wa hen nara hen nari ni omoshiroi."},{"jp":"この町は小さいなら小さいなりに楽しい。","en":"If this town is small, it’s fun in its own small way.","romaji":"Kono machi wa chiisai nara chiisai nari ni tanoshii."}],"example":"彼はまだ初心者なら初心者なりに頑張っている。","exampleMeaning":"Since he’s still a beginner, he’s doing his best in his own beginner way."},{"pattern":"～には及ばない (〜ni wa oyobanai)","meaning":"Means 'no need to go that far' or 'not necessary'.","formation":"Verb-dictionary form + には及ばない","examples":[{"jp":"ファーストクラスに乗るには及ばない、エコノミーでも十分だ。","en":"There’s no need to go as far as flying first class; economy is enough.","romaji":"Faasuto kurasu ni noru ni wa oyobanai, ekonomii demo juubun da."},{"jp":"毎回会うたびにギフトを持って行くには及ばない。","en":"There’s no need to bring a gift every time you meet her.","romaji":"Maikai au tabi ni gifuto o motte iku ni wa oyobanai."},{"jp":"その問題は先生に聞くには及ばない、自分で解決できる。","en":"That issue doesn’t warrant asking the teacher; you can solve it yourself.","romaji":"Sono mondai wa sensei ni kiku ni wa oyobanai, jibun de kaiketsu dekiru."},{"jp":"小さな失敗のために、あんなに辛辣な言葉を使うには及ばないだろう。","en":"For such a small mistake, there’s no need to use such harsh words.","romaji":"Chiisana shippai no tame ni, anna ni shinratsu na kotoba o tsukau ni wa oyobanai darou."}],"example":"ファーストクラスに乗るには及ばない、エコノミーでも十分だ。","exampleMeaning":"There’s no need to go as far as flying first class; economy is enough."},{"pattern":"～に堪えない","meaning":"Indicates something is unbearable or not worth doing (e.g., 'unbearable to watch', 'unbearable to listen to').","formation":"Verb-dictionary form + に堪えない, Noun + に堪えない","examples":[{"jp":"彼の冗談は聞くに堪えない。","en":"His jokes are unbearable to listen to.","romaji":"Kare no joudan wa kiku ni taenai."},{"jp":"その映画は見るに堪えないほどひどい出来だ。","en":"That movie is so bad that it’s unbearable to watch.","romaji":"Sono eiga wa miru ni taenai hodo hidoi deki da."},{"jp":"この小説は読むに堪えないほど退屈だ。","en":"This novel is so boring that it’s unbearable to read.","romaji":"Kono shousetsu wa yomu ni taenai hodo taikutsu da."},{"jp":"彼の行動は見るに堪えない。","en":"His behavior is unbearable to watch.","romaji":"Kare no koudou wa miru ni taenai."}],"example":"彼の冗談は聞くに堪えない。","exampleMeaning":"His jokes are unbearable to listen to."},{"pattern":"～に堪える","meaning":"Used to say that something is 'worth doing' or 'can stand up to' something (the positive counterpart of ～に堪えない).","formation":"Verb-dictionary form + に堪える, Noun + に堪える","examples":[{"jp":"彼の歌声は聞くに堪える。","en":"His singing voice is worth listening to.","romaji":"Kare no utagoe wa kiku ni taeru."},{"jp":"この小説は読むに堪える内容だ。","en":"This novel is worth reading.","romaji":"Kono shousetsu wa yomu ni taeru naiyou da."},{"jp":"あの映画は見るに堪える名作だ。","en":"That movie is a masterpiece worth watching.","romaji":"Ano eiga wa miru ni taeru meisaku da."},{"jp":"彼の意見は十分に参考に堪える。","en":"His opinion is definitely worth considering.","romaji":"Kare no iken wa juubun ni sankou ni taeru."}],"example":"彼の歌声は聞くに堪える。","exampleMeaning":"His singing voice is worth listening to."},{"pattern":"～に耐える","meaning":"To endure or withstand something; 'endure', 'withstand', 'tolerate'.","formation":"Noun + に耐える","examples":[{"jp":"彼は厳しい修行に耐えた。","en":"He endured the harsh training.","romaji":"Kare wa kibishii shugyou ni taeta."},{"jp":"この橋は強風に耐えられる。","en":"This bridge can withstand strong winds.","romaji":"Kono hashi wa kyoufuu ni taerareru."},{"jp":"彼女は苦しみに耐えた。","en":"She endured the pain.","romaji":"Kanojo wa kurushimi ni taeta."},{"jp":"この建物は地震に耐えることができます。","en":"This building can withstand an earthquake.","romaji":"Kono tatemono wa jishin ni taeru koto ga dekimasu."}],"example":"彼は厳しい修行に耐えた。","exampleMeaning":"He endured the harsh training."},{"pattern":"～に至った (〜ni itatta)","meaning":"Expresses the outcome or final conclusion of a process; 'reached the point', 'led to'.","formation":"Verb-てform + に至った or Noun / Verb-dictionary + に至る (more general).","examples":[{"jp":"彼は練習を重ねて、ついにプロのギタリストに至った。","en":"After repeated practice, he finally became a professional guitarist.","romaji":"Kare wa renshuu o kasanete, tsui ni puro no gitarisuto ni itatta."},{"jp":"調査を進めるうちに、驚くべき結論に至った。","en":"As the investigation progressed, it led to a surprising conclusion.","romaji":"Chousa o susumeru uchi ni, odoroku beki ketsuron ni itatta."},{"jp":"この問題はついに国際的な対立に至った。","en":"This issue finally led to an international conflict.","romaji":"Kono mondai wa tsui ni kokusaiteki na tairitsu ni itatta."},{"jp":"たくさんの失敗を経て、成功に至った。","en":"After many failures, I finally achieved success.","romaji":"Takusan no shippai o hete, seikou ni itatta."}],"example":"彼は練習を重ねて、ついにプロのギタリストに至った。","exampleMeaning":"After repeated practice, he finally became a professional guitarist."},{"pattern":"～に越したことはない (〜ni koshita koto wa nai)","meaning":"Expresses that something is the best or most desirable course of action; 'nothing better than...'.","formation":"Verb (dictionary form) + に越したことはない, い-Adjective + に越したことはない, な-Adjective/Noun + である + に越したことはない","examples":[{"jp":"早く準備するに越したことはない。","en":"It's best to prepare early.","romaji":"Hayaku junbi suru ni koshita koto wa nai."},{"jp":"新鮮な食材を使うに越したことはない。","en":"There's nothing better than using fresh ingredients.","romaji":"Shinsen na shokuzai o tsukau ni koshita koto wa nai."},{"jp":"安全運転に越したことはない。","en":"Safe driving is always best.","romaji":"Anzen unten ni koshita koto wa nai."},{"jp":"健康的な生活を送るに越したことはない。","en":"There's nothing better than leading a healthy lifestyle.","romaji":"Kenkouteki na seikatsu o okuru ni koshita koto wa nai."}],"example":"早く準備するに越したことはない。","exampleMeaning":"It's best to prepare early."},{"pattern":"～に難くない","meaning":"Expresses 'not difficult to ~' in a formal/literary sense; e.g., 'not hard to imagine/understand'.","formation":"Verb-dictionary form + に難くない (commonly with 想像する, 理解する, 察する, etc.)","examples":[{"jp":"彼の喜びは想像に難くない。","en":"It's not hard to imagine his delight.","romaji":"Kare no yorokobi wa souzou ni katakunai."},{"jp":"この結果が彼女を失望させたことは理解に難くない。","en":"It's not difficult to understand that this outcome disappointed her.","romaji":"Kono kekka ga kanojo o shitsubou saseta koto wa rikai ni katakunai."},{"jp":"彼が怒る気持ちは察するに難くない。","en":"It's not hard to guess why he is angry.","romaji":"Kare ga okoru kimochi wa sassuru ni katakunai."},{"jp":"このような状況が起こった理由は想像に難くない。","en":"It's not hard to imagine why this situation occurred.","romaji":"Kono youna joukyou ga okotta riyuu wa souzou ni katakunai."}],"example":"彼の喜びは想像に難くない。","exampleMeaning":"It's not hard to imagine his delight."},{"pattern":"～のは Noun ぐらいのものだ (〜no wa Noun gurai no mono da)","meaning":"Conveys that 'only (Noun) is the case' or 'nothing but (Noun)'.","formation":"Verb-casual + のは + Noun + ぐらいのものだ, い-Adjective + のは + Noun + ぐらいのものだ, etc.","examples":[{"jp":"この小説を読むのは暇つぶしぐらいのものだ。","en":"Reading this novel is nothing but a way to kill time.","romaji":"Kono shousetsu o yomu no wa hima tsubushi gurai no mono da."},{"jp":"今日の夕食で良かったのはピザぐらいのものだ。","en":"About the only good thing at tonight's dinner was the pizza.","romaji":"Kyou no yuushoku de yokatta no wa piza gurai no mono da."},{"jp":"この映画を見るのは時間の無駄ぐらいのものだ。","en":"Watching this movie is nothing but a waste of time.","romaji":"Kono eiga o miru no wa jikan no muda gurai no mono da."},{"jp":"彼と話すのはストレスぐらいのものだ。","en":"Talking to him is nothing but stressful.","romaji":"Kare to hanasu no wa sutoresu gurai no mono da."}],"example":"この小説を読むのは暇つぶしぐらいのものだ。","exampleMeaning":"Reading this novel is nothing but a way to kill time."},{"pattern":"～ば～ものを","meaning":"Expresses regret or a missed opportunity: 'if only', 'had I but...'.","formation":"Verb-ば + Verb-past + ものを, い-Adjective + ければ + ものを, な-Adjective/Noun + であれば + ものを, etc.","examples":[{"jp":"早く起きれば、遅刻しなかったものを。","en":"If only I'd woken up early, I wouldn't have been late.","romaji":"Hayaku okireba, chikoku shinakatta mono o."},{"jp":"もっと頑張れば、テストに合格したものを。","en":"If only I'd tried harder, I would have passed the test.","romaji":"Motto ganbareba, tesuto ni goukaku shita mono o."},{"jp":"お金があれば、新しい車を買ったものを。","en":"If only I had the money, I would have bought a new car.","romaji":"Okane ga areba, atarashii kuruma o katta mono o."},{"jp":"友達がいれば、一緒に遊んだものを。","en":"If only I had a friend, I would have hung out together.","romaji":"Tomodachi ga ireba, issho ni asonda mono o."}],"example":"早く起きれば、遅刻しなかったものを。","exampleMeaning":"If only I'd woken up early, I wouldn't have been late."},{"pattern":"～びた","meaning":"A suffix meaning “looking or seeming like ~” (often appears with nouns/adjectives).","formation":"[Noun/Adjective stem] + びた (forms a 連体形 modifier, e.g., 大人びた人 “an adult-like person”)","examples":[{"jp":"大人びた考え方をする子供","en":"A child who thinks in a very grown-up way","romaji":"Otonabita kangaekata o suru kodomo"},{"jp":"古びたカバンを捨てられない。","en":"I can't throw away that old, worn-looking bag.","romaji":"Furubita kaban o suterarenai."},{"jp":"田舎びた雰囲気がこの町の魅力だ。","en":"The countrified atmosphere is this town’s charm.","romaji":"Inakabita fun'iki ga kono machi no miryoku da."},{"jp":"彼女は少し大人びた服装をしている。","en":"She’s dressed in a slightly grown-up style.","romaji":"Kanojo wa sukoshi otonabita fukusou o shite iru."}],"example":"大人びた考え方をする子供","exampleMeaning":"A child who thinks in a very grown-up way"},{"pattern":"～びる (〜biru)","meaning":"A suffix meaning “to appear/to become ~,” often used with certain adjectives or nouns.","formation":"Adjective/Noun + びる (to form a verb)","examples":[{"jp":"彼女は年齢より大人びている。","en":"She seems older than her actual age.","romaji":"Kanojo wa nenrei yori otona bite iru."},{"jp":"この建物はすっかり古びている。","en":"This building has become completely old and worn.","romaji":"Kono tatemono wa sukkari furubite iru."},{"jp":"彼は都会育ちなのに、少し田舎びている話し方をする。","en":"Even though he grew up in the city, he speaks in a somewhat country-like way.","romaji":"Kare wa tokai sodachi na noni, sukoshi inakabite iru hanashikata o suru."},{"jp":"子供が急に大人びる瞬間を見ると驚く。","en":"It’s surprising when you see a child suddenly act grown-up.","romaji":"Kodomo ga kyuu ni otona biru shunkan o miru to odoroku."}],"example":"彼女は年齢より大人びている。","exampleMeaning":"She seems older than her actual age."},{"pattern":"～ぶった","meaning":"Often appears as a past form of ～ぶる, meaning 'acted/pretended like ~' (or literally 'hit/bashed', depending on context).","formation":"Noun/Adjective + ぶる → ぶった (past tense), e.g., 偉そうぶった, 大人ぶった","examples":[{"jp":"彼は何でも知っているかのようにぶった態度を取る。","en":"He takes on an attitude as though he knows everything.","romaji":"Kare wa nandemo shitteiru ka no you ni butta taido o toru."},{"jp":"偉そうぶった物言いをされると、少し腹が立つ。","en":"It irritates me when he speaks in such a high-and-mighty way.","romaji":"Erasou butta monoii o sareru to, sukoshi hara ga tatsu."},{"jp":"彼女は大人ぶった口調で話しているが、実はまだ高校生だ。","en":"She’s speaking in a very grown-up manner, but she’s actually still in high school.","romaji":"Kanojo wa otona butta kuchou de hanashite iru ga, jitsu wa mada koukousei da."},{"jp":"いい子ぶった態度を取らなくてもいいよ。","en":"You don't have to pretend to be such a goody-goody.","romaji":"Ii ko butta taido o toranakute mo ii yo."}],"example":"彼は何でも知っているかのようにぶった態度を取る。","exampleMeaning":"He takes on an attitude as though he knows everything."},{"pattern":"～ぶって (〜butte)","meaning":"Te-form of ～ぶる, meaning 'acting/pretending to be ~'.","formation":"Noun/Adjective + ぶる → ぶって (te-form)","examples":[{"jp":"彼は何でも知ったかぶって話をする。","en":"He talks as if he knows everything.","romaji":"Kare wa nandemo shittaka butte hanashi o suru."},{"jp":"彼女は何も知らないふりをしてぶっていたが、本当は全部わかっている。","en":"She was acting like she didn’t know anything, but in reality, she understands it all.","romaji":"Kanojo wa nanimo shiranai furi o shite butte ita ga, hontou wa zenbu wakatte iru."},{"jp":"彼はいつも偉そうぶって周りに指図している。","en":"He’s always bossing people around as if he’s so important.","romaji":"Kare wa itsumo erasou butte mawari ni sashizu shite iru."},{"jp":"大人ぶっているけど、まだ子供っぽいところがある。","en":"He acts grown-up, but he still has some childish traits.","romaji":"Otona butte iru kedo, mada kodomoppoi tokoro ga aru."}],"example":"彼は何でも知ったかぶって話をする。","exampleMeaning":"He talks as if he knows everything."},{"pattern":"～ぶり (〜buri)","meaning":"Expresses the amount of time elapsed since doing something last.","formation":"Time expression + ぶり","examples":[{"jp":"三年ぶりに彼に会いました。","en":"I met him for the first time in three years.","romaji":"San-nen buri ni kare ni aimashita."},{"jp":"一週間ぶりにジムに行った。","en":"I went to the gym for the first time in a week.","romaji":"Isshuukan buri ni jimu ni itta."},{"jp":"一ヶ月ぶりに彼からの手紙が来た。","en":"I received a letter from him for the first time in a month.","romaji":"Ikkagetsu buri ni kare kara no tegami ga kita."},{"jp":"五年ぶりに雪が降った。","en":"It snowed for the first time in five years.","romaji":"Go-nen buri ni yuki ga futta."}],"example":"三年ぶりに彼に会いました。","exampleMeaning":"I met him for the first time in three years."},{"pattern":"～ぶる (〜buru)","meaning":"Used when someone is acting or pretending to be something they are not (often a negative connotation).","formation":"Noun / (Adjective stem) + ぶる","examples":[{"jp":"彼はあたかも知っているかのように学者ぶる。","en":"He acts like a scholar, as if he knows everything.","romaji":"Kare wa atakamo shitteiru ka no you ni gakusha buru."},{"jp":"女優ぶるのはやめて、自分自身でいろ。","en":"Stop acting like you’re an actress and just be yourself.","romaji":"Joyu buru no wa yamete, jibun jishin de iro."},{"jp":"彼女は常にお嬢様ぶっている。","en":"She’s always putting on the airs of a refined lady.","romaji":"Kanojo wa tsune ni ojou-sama butte iru."},{"jp":"私がいじめられていると無邪気ぶる彼女を見て、怒りがこみ上げた。","en":"Seeing her act innocent while I was being bullied made my anger surge.","romaji":"Watashi ga ijimerarete iru to mujaki buru kanojo o mite, ikari ga komiageta."}],"example":"彼はあたかも知っているかのように学者ぶる。","exampleMeaning":"He acts like a scholar, as if he knows everything."},{"pattern":"～までだ","meaning":"Expresses a limit or extent; 'it's only up to...', 'no more than...'.","formation":"Verb (dictionary/ない form) + までだ, い-Adjective + までだ, Noun + までだ","examples":[{"jp":"彼とは友達までだ。それ以上の関係ではありません。","en":"With him, it's only friendship—nothing more.","romaji":"Kare to wa tomodachi made da. Sore ijou no kankei dewa arimasen."},{"jp":"飲み放題は9時までだ。それ以降は追加料金が必要だ。","en":"The all-you-can-drink deal is only until nine. After that, there's an extra charge.","romaji":"Nomihoudai wa kuji made da. Sore ikou wa tsuika ryoukin ga hitsuyou da."},{"jp":"私たちの情報は昨日までだ。それ以降のアップデートはありません。","en":"Our information only goes up to yesterday; there are no further updates.","romaji":"Watashitachi no jouhou wa kinou made da. Sore ikou no appudeeto wa arimasen."},{"jp":"彼の知識は中学生レベルまでだ。それ以上は理解できない。","en":"His knowledge is only at a junior-high level. He can't understand anything more advanced.","romaji":"Kare no chishiki wa chuugakusei reberu made da. Sore ijou wa rikai dekinai."}],"example":"彼とは友達までだ。それ以上の関係ではありません。","exampleMeaning":"With him, it's only friendship—nothing more."},{"pattern":"～もなんでもない (〜mo nandemonai)","meaning":"Used to dismiss or negate something’s importance; 'it’s nothing at all', 'it doesn’t matter'.","formation":"Verb-dictionary form + もなんでもない, い-Adjective + もなんでもない, な-Adjective + なもなんでもない, Noun + もなんでもない","examples":[{"jp":"100万円を負けるもなんでもない。","en":"Losing a million yen is no big deal at all.","romaji":"Hyaku man-en o makeru mo nandemonai."},{"jp":"彼が社長だもなんでもない。","en":"It doesn't matter one bit that he's the president.","romaji":"Kare ga shachou da mo nandemonai."},{"jp":"あなたが来ないもなんでもない。","en":"It doesn't matter at all if you don't come.","romaji":"Anata ga konai mo nandemonai."},{"jp":"それが美しいもなんでもない。","en":"It doesn't matter at all whether it's beautiful.","romaji":"Sore ga utsukushii mo nandemonai."}],"example":"100万円を負けるもなんでもない。","exampleMeaning":"Losing a million yen is no big deal at all."},{"pattern":"～ものとして","meaning":"Indicates an assumption or supposition; 'assuming', 'under the assumption that'.","formation":"Verb-casual + ものとして, い-Adjective + ものとして, な-Adjective + なものとして, Noun + のものとして","examples":[{"jp":"雨が降るものとして、傘を持って行きました。","en":"Assuming it would rain, I took an umbrella.","romaji":"Ame ga furu mono to shite, kasa o motte ikimashita."},{"jp":"彼が病気なものとして、代わりに私が出席した。","en":"On the assumption that he was sick, I attended in his place.","romaji":"Kare ga byouki na mono to shite, kawari ni watashi ga shusseki shita."},{"jp":"このケーキが美味しいものとして、みんなに分けよう。","en":"Let’s share this cake, assuming it’s delicious.","romaji":"Kono keeki ga oishii mono to shite, minna ni wakeyou."},{"jp":"彼女が学生のものとして、学割を適用しました。","en":"Assuming she is a student, I applied the student discount.","romaji":"Kanojo ga gakusei no mono to shite, gakuwari o tekiyou shimashita."}],"example":"雨が降るものとして、傘を持って行きました。","exampleMeaning":"Assuming it would rain, I took an umbrella."},{"pattern":"～んがために (〜n ga tame ni)","meaning":"Emphasizes the reason or purpose for an action; 'in order to', 'for the sake of'.","formation":"Verb-negative stem + んがために","examples":[{"jp":"健康を保たんがために、毎日運動をしています。","en":"I exercise daily in order to maintain my health.","romaji":"Kenkou o tamotan ga tame ni, mainichi undou o shite imasu."},{"jp":"合格せんがために、一生懸命勉強します。","en":"I study hard in order to pass.","romaji":"Goukaku sen ga tame ni, isshoukenmei benkyou shimasu."},{"jp":"明日の試験に備えんがため、今夜は早く寝るつもりです。","en":"I plan to go to bed early so I can prepare for tomorrow’s exam.","romaji":"Ashita no shiken ni sonaen ga tame, kon'ya wa hayaku neru tsumori desu."},{"jp":"彼女の笑顔を見んがために、毎日会いに行きます。","en":"I go to see her every day in order to see her smile.","romaji":"Kanojo no egao o min ga tame ni, mainichi ai ni ikimasu."}],"example":"健康を保たんがために、毎日運動をしています。","exampleMeaning":"I exercise daily in order to maintain my health."},{"pattern":"～んばかりに (〜n bakari ni)","meaning":"Indicates 'as though about to ~' or 'as if to say ~'.","formation":"Verb-negative stem + ん + ばかりに","examples":[{"jp":"彼は何も知らんばかりに、私の質問を無視した。","en":"He ignored my question as if he didn’t know anything.","romaji":"Kare wa nanimo shir-an bakari ni, watashi no shitsumon o mushi shita."},{"jp":"その子は泣かんばかりに顔をしかめた。","en":"The child made a face as if he were about to cry.","romaji":"Sono ko wa nakan bakari ni kao o shikameta."},{"jp":"彼女は笑わんばかりに口元を押さえた。","en":"She covered her mouth as though she were about to burst out laughing.","romaji":"Kanojo wa warawan bakari ni kuchimoto o osaeta."},{"jp":"彼は退屈だと言わんばかりに、ため息を何度もついた。","en":"He sighed over and over as if to say he was bored.","romaji":"Kare wa taikutsu da to iwan bakari ni, tameiki o nando mo tsuita."}],"example":"彼は何も知らんばかりに、私の質問を無視した。","exampleMeaning":"He ignored my question as if he didn’t know anything."},{"pattern":"～差し支えない (〜sashitsukaenai)","meaning":"Indicates no problem or obstacle; 'it’s fine if...', 'there’s no issue'.","formation":"Verb-て form + も差し支えない, Noun + が差し支えない","examples":[{"jp":"多少遅くても差し支えないです。","en":"It’s no problem if you’re a bit late.","romaji":"Tashou osokute mo sashitsukaenai desu."},{"jp":"部屋が少し汚くても差し支えない。","en":"It doesn’t matter if the room is slightly messy.","romaji":"Heya ga sukoshi kitanakute mo sashitsukaenai."},{"jp":"雨が降っても差し支えない。","en":"It’s not an issue even if it rains.","romaji":"Ame ga futte mo sashitsukaenai."},{"jp":"彼がここにいることが差し支えないですか？","en":"Is it okay (no problem) for him to be here?","romaji":"Kare ga koko ni iru koto ga sashitsukaenai desu ka?"}],"example":"多少遅くても差し支えないです。","exampleMeaning":"It’s no problem if you’re a bit late."},{"pattern":"～折に (〜ori ni)","meaning":"Indicates the time or occasion when something happens; 'when', 'at the time of'.","formation":"Verb-dictionary form + 折に, Verb-た形 + 折に, Noun + の折に","examples":[{"jp":"父が病気の折に、私は留学していました。","en":"When my father was ill, I was studying abroad.","romaji":"Chichi ga byouki no ori ni, watashi wa ryuugaku shite imashita."},{"jp":"日本へ行く折に、お土産を買ってきてください。","en":"When you go to Japan, please buy souvenirs.","romaji":"Nihon e iku ori ni, omiyage o katte kite kudasai."},{"jp":"子供が寝ている折に、静かにしてください。","en":"Please be quiet when the child is sleeping.","romaji":"Kodomo ga nete iru ori ni, shizuka ni shite kudasai."},{"jp":"彼に会う折に、この手紙を渡してください。","en":"Please give him this letter when you see him.","romaji":"Kare ni au ori ni, kono tegami o watashite kudasai."}],"example":"父が病気の折に、私は留学していました。","exampleMeaning":"When my father was ill, I was studying abroad."},{"pattern":"～極まりない (〜kiwamarinai)","meaning":"Expresses an extreme state, often negative; 'utterly', 'extremely', 'boundlessly'.","formation":"な-Adjective（語幹）+ 極まりない, い-Adjective（連用形）+ こと + 極まりない, Noun + の極まりない","examples":[{"jp":"彼の失礼な態度は極まりない。","en":"His rude attitude is utterly beyond words.","romaji":"Kare no shitsurei na taido wa kiwamarinai."},{"jp":"その運転は危険極まりない。","en":"That driving is extremely dangerous.","romaji":"Sono unten wa kiken kiwamarinai."},{"jp":"彼女のわがままぶりは非常識極まりない。","en":"Her selfishness is utterly irrational.","romaji":"Kanojo no wagamama-buri wa hijoushiki kiwamarinai."},{"jp":"この部屋の汚さは不衛生極まりない。","en":"The filthiness of this room is extremely unsanitary.","romaji":"Kono heya no kitasa wa fueisei kiwamarinai."}],"example":"彼の失礼な態度は極まりない。","exampleMeaning":"His rude attitude is utterly beyond words."},{"pattern":"～極まる (〜kiwamaru)","meaning":"Also expresses an extreme degree or state, typically negative.","formation":"な-Adjective（語幹）+ 極まる, い-Adjective（連用形）+ こと + 極まる, etc.","examples":[{"jp":"彼の言動は失礼極まる。","en":"His words and actions are extremely rude.","romaji":"Kare no gendou wa shitsurei kiwamaru."},{"jp":"その態度は非常識極まる。","en":"That behavior is utterly irrational.","romaji":"Sono taido wa hijoushiki kiwamaru."},{"jp":"彼女の発言は無責任極まる。","en":"Her remark is extremely irresponsible.","romaji":"Kanojo no hatsugen wa musekinin kiwamaru."},{"jp":"このような誤解は遺憾極まる。","en":"Such a misunderstanding is exceedingly regrettable.","romaji":"Kono youna gokai wa ikan kiwamaru."}],"example":"彼の言動は失礼極まる。","exampleMeaning":"His words and actions are extremely rude."},{"pattern":"～足りない","meaning":"Expresses insufficiency or lack; 'not enough', 'insufficient'.","formation":"Noun + (が) 足りない, Verb-casual + ほど/だけ + (が) 足りない","examples":[{"jp":"私の日本語の能力はまだまだ足りない。","en":"My Japanese skills are still not enough.","romaji":"Watashi no nihongo no nouryoku wa madamada tarinai."},{"jp":"時間が足りないから、今すぐ行かなきゃ。","en":"We don't have enough time, so we must go right now.","romaji":"Jikan ga tarinai kara, ima sugu ikanakya."},{"jp":"彼の説明には詳細が足りない。","en":"His explanation lacks detail.","romaji":"Kare no setsumei ni wa shousai ga tarinai."},{"jp":"料理するための食材が足りない。","en":"There's not enough food to cook with.","romaji":"Ryouri suru tame no shokuzai ga tarinai."}],"example":"私の日本語の能力はまだまだ足りない。","exampleMeaning":"My Japanese skills are still not enough."},{"pattern":"～足る Noun (〜taru Noun)","meaning":"Indicates that something is worthy or sufficient to be called/used as ~; 'worthy of', 'enough to ~'.","formation":"Noun/Verb-dictionary form + に足る + Noun","examples":[{"jp":"彼は信頼に足る人物だ。","en":"He is a person worthy of trust.","romaji":"Kare wa shinrai ni taru jinbutsu da."},{"jp":"この小説は読むに足る価値がある。","en":"This novel is well worth reading.","romaji":"Kono shousetsu wa yomu ni taru kachi ga aru."},{"jp":"検討に足るデータが十分に集まった。","en":"We've gathered enough data to be worth examining.","romaji":"Kentou ni taru deeta ga juubun ni atsumatta."},{"jp":"彼の説明は信用に足るものだと思う。","en":"I think his explanation is worthy of trust.","romaji":"Kare no setsumei wa shinyou ni taru mono da to omou."}],"example":"彼は信頼に足る人物だ。","exampleMeaning":"He is a person worthy of trust."},{"pattern":"～限りだ (〜kagiri da)","meaning":"Expresses an extreme degree of emotion or reaction; 'I feel so ~', 'as ~ as can be'.","formation":"い-Adjective + 限りだ, な-Adjective + な/である + 限りだ, Noun + の + 限りだ","examples":[{"jp":"彼女が急に辞めてしまった。驚きの限りだ。","en":"She suddenly quit. I'm as shocked as can be.","romaji":"Kanojo ga kyuu ni yamete shimatta. Odoroki no kagiri da."},{"jp":"息子が成功した。嬉しい限りだ。","en":"My son succeeded. I'm so happy.","romaji":"Musuko ga seikou shita. Ureshii kagiri da."},{"jp":"こんなに綺麗な花が見られるなんて、幸せの限りだ。","en":"I'm as happy as can be to see such beautiful flowers.","romaji":"Konna ni kirei na hana ga mirareru nante, shiawase no kagiri da."},{"jp":"試験に合格できて、ほっとした限りだ。","en":"I passed the exam—what a relief!","romaji":"Shiken ni goukaku dekite, hotto shita kagiri da."}],"example":"彼女が急に辞めてしまった。驚きの限りだ。","exampleMeaning":"She suddenly quit. I'm as shocked as can be."}]
